import { instrumentLabelForKey } from './quality-instruments';

/**
 * Display labels for the repo Settings sections, keyed by the `?settings=`
 * section id. This is the single source for the section titles — SetupTab
 * renders its section headings from the same map so the breadcrumb crumb and
 * the Settings page can never drift.
 */
export const SETTINGS_SECTION_LABELS: Record<string, string> = {
  'working-together': 'Setup',
  capabilities: 'Capabilities',
  configuration: 'Configuration',
  pipeline: 'Pipeline',
};

/** Display labels for the work areas, keyed by the `?view=` value. */
export const WORK_AREA_LABELS: Record<string, string> = {
  plans: 'Plans',
  fixes: 'Fixes',
  spikes: 'Spikes',
};

/** Where a breadcrumb crumb navigates when clicked. `current` is the page you
 * are already on, so it is rendered as plain (non-interactive) text. */
export type CrumbTarget =
  | { kind: 'repos' }
  | { kind: 'repoMain' }
  | { kind: 'qualityTop' }
  | { kind: 'settingsTop' }
  | { kind: 'areaTop' }
  | { kind: 'current' };

export interface RepoCrumb {
  label: string;
  target: CrumbTarget;
}

export interface RepoBreadcrumbState {
  repoName: string;
  /** The `?view=` value (e.g. 'quality'); null/work-area = repo main page. */
  view: string | null;
  /** The `?analyser=` drill-down key, if a Quality analyser is open. */
  analyser: string | null;
  /** The `?item=` selected Plan/Fix/Spike slug, if one is open in a work area. */
  item: string | null;
  /** Whether the Settings inline view is open. */
  settingsOpen: boolean;
  /** The open Settings section id, if any. */
  settingsSection: string | null;
}

/**
 * Build the repo breadcrumb trail from the URL-derived nav state:
 *
 *   Repos / <name>                       (no known area in the URL)
 *   Repos / <name> / Fixes               (a work area)
 *   Repos / <name> / Fixes / <slug>      (a selected plan/fix/spike)
 *   Repos / <name> / Quality             (Quality top)
 *   Repos / <name> / Quality / <metric>  (analyser drill-down)
 *   Repos / <name> / Settings            (Settings top)
 *   Repos / <name> / Settings / <tab>    (settings section)
 *
 * The last crumb is always the current page (non-interactive); every earlier
 * crumb navigates one level up the hierarchy. An unknown analyser/section id
 * resolves to no detail crumb, so a stale deep link degrades to the area top
 * rather than showing a blank crumb.
 */
export function buildRepoCrumbs(state: RepoBreadcrumbState): RepoCrumb[] {
  const crumbs: RepoCrumb[] = [
    { label: 'Repos', target: { kind: 'repos' } },
    { label: state.repoName, target: { kind: 'repoMain' } },
  ];

  if (state.settingsOpen) {
    crumbs.push({ label: 'Settings', target: { kind: 'settingsTop' } });
    const sectionLabel = state.settingsSection
      ? SETTINGS_SECTION_LABELS[state.settingsSection]
      : undefined;
    if (sectionLabel) crumbs.push({ label: sectionLabel, target: { kind: 'current' } });
  } else if (state.view === 'quality') {
    crumbs.push({ label: 'Quality', target: { kind: 'qualityTop' } });
    const analyserLabel = state.analyser
      ? instrumentLabelForKey(state.analyser)
      : undefined;
    if (analyserLabel) crumbs.push({ label: analyserLabel, target: { kind: 'current' } });
  } else if (state.view && WORK_AREA_LABELS[state.view]) {
    crumbs.push({ label: WORK_AREA_LABELS[state.view], target: { kind: 'areaTop' } });
    if (state.item) crumbs.push({ label: state.item, target: { kind: 'current' } });
  }

  // The final crumb is the current page — render it as plain text.
  crumbs[crumbs.length - 1] = { ...crumbs[crumbs.length - 1], target: { kind: 'current' } };
  return crumbs;
}
