import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CheckCircle2, AlertTriangle, XCircle, MinusCircle, Activity, RefreshCw, Copy, Check } from 'lucide-react';
import { getSystemDoctor } from '../../services/api';
import type { CheckResult } from '../../types';

type LoadState =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'loaded'; checks: CheckResult[] };

/** Status a doctor row can carry — the system `CheckResult` statuses, which the
 *  repo-health rows reuse as a subset (pass/warn/fail). */
export type DoctorRowStatus = CheckResult['status'];

const statusIcon = (status: DoctorRowStatus): React.ReactNode => {
  switch (status) {
    case 'pass':
      return <CheckCircle2 className="h-5 w-5 flex-shrink-0 text-done" aria-label="passed" />;
    case 'warn':
      return <AlertTriangle className="h-5 w-5 flex-shrink-0 text-warn" aria-label="warning" />;
    case 'fail':
      return <XCircle className="h-5 w-5 flex-shrink-0 text-destructive" aria-label="failed" />;
    case 'skip':
      return <MinusCircle className="h-5 w-5 flex-shrink-0 text-subtle" aria-label="skipped" />;
  }
};

/**
 * One doctor check rendered as a row: status icon, name, message, optional
 * details, and a Copy-command button on non-passing rows that carry a `fix`.
 * Shared by the system-health panel and the repo Setup doctor page so both
 * speak the same row/Copy vocabulary.
 */
export const DoctorCheckRow: React.FC<{
  testId: string;
  status: DoctorRowStatus;
  name: string;
  message: string;
  details?: readonly string[];
  fix?: string;
}> = ({ testId, status, name, message, details, fix }) => (
  <li data-testid={testId} className="flex items-start gap-3">
    {statusIcon(status)}
    <div className="min-w-0">
      <p className="text-sm font-medium">{name}</p>
      <p className="text-sm text-muted-foreground">{message}</p>
      {details && details.length > 0 && (
        <ul className="mt-1 text-xs text-muted-foreground list-disc pl-4">
          {details.map((detail, i) => (
            <li key={i}>{detail}</li>
          ))}
        </ul>
      )}
      {status !== 'pass' && fix && <CopyCommandButton command={fix} />}
    </div>
  </li>
);

/** Aggregate one-line summary mirroring the CLI doctor report. */
const summarise = (checks: CheckResult[]): string => {
  const fails = checks.filter((c) => c.status === 'fail').length;
  const warns = checks.filter((c) => c.status === 'warn').length;
  if (fails === 0 && warns === 0) return 'All system checks passed';
  const parts: string[] = [];
  if (fails > 0) parts.push(`${fails} critical`);
  if (warns > 0) parts.push(`${warns} warning${warns === 1 ? '' : 's'}`);
  return parts.join(', ');
};

/**
 * Copies a check's suggested `fix:` command to the clipboard. System repairs
 * are print-only by backend policy, so the UI never runs them — it just hands
 * the user the command to paste. Shows a brief "Copied!" confirmation.
 *
 * The confirmation only appears when the clipboard write actually succeeds: a
 * false "Copied!" over a silently-failed write would leave the user pasting
 * nothing and the repair never running. The revert timer is cleared on unmount
 * (a row can disappear on Refresh before the window elapses).
 */
export const CopyCommandButton: React.FC<{ command: string; confirmMs?: number }> = ({
  command,
  confirmMs = 2000,
}) => {
  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    },
    [],
  );

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(command);
    } catch {
      return; // leave the button on "Copy command" — the write did not land
    }
    setCopied(true);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setCopied(false), confirmMs);
  }, [command, confirmMs]);

  return (
    <button
      type="button"
      onClick={() => void handleCopy()}
      className="mt-1 inline-flex items-center gap-1.5 rounded-md border border-border px-2 py-1 text-xs text-muted-foreground hover:bg-muted hover:text-foreground"
    >
      {copied ? (
        <>
          <Check className="h-3.5 w-3.5 text-done" />
          Copied!
        </>
      ) : (
        <>
          <Copy className="h-3.5 w-3.5" />
          Copy command
        </>
      )}
    </button>
  );
};

export const SystemHealthSection: React.FC = () => {
  const [state, setState] = useState<LoadState>({ status: 'loading' });

  const load = useCallback(async () => {
    setState({ status: 'loading' });
    try {
      const result = await getSystemDoctor();
      setState({ status: 'loaded', checks: result.checks });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setState({ status: 'error', message });
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  return (
    <div className="space-y-6">
      <section className="rounded-2xl panel p-5 md:p-6">
        <div className="flex items-center gap-2">
          <Activity className="h-5 w-5 text-blue" />
          <h2 className="display text-base font-semibold">System Health</h2>
        </div>
        <p className="mt-1 text-sm text-muted-foreground">
          {state.status === 'loaded'
            ? summarise(state.checks)
            : 'Toolchain and install health for this machine'}
        </p>
        <div className="mt-4 space-y-4">
          {state.status === 'loading' && (
            <div role="status" className="text-sm text-muted-foreground">
              Checking system health…
            </div>
          )}

          {state.status === 'error' && (
            <div role="alert" className="text-sm text-destructive">
              Failed to load system health: {state.message}
            </div>
          )}

          {state.status === 'loaded' && (
            <ul className="space-y-3">
              {state.checks.map((check) => (
                <DoctorCheckRow
                  key={check.key}
                  testId={`system-check-${check.key}`}
                  status={check.status}
                  name={check.name}
                  message={check.message}
                  details={check.details}
                  fix={check.fix}
                />
              ))}
            </ul>
          )}

          <button
            type="button"
            onClick={() => void load()}
            disabled={state.status === 'loading'}
            className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground disabled:opacity-50"
          >
            <RefreshCw className="h-4 w-4" />
            Refresh
          </button>
        </div>
      </section>
    </div>
  );
};

export default SystemHealthSection;
