import type { ListStatus } from '@/components/ListStatusFilter';
import type { WorkAreaCount } from '@/components/layout/StageRail';

/**
 * Stage-rail counts for a work area: the in-progress count, and the total —
 * ACTIVE work only (not_started + in_progress + ready_to_land). Completed/
 * superseded items are excluded along with archived ones, so the total means
 * the same thing across plans, fixes and spikes regardless of whether the area
 * supports archival (plans/fixes hide completed work by archiving it; spikes
 * have no archive, so counting completed there would over-state the total
 * relative to the others).
 *
 * Done-but-unlanded work is finished-but-unmerged: both fixCategory and
 * planCategory give it the `ready_to_land` category, which counts toward the
 * active total but not the in-progress sub-count — so no separate predicate is
 * needed to keep it out of "in progress".
 */
const ACTIVE_CATEGORIES: ReadonlySet<ListStatus> = new Set(['not_started', 'in_progress', 'ready_to_land']);

export function workAreaCount<T>(
  items: readonly T[],
  category: (item: T) => ListStatus,
): WorkAreaCount {
  const inProgress = items.filter((i) => category(i) === 'in_progress').length;
  const total = items.filter((i) => ACTIVE_CATEGORIES.has(category(i))).length;
  return { inProgress, total };
}
