import type { SetupChipStatus } from '../components/SetupProgressStrip';

/** The four ordered step sections that get a progress-strip chip. */
export type SetupStepId = 'working-together' | 'analysis' | 'configuration' | 'pipeline';

export interface SetupStatusInputs {
  /** Config-health result; null while still loading. */
  health: { status: 'healthy' | 'warning' | 'error' } | null;
  /** Whether `analyse` has produced an analysis file for the repo. */
  analysisExists: boolean;
  /** Whether the effective config has any repo-level overrides. */
  hasConfigOverrides: boolean;
}

const workingTogetherStatus = (health: SetupStatusInputs['health']): SetupChipStatus => {
  if (!health) return 'untouched';
  switch (health.status) {
    case 'error':
      return 'fail';
    case 'warning':
      return 'attention';
    case 'healthy':
      return 'complete';
  }
};

/**
 * Pure mapping from repo state to each step section's chip status. The Setup
 * section reads health, Analysis reads whether the repo is analysed, and
 * Configuration flags repo overrides.
 *
 * `configuration` defaults to complete (config always resolves); it becomes a
 * meaningful gate once Feature 4's ConfigEditor can surface invalid overrides.
 * `pipeline` is always complete — outstanding capability recommendations are a
 * Capabilities-tab concern (the recommendations panel lives there), not a
 * pipeline-editor one.
 */
export const deriveSetupChipStatuses = (
  inputs: SetupStatusInputs,
): Record<SetupStepId, SetupChipStatus> => ({
  'working-together': workingTogetherStatus(inputs.health),
  analysis: inputs.analysisExists ? 'complete' : 'untouched',
  configuration: inputs.hasConfigOverrides ? 'attention' : 'complete',
  pipeline: 'complete',
});

/** Severity rank — lower is worse; only two `complete`s combine to `complete`. */
const STATUS_RANK: Record<SetupChipStatus, number> = {
  fail: 0,
  attention: 1,
  untouched: 2,
  complete: 3,
};

/**
 * Combine two step statuses into the worse of the two. Used where one section
 * now carries two concerns (the Setup section folds in analysis readiness):
 * the combined chip only reads `complete` when both inputs are complete.
 */
export const worseSetupStatus = (a: SetupChipStatus, b: SetupChipStatus): SetupChipStatus =>
  STATUS_RANK[a] <= STATUS_RANK[b] ? a : b;
