import React from 'react';
import { RotateCcw } from 'lucide-react';
import { Switch } from './ui/switch';
import type { ConfigEntry, ConfigFlags } from '../types';

type FlagSource = ConfigEntry['source'];

// Token-based provenance chips — flip with the theme automatically. Rendered in
// `repo` mode (where default / global / repo are all distinguishable); the
// `global` mount suppresses them since every value is global there.
const SOURCE_STYLE: Record<FlagSource, string> = {
  repo: 'bg-blue/10 text-blue',
  global: 'bg-muted text-subtle',
  default: 'bg-muted/50 text-subtle',
};

/** Per-key provenance chip showing whether a value comes from default, global or repo. */
const SourceBadge: React.FC<{ flagKey: string; source: FlagSource }> = ({ flagKey, source }) => (
  <span
    data-testid={`config-source-${flagKey}`}
    data-source={source}
    className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${SOURCE_STYLE[source]}`}
  >
    {source}
  </span>
);

/** One selectable choice of an enum control, rendered as its own radio row. */
interface EnumOption {
  value: string;
  label: string;
  help: string;
}

type Control =
  | { kind: 'boolean' }
  | { kind: 'text' }
  | { kind: 'enum'; options: readonly EnumOption[] };

interface FlagDef {
  key: string;
  label: string;
  /** One-line explanation rendered beneath the label. */
  help: string;
  control: Control;
}

interface FlagGroup {
  /** Stable id used for the section's test hook (`config-group-<id>`). */
  id: string;
  title: string;
  /** Section-level helper text rendered under the heading. */
  description: string;
  flags: readonly FlagDef[];
}

/**
 * The curated, writable flag set the editor exposes — the same vocabulary the
 * GET surfaces — grouped under headings (Methodology / Workflow / Directories /
 * Pruning), each section and option carrying helper text. Order here is the
 * render order. Keys absent from a given `flags` map (e.g. a scope that doesn't
 * define them) are skipped; a group with no present keys renders nothing.
 */
const FLAG_GROUPS: readonly FlagGroup[] = [
  {
    id: 'methodology',
    title: 'Methodology',
    description: 'Development practices tiny-brain enforces as work flows through the pipeline.',
    flags: [
      { key: 'enableTDD', label: 'Test-Driven Development', help: 'Require a failing test before implementation; gate tasks RED → GREEN → REFACTOR.', control: { kind: 'boolean' } },
      { key: 'enableSDD', label: 'Spec-Driven Development', help: 'Plan features as specs before writing code.', control: { kind: 'boolean' } },
      { key: 'enableADR', label: 'Architecture Decision Records', help: 'Prompt for an ADR when a change makes a significant architectural decision.', control: { kind: 'boolean' } },
      { key: 'enableQuality', label: 'Quality Pipeline', help: 'Run quality analysis (coverage, security, performance, …) on the repo.', control: { kind: 'boolean' } },
    ],
  },
  {
    id: 'workflow',
    title: 'Workflow',
    description: 'How tracked work is organised and cleaned up.',
    flags: [
      { key: 'autoArchive', label: 'Auto-archive completed work', help: 'Archive completed PRDs and resolved fixes automatically during sync.', control: { kind: 'boolean' } },
      { key: 'manageAgentsMd', label: 'Manage AGENTS.md', help: 'Let tiny-brain own and regenerate the AGENTS.md managed block during analyse.', control: { kind: 'boolean' } },
      { key: 'defaultPersona', label: 'Default persona', help: 'The persona activated at session start.', control: { kind: 'text' } },
      {
        key: 'branchGranularity',
        label: 'Branch granularity',
        help: 'When you start a task, should tiny-brain make a git branch for you — and how much work shares each branch?',
        control: {
          kind: 'enum',
          options: [
            { value: 'off', label: 'Off', help: "Don't make branches — keep working on the branch you're already on." },
            { value: 'task', label: 'A branch per task', help: 'Every task gets its own branch.' },
            { value: 'container', label: 'A branch per feature', help: "A feature's tasks share one branch (a fix or spike gets a single branch)." },
            { value: 'root', label: 'A branch per PRD', help: 'The whole PRD shares one branch.' },
          ],
        },
      },
    ],
  },
  {
    id: 'directories',
    title: 'Directories',
    description: 'Where tiny-brain reads and writes tracked-work documents.',
    flags: [
      { key: 'docsDirectory', label: 'Docs directory', help: 'Root directory for generated documentation.', control: { kind: 'text' } },
      { key: 'adrDirectory', label: 'ADR directory', help: 'Where Architecture Decision Records are written.', control: { kind: 'text' } },
      { key: 'prdDirectory', label: 'PRD directory', help: 'Where PRD folders live.', control: { kind: 'text' } },
      { key: 'fixesDirectory', label: 'Fixes directory', help: 'Where fix documents live.', control: { kind: 'text' } },
    ],
  },
  {
    id: 'pruning',
    title: 'Pruning',
    description: 'Automatic cleanup of archived, completed PRDs, fixes and spikes — their docs, progress entries and cached reviews. Branches and worktrees are never touched.',
    flags: [
      { key: 'pruneOnPush', label: 'Prune on push', help: 'On every git push, delete the docs, progress entries and cached reviews of archived, fully-completed PRDs, fixes and spikes.', control: { kind: 'boolean' } },
      { key: 'pruneOnPr', label: 'Prune on PR', help: 'Like prune-on-push, but only when the current branch has an open PR (needs `gh` on PATH); takes precedence over prune-on-push.', control: { kind: 'boolean' } },
      { key: 'pruneAfterDaysSinceArchive', label: 'Prune after days since archive', help: 'Background daily sweep prunes items resolved more than this many days ago; blank disables the sweep.', control: { kind: 'text' } },
    ],
  },
];

// Boolean and text controls render inline on the right of their row. Enum
// controls are rendered as a full-width radio list by the row itself (one
// option per row), so they never reach this component.
const FlagControl: React.FC<{
  def: FlagDef;
  value: unknown;
  onWrite: (key: string, value: boolean | string) => void;
}> = ({ def, value, onWrite }) => {
  if (def.control.kind === 'boolean') {
    return (
      <Switch
        checked={Boolean(value)}
        onCheckedChange={(checked) => onWrite(def.key, checked)}
        aria-label={def.label}
      />
    );
  }

  if (def.control.kind === 'enum') return null;

  // Text: commit on blur so a write isn't fired on every keystroke. Keyed on
  // the incoming value so a prop change (e.g. parent re-fetch after a write)
  // remounts the input with the new canonical value — uncontrolled per-edit,
  // but still a pure render of the latest props.
  const text = value === null || value === undefined ? '' : String(value);
  return (
    <input
      key={text}
      aria-label={def.label}
      defaultValue={text}
      onBlur={(e) => onWrite(def.key, e.target.value)}
      className="text-xs font-mono px-2 py-0.5 rounded border border-border bg-background w-40"
    />
  );
};

/**
 * Scope-aware config editor — a pure render over the flattened `{value, source}`
 * flag map. It performs no fetch and defines no API shapes: both the global
 * (SettingsPane) and repo (Setup tab) mounts pass their own flags + callbacks.
 *
 * In `repo` mode, a key whose value comes from the repo scope gets a
 * clear-override affordance (`onClearOverride`) that drops the repo key so the
 * global/default value shows through. The `global` mount never renders it.
 *
 * The per-row provenance badge is only meaningful in `repo` mode (where it
 * distinguishes default / global / repo). In the `global` mount everything is
 * global, so the badge is suppressed as noise.
 */
export const ConfigEditor: React.FC<{
  flags: ConfigFlags;
  mode: 'global' | 'repo';
  onWrite: (key: string, value: boolean | string) => void;
  onClearOverride?: (key: string) => void;
}> = ({ flags, mode, onWrite, onClearOverride }) => (
  <div className="space-y-6" data-testid="config-editor">
    {FLAG_GROUPS.map((group) => {
      const defs = group.flags.filter((def) => def.key in flags);
      if (defs.length === 0) return null;
      return (
        <section key={group.id} data-testid={`config-group-${group.id}`} className="space-y-1">
          <div className="mb-1">
            <h3 className="text-sm font-medium text-foreground">{group.title}</h3>
            <p className="text-xs text-subtle">{group.description}</p>
          </div>
          {defs.map((def) => {
            const entry = flags[def.key];
            const source = entry.source;
            const showClear = mode === 'repo' && source === 'repo' && Boolean(onClearOverride);
            const provenance = mode === 'repo' ? <SourceBadge flagKey={def.key} source={source} /> : null;
            const clearButton = showClear ? (
              <button
                type="button"
                aria-label={`Reset ${def.label}`}
                onClick={() => onClearOverride?.(def.key)}
                className="inline-flex items-center text-muted-foreground hover:text-foreground"
              >
                <RotateCcw className="h-3.5 w-3.5" />
              </button>
            ) : null;

            // Enum: a full-width radio list, one option per row, each with its
            // own plain-language description — clearer than a dense dropdown.
            if (def.control.kind === 'enum') {
              const current = String(entry.value ?? '');
              return (
                <div
                  key={def.key}
                  data-testid={`config-row-${def.key}`}
                  className="py-1.5 border-b border-border last:border-b-0"
                >
                  <div className="flex items-center justify-between gap-3">
                    <span className="text-sm text-muted-foreground">{def.label}</span>
                    <div className="flex items-center gap-2 shrink-0">
                      {provenance}
                      {clearButton}
                    </div>
                  </div>
                  <p className="text-xs text-subtle">{def.help}</p>
                  <div role="radiogroup" aria-label={def.label} className="mt-2 space-y-1.5">
                    {def.control.options.map((opt) => (
                      <label key={opt.value} className="flex items-start gap-2 cursor-pointer">
                        <input
                          type="radio"
                          name={def.key}
                          value={opt.value}
                          checked={current === opt.value}
                          onChange={() => onWrite(def.key, opt.value)}
                          className="mt-1 shrink-0"
                        />
                        <span className="min-w-0">
                          <span className="text-sm text-foreground">{opt.label}</span>
                          <span className="block text-xs text-subtle">{opt.help}</span>
                        </span>
                      </label>
                    ))}
                  </div>
                </div>
              );
            }

            return (
              <div
                key={def.key}
                data-testid={`config-row-${def.key}`}
                className="flex items-center justify-between gap-3 py-1.5 border-b border-border last:border-b-0"
              >
                <div className="min-w-0">
                  <span className="text-sm text-muted-foreground">{def.label}</span>
                  <p className="text-xs text-subtle">{def.help}</p>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  {provenance}
                  {clearButton}
                  <FlagControl def={def} value={entry.value} onWrite={onWrite} />
                </div>
              </div>
            );
          })}
        </section>
      );
    })}
  </div>
);

export default ConfigEditor;
