import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App';
import { ThemeProvider } from './contexts/ThemeContext';
import { LibraryProvider } from './contexts/LibraryContext';
import { CurrentRepoProvider } from './contexts/CurrentRepoContext';
import ErrorBoundary from './components/ErrorBoundary';
// Self-host the brand fonts (variable axes) so the dashboard renders correctly
// offline — no Google Fonts CDN dependency. Imported before globals.css so the
// @font-face rules are registered before the `--font-*` stacks reference them.
import '@fontsource-variable/inter';
import '@fontsource-variable/space-grotesk';
import '@fontsource-variable/jetbrains-mono';
import './styles/globals.css';
// Base styles for the unified-diff viewer (task detail page diffs); our own
// rules layer on top via the .tb-diff wrapper.
import 'react-diff-view/style/index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <ErrorBoundary>
      <BrowserRouter>
        <ThemeProvider>
          <LibraryProvider>
            <CurrentRepoProvider>
              <App />
            </CurrentRepoProvider>
          </LibraryProvider>
        </ThemeProvider>
      </BrowserRouter>
    </ErrorBoundary>
  </React.StrictMode>
);