import React from 'react';
import { Archive } from 'lucide-react';
import { AssetsIndicator } from './AssetsIndicator';

/**
 * The sidebar card's title-aside markers — the design-assets indicator and the
 * archive glyph — shared by PlanCard and FixCard so the two never drift. Returns
 * `undefined` when there's nothing to show, preserving SidebarCard's contract of
 * rendering no aside wrapper when the slot is empty.
 */
export function cardTitleMarkers(opts: {
  hasAssets?: boolean;
  assetCount?: number;
  isArchived?: boolean;
}): React.ReactNode {
  const { hasAssets, assetCount, isArchived } = opts;
  if (!hasAssets && !isArchived) return undefined;
  return (
    <>
      {hasAssets && <AssetsIndicator count={assetCount} />}
      {isArchived && <Archive data-testid="archive-icon" className="h-3.5 w-3.5 text-muted-foreground" />}
    </>
  );
}
