import { Drama, FolderGit2, Server, Bot } from 'lucide-react';
import type { SidebarSection } from './AppSidebar';

/**
 * Builds the main sidebar's nav sections. Extracted from App.tsx so the
 * composition (which sections exist, in what order) is unit-testable without
 * standing up the router and app hooks.
 *
 * The former "AI › Plugins" section is intentionally gone: plugin management is
 * a provider-owned concern obtained from Claude Code itself, not a top-level
 * tiny brain nav slot (fix rework-main-sidebar-nav).
 */
export interface BuildSidebarSectionsOptions {
  /**
   * How many personas exist. The Personas nav item is only worth showing when
   * there is more than one to switch between; with just the default `developer`
   * persona it is omitted. `undefined` (count unknown) shows it.
   */
  personaCount?: number;
}

export function buildSidebarSections({ personaCount }: BuildSidebarSectionsOptions = {}): SidebarSection[] {
  // Show Personas only when there's more than one to switch between. An unknown
  // count (undefined, still loading) keeps it — hiding then re-showing flickers.
  const showPersonas = personaCount === undefined || personaCount > 1;
  const sections: SidebarSection[] = [];
  if (showPersonas) {
    sections.push({ id: 'main', items: [{ id: 'personas', title: 'Personas', icon: Drama }] });
  }
  sections.push({ id: 'code', title: 'Code', items: [{ id: 'repos', title: 'Repos', icon: FolderGit2 }] });
  // Execution is pinned to the foot of the nav (just above the utility rail).
  // Its surfaces aren't built yet — they land on a coming-soon placeholder.
  sections.push({
    id: 'execution',
    title: 'Execution',
    position: 'bottom',
    items: [
      { id: 'environments', title: 'Environments', icon: Server },
      { id: 'workers', title: 'Workers', icon: Bot },
    ],
  });
  return sections;
}

/**
 * The path the app lands on for a bare-root / unknown route. When Personas is
 * hidden (a single persona) the app must not land on `/personas`, so it falls
 * back to Repos.
 */
export function defaultViewPath(personaCount: number): string {
  return personaCount > 1 ? '/personas' : '/repos';
}

/**
 * The route a sidebar item id navigates to when clicked, or null when the id
 * has no destination. Kept in step with {@link buildSidebarSections} and
 * {@link selectedViewForPath}.
 */
export function navPathForItem(itemId: string): string | null {
  switch (itemId) {
    case 'personas':
      return '/personas';
    case 'repos':
      return '/repos';
    case 'environments':
      return '/environments';
    case 'workers':
      return '/workers';
    case 'settings':
      return '/settings';
    default:
      return null;
  }
}

/**
 * Reads the persona count out of the `/api/personas` response. The endpoint
 * returns `{ personas: [...] }`; a bare array is also tolerated (defensive,
 * mirroring the personas page). Any other shape counts as zero.
 */
export function personaCountFromResponse(data: unknown): number {
  if (data && typeof data === 'object' && Array.isArray((data as { personas?: unknown }).personas)) {
    return (data as { personas: unknown[] }).personas.length;
  }
  if (Array.isArray(data)) return data.length;
  return 0;
}

/**
 * Maps a router pathname to the selected sidebar view id, so the route ↔ nav
 * mapping is unit-testable and stays in step with {@link buildSidebarSections}.
 * A repo detail page (`/repos/<id>`) selects nothing here — the starred-repo
 * sub-row owns that visual. Unmatched paths (a bare root before redirect, or a
 * stale `/plugins` link) select nothing rather than highlighting a nav item
 * that may not exist (Personas is now conditional).
 */
export function selectedViewForPath(pathname: string): string | null {
  if (pathname.startsWith('/personas')) return 'personas';
  if (pathname === '/repos') return 'repos';
  if (pathname.startsWith('/repos/')) return null;
  if (pathname === '/environments') return 'environments';
  if (pathname === '/workers') return 'workers';
  if (pathname === '/settings') return 'settings';
  return null;
}
