import React, { useState, useEffect } from 'react';
import { Code, CircleDashed } from 'lucide-react';

interface AnalysisBadgeProps {
  repoId: string;
  onClick?: () => void;
  size?: 'sm' | 'md';
}

/**
 * A small badge that shows whether a repository has been analysed.
 * Click handler navigates to the repo Setup tab's Analysis section.
 * Renders nothing until its fetch resolves (no loading flicker on cards).
 */
const AnalysisBadge: React.FC<AnalysisBadgeProps> = ({ repoId, onClick, size = 'sm' }) => {
  const [exists, setExists] = useState<boolean | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/repos/${repoId}/analysis`)
      .then(res => (res.ok ? res.json() : null))
      .then(data => {
        if (!cancelled && data) setExists(!!data.exists);
      })
      .catch(() => {
        // Silently fail — badge just won't show.
      });
    return () => {
      cancelled = true;
    };
  }, [repoId]);

  if (exists === null) return null;

  const iconSize = size === 'sm' ? 'h-4 w-4' : 'h-5 w-5';
  const textSize = size === 'sm' ? 'text-xs' : 'text-sm';
  const baseClasses = onClick ? 'cursor-pointer hover:opacity-80 transition-opacity' : '';

  return (
    <span
      data-testid={`analysis-badge-${repoId}`}
      className={`inline-flex items-center gap-1 ${baseClasses}`}
      onClick={() => onClick?.()}
      title={exists ? 'Repository analysed' : 'Repository not analysed - click to analyse'}
    >
      {exists ? (
        <Code className={`${iconSize} text-blue-500`} />
      ) : (
        <CircleDashed className={`${iconSize} text-gray-400`} />
      )}
      <span className={`${textSize} ${exists ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400'}`}>
        {exists ? 'Analysed' : 'Not analysed'}
      </span>
    </span>
  );
};

export default AnalysisBadge;
