import React, { useState } from 'react';
import { Server, Plus, Trash2, RefreshCw, Terminal, KeyRound } from 'lucide-react';
import { Button } from '../components/ui/button';
import {
  useEnvironments,
  type CreateEnvironmentInput,
  type EnvironmentView,
  type SandboxProviderView,
} from '../hooks/useEnvironments';

/**
 * Execution › Environments — the global surface over /api/environments
 * (workers PRD, environments-registry task 5).
 *
 * An environment is where workers run: configure a provider once — connect
 * the account, reference the keys — then attach it to any worker. It is
 * repo-agnostic and work-agnostic; only a run binds a work item in a repo
 * to a worker on an environment. Cards render whatever the routes return —
 * a connect-needed environment shows the terminal handoff (copyable command
 * + Re-check) alongside its configured fields. The UI stays dumb: it POSTs
 * raw fields for the server to validate.
 */

const statusPill: Record<EnvironmentView['connection']['status'], { label: string; cls: string }> = {
  ready: {
    label: 'Ready',
    cls: 'bg-[color-mix(in_oklab,var(--ds-done)_16%,transparent)] text-[var(--ds-done)]',
  },
  'connect-needed': {
    label: 'Setup needed',
    cls: 'bg-[color-mix(in_oklab,var(--ds-warn,orange)_16%,transparent)] text-[var(--ds-warn,orange)]',
  },
  unavailable: {
    label: 'Not available',
    cls: 'bg-[color-mix(in_oklab,var(--ds-fg)_8%,transparent)] text-muted-foreground',
  },
};

const ConnectionPill: React.FC<{ connection: EnvironmentView['connection'] }> = ({ connection }) => {
  const pill = statusPill[connection.status];
  return (
    <span className={`eyebrow rounded-md px-2 py-0.5 text-[10px] ${pill.cls}`}>{pill.label}</span>
  );
};

/**
 * The BYOK connect handoff: `railway login` is interactive and
 * terminal-bound, so the honest move is a copyable command plus a manual
 * Re-check — the dashboard reads the session, it never signs in for you.
 */
const ConnectNeeded: React.FC<{ instruction: string; onRecheck: () => void }> = ({
  instruction,
  onRecheck,
}) => (
  <div className="mt-3 rounded-xl border border-[var(--ds-border)] p-3">
    <p className="text-xs text-muted-foreground">
      Not signed in. Run this in your terminal — it opens your browser to authorise; the
      dashboard can't sign in for you.
    </p>
    <div className="mt-2 flex items-center gap-2">
      <Terminal className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
      <code className="flex-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] px-2 py-1 font-mono text-xs">
        {instruction}
      </code>
      <Button
        variant="outline"
        size="sm"
        onClick={() => void navigator.clipboard?.writeText(instruction)}
      >
        Copy
      </Button>
    </div>
    <Button variant="outline" size="sm" className="mt-2" onClick={onRecheck}>
      <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
      I've logged in — Re-check
    </Button>
  </div>
);

const EnvironmentCard: React.FC<{
  environment: EnvironmentView;
  onRecheck: () => void;
  onDelete: (name: string) => void;
}> = ({ environment, onRecheck, onDelete }) => {
  const isBuiltIn = environment.name === 'local' && environment.provider === 'local';
  const { connection } = environment;
  return (
    <div className="panel rounded-2xl p-5">
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-2.5">
          <Server className="h-4 w-4 text-muted-foreground" />
          <h2 className="font-mono text-sm font-semibold">{environment.name}</h2>
          {isBuiltIn && (
            <span className="eyebrow rounded-md bg-[color-mix(in_oklab,var(--ds-blue)_15%,transparent)] px-2 py-0.5 text-[10px] text-blue">
              Built-in
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          <ConnectionPill connection={connection} />
          {!isBuiltIn && (
            <Button
              variant="ghost"
              size="sm"
              aria-label={`Delete ${environment.name}`}
              onClick={() => onDelete(environment.name)}
            >
              <Trash2 className="h-3.5 w-3.5" />
              Delete
            </Button>
          )}
        </div>
      </div>

      <dl className="mt-3 grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs">
        {environment.provider !== environment.name && (
          <>
            <dt className="text-muted-foreground">Provider</dt>
            <dd className="font-mono">{environment.provider}</dd>
          </>
        )}
        {isBuiltIn && (
          <dd className="col-span-2">Runs on this machine — no setup required.</dd>
        )}
        {(connection.status === 'ready' && connection.account) || environment.account ? (
          <>
            <dt className="text-muted-foreground">Account</dt>
            <dd className="font-mono">
              {connection.status === 'ready' && connection.account
                ? connection.account
                : environment.account}
            </dd>
          </>
        ) : null}
        {environment.keyedProviders.length > 0 && (
          <>
            <dt className="text-muted-foreground">Model keys</dt>
            <dd className="flex flex-wrap gap-1.5">
              {environment.keyedProviders.map((provider) => (
                <span
                  key={provider}
                  className="inline-flex items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] px-1.5 py-0.5 font-mono"
                >
                  <KeyRound className="h-3 w-3" />
                  {provider}
                </span>
              ))}
            </dd>
          </>
        )}
        {environment.policy?.idleTimeoutMinutes !== undefined && (
          <>
            <dt className="text-muted-foreground">Idle timeout</dt>
            <dd>{environment.policy.idleTimeoutMinutes} min</dd>
          </>
        )}
        {environment.policy?.networkIsolation !== undefined && (
          <>
            <dt className="text-muted-foreground">Network</dt>
            <dd>{environment.policy.networkIsolation}</dd>
          </>
        )}
      </dl>

      {connection.status === 'connect-needed' && (
        <ConnectNeeded instruction={connection.instruction} onRecheck={onRecheck} />
      )}
      {connection.status === 'unavailable' && (
        <p className="mt-3 text-xs text-muted-foreground">{connection.reason}</p>
      )}
    </div>
  );
};

/**
 * The draft form. `local` is not a choice — exactly one local environment
 * exists, built-in and already set up; you only ever configure remote
 * providers, offered from the sandbox-provider catalog (unavailable ones
 * render disabled).
 */
const NewEnvironmentForm: React.FC<{
  providers: SandboxProviderView[];
  onSave: (input: CreateEnvironmentInput) => Promise<{ ok: boolean; error?: string }>;
  onDone: () => void;
}> = ({ providers, onSave, onDone }) => {
  const firstAvailable = providers.find((p) => p.available)?.id ?? '';
  const [name, setName] = useState('');
  const [provider, setProvider] = useState(firstAvailable);
  const [account, setAccount] = useState('');
  const [keys, setKeys] = useState<{ provider: string; reference: string }[]>([]);
  const [pickProvider, setPickProvider] = useState('');
  const [pickReference, setPickReference] = useState('');
  const [idleTimeout, setIdleTimeout] = useState('30');
  const [isolation, setIsolation] = useState<'isolated' | 'private'>('isolated');
  const [preWarm, setPreWarm] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // One resolution for everything provider-shaped: the select value, the
  // slot list, the policy gating, and the saved field. `provider` seeds
  // from '' when the form mounts before the catalog fetch resolves, so raw
  // reads of it would disagree with what the select shows.
  const effectiveProvider = provider || firstAvailable;
  const selectedProvider = providers.find((p) => p.id === effectiveProvider);
  const slots = selectedProvider?.credentialProviders ?? [];
  const slotFor = (id: string) => slots.find((s) => s.id === id);
  const unadded = slots.filter((s) => !keys.some((k) => k.provider === s.id));
  // Keep the picker on a real, unadded slot as keys come and go.
  const effectivePick = unadded.some((s) => s.id === pickProvider)
    ? pickProvider
    : (unadded[0]?.id ?? '');

  const addKey = () => {
    if (!effectivePick || pickReference.trim().length === 0) return;
    setKeys([...keys, { provider: effectivePick, reference: pickReference.trim() }]);
    setPickReference('');
  };

  const save = async () => {
    const credentials: Record<string, string> = {};
    for (const key of keys) credentials[key.provider] = key.reference;
    const input: CreateEnvironmentInput = {
      name: name.trim(),
      provider: effectiveProvider,
      ...(account.trim() ? { account: account.trim() } : {}),
      ...(Object.keys(credentials).length > 0 ? { credentials } : {}),
      ...(effectiveProvider === 'railway'
        ? {
            policy: {
              idleTimeoutMinutes: Number.parseInt(idleTimeout, 10) || 30,
              networkIsolation: isolation,
              preWarm,
            },
          }
        : {}),
    };
    const result = await onSave(input);
    if (result.ok) {
      onDone();
    } else {
      setError(result.error ?? 'Failed to save environment');
    }
  };

  const field = 'w-full rounded-md border border-[var(--ds-border)] bg-transparent px-2 py-1.5 text-sm';

  return (
    <div className="panel rounded-2xl p-5">
      <h2 className="text-sm font-semibold">New environment</h2>
      <p className="mt-1 text-xs text-muted-foreground">
        Nothing is provisioned until a worker runs here. Key references are provider
        variables (e.g. Railway project variables), never raw secrets.
      </p>
      <div className="mt-3 grid gap-3">
        <label className="text-xs">
          <span className="text-muted-foreground">Name</span>
          <input className={field} value={name} onChange={(e) => setName(e.target.value)} />
        </label>
        <label className="text-xs">
          <span className="text-muted-foreground">Provider</span>
          <select
            className={field}
            value={effectiveProvider}
            // No keys reset on change: railway is the only selectable
            // provider today, so a switch can't happen through the UI.
            // Re-introduce (with a test) when a second provider unlocks.
            onChange={(e) => setProvider(e.target.value)}
          >
            {providers.map((p) => (
              <option key={p.id} value={p.id} disabled={!p.available}>
                {p.available ? p.label : `${p.label} — soon`}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs">
          <span className="text-muted-foreground">Account</span>
          <input
            className={field}
            value={account}
            placeholder="you@example.com"
            onChange={(e) => setAccount(e.target.value)}
          />
        </label>
        <div className="mt-1">
          <p className="text-xs font-semibold">Model credentials</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Each key unlocks that provider's models for workers in this environment: if you
            have an Anthropic API key, add it to {selectedProvider?.label ?? 'the provider'}{' '}
            and enter the <span className="font-semibold">reference</span> to the key here
            (not the actual key!). Same for an OpenAI API key.
          </p>
          <p className="mt-1.5 text-xs text-muted-foreground">
            The worker resolves the reference inside the sandbox at run time — your actual
            key is never seen by tiny-brain.
          </p>
        </div>
        {keys.length === 0 && (
          <p className="text-xs text-muted-foreground">No keys yet — models stay locked.</p>
        )}
        {keys.map((key) => {
          const slot = slotFor(key.provider);
          return (
            <div
              key={key.provider}
              className="rounded-xl border border-[var(--ds-border)] p-3 text-xs"
            >
              <div className="flex items-center gap-2">
                <KeyRound className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                <span className="font-semibold">{slot?.label ?? key.provider}</span>
                <code className="flex-1 truncate font-mono text-muted-foreground">
                  {key.reference}
                </code>
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={`Remove ${slot?.label ?? key.provider} key`}
                  onClick={() => setKeys(keys.filter((k) => k.provider !== key.provider))}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
              {slot !== undefined && slot.models.length > 0 && (
                <p className="mt-1.5 text-muted-foreground">
                  Unlocks {slot.models.join(', ')}
                </p>
              )}
            </div>
          );
        })}
        {unadded.length > 0 && (
          <div className="rounded-xl border border-dashed border-[var(--ds-border)] p-3">
            <div className="grid gap-2">
              <label className="text-xs">
                <span className="text-muted-foreground">Add a provider key</span>
                <select
                  className={field}
                  value={effectivePick}
                  onChange={(e) => setPickProvider(e.target.value)}
                >
                  {unadded.map((slot) => (
                    <option key={slot.id} value={slot.id}>
                      {slot.label}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs">
                <span className="text-muted-foreground">Key reference</span>
                <input
                  className={field}
                  value={pickReference}
                  placeholder={`\${{ shared.${effectivePick.toUpperCase()}_API_KEY }}`}
                  onChange={(e) => setPickReference(e.target.value)}
                />
              </label>
              <div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={addKey}
                  disabled={pickReference.trim().length === 0}
                >
                  <Plus className="mr-1.5 h-3.5 w-3.5" />
                  Add key
                </Button>
              </div>
            </div>
          </div>
        )}
        {effectiveProvider === 'railway' && (
          <>
            <label className="text-xs">
              <span className="text-muted-foreground">Idle timeout (minutes, 1–120)</span>
              <input
                className={field}
                type="number"
                value={idleTimeout}
                onChange={(e) => setIdleTimeout(e.target.value)}
              />
            </label>
            <label className="text-xs">
              <span className="text-muted-foreground">Network</span>
              <select
                className={field}
                value={isolation}
                onChange={(e) => setIsolation(e.target.value as 'isolated' | 'private')}
              >
                <option value="isolated">Isolated</option>
                <option value="private">Private</option>
              </select>
            </label>
            <label className="flex items-center gap-2 text-xs">
              <input
                type="checkbox"
                checked={preWarm}
                onChange={(e) => setPreWarm(e.target.checked)}
              />
              <span>Pre-warm — bake repo templates ahead of the first run</span>
            </label>
          </>
        )}
      </div>
      {error && <p className="mt-2 text-xs text-red-500">{error}</p>}
      <div className="mt-4 flex gap-2">
        <Button
          size="sm"
          onClick={() => void save()}
          // No provider = the catalog fetch failed or nothing is available
          // — a POST with provider '' would just 400.
          disabled={name.trim().length === 0 || effectiveProvider === ''}
        >
          Save environment
        </Button>
        <Button variant="ghost" size="sm" onClick={onDone}>
          Cancel
        </Button>
      </div>
    </div>
  );
};

const EnvironmentsPage: React.FC = () => {
  const { environments, providers, loading, error, refresh, create, remove } = useEnvironments();
  const [creating, setCreating] = useState(false);

  return (
    <div className="mx-auto w-full max-w-6xl p-4 md:p-6 lg:p-8">
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="eyebrow text-[10px] text-muted-foreground">Execution environments</p>
          <h1 className="display mt-1 text-2xl font-bold">Environments</h1>
          <p className="mt-2 max-w-xl text-sm text-muted-foreground">
            Where workers run. Configure a provider once — connect the account, reference the
            key — then attach it to any worker. Environments know nothing about repos or work
            items; a run is what binds them.
          </p>
        </div>
        <Button size="sm" onClick={() => setCreating(true)}>
          <Plus className="mr-1.5 h-3.5 w-3.5" />
          New environment
        </Button>
      </div>

      {error && <p className="mt-4 text-sm text-red-500">{error}</p>}
      {loading && <p className="mt-4 text-sm text-muted-foreground">Loading environments…</p>}

      {/* Mockup layout: environment list left, the draft panel in a fixed
          right-hand column. Stacks below xl so the list (column 1) keeps full
          width on normal laptop widths and stays fully responsive. */}
      <div className={`mt-6 grid gap-4 ${creating ? 'xl:grid-cols-[minmax(0,1fr)_360px]' : ''}`}>
        <div className="grid min-w-0 content-start gap-4">
          {environments.map((environment) => (
            <EnvironmentCard
              key={environment.name}
              environment={environment}
              onRecheck={() => void refresh()}
              onDelete={(name) => void remove(name)}
            />
          ))}
        </div>
        {creating && (
          <NewEnvironmentForm
            providers={providers}
            onSave={create}
            onDone={() => setCreating(false)}
          />
        )}
      </div>
    </div>
  );
};

export default EnvironmentsPage;
