import { useEffect, useState } from 'react';
import { Loader2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet';
import { fetchFixContent } from '../services/api';

export interface FixSourceSheetProps {
  repoId: string;
  fixId: string;
  isOpen: boolean;
  onClose: () => void;
}

/**
 * Right-side slide-over showing a fix's raw markdown source — the view the
 * Tasks/Details tabs used to host, relocated behind the detail header's
 * "View source" action so it no longer competes with the single-column layout.
 * Content is fetched lazily the first time (and whenever) the sheet opens.
 */
export const FixSourceSheet: React.FC<FixSourceSheetProps> = ({ repoId, fixId, isOpen, onClose }) => {
  const [content, setContent] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    // On close, drop the previous content so a reopen (often for a different
    // fix) doesn't flash the prior markdown for a paint before the fetch starts.
    if (!isOpen) {
      setContent(null);
      setError(false);
      return;
    }
    let cancelled = false;
    setContent(null);
    setLoading(true);
    setError(false);
    fetchFixContent(repoId, fixId)
      .then((c) => { if (!cancelled) setContent(c); })
      .catch(() => { if (!cancelled) setError(true); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [isOpen, repoId, fixId]);

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="flex w-[640px] flex-col sm:max-w-[640px]">
        <SheetHeader>
          <SheetTitle className="display">Fix source</SheetTitle>
          <SheetDescription className="mono truncate text-xs">{fixId}</SheetDescription>
        </SheetHeader>
        <div className="min-h-0 flex-1 overflow-auto px-4 pb-4">
          {loading ? (
            <p className="flex items-center gap-2 py-4 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading fix source…
            </p>
          ) : error ? (
            <p className="py-4 text-sm text-red-600 dark:text-red-400">Failed to load fix source.</p>
          ) : content !== null ? (
            <div
              data-testid="fix-source"
              className="panel-flat prose prose-sm max-w-none overflow-auto rounded-xl p-4 dark:prose-invert"
            >
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
            </div>
          ) : null}
        </div>
      </SheetContent>
    </Sheet>
  );
};

export default FixSourceSheet;
