import { useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { ArrowUp, Ban, Bot, CheckCheck, CircleCheck, ChevronDown, ChevronRight, Cloud, FastForward, GitBranch, GitCommitHorizontal, GitMerge, GitPullRequest, HardDrive, Layers, Loader2, Lock, Trash2, TriangleAlert, Wrench, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { AcceptanceState, BranchRunProvenance, DeliveredTask, LandingState, RunEnvironment, WorktreeProvenance } from '@magic-ingredients/tiny-brain-core';
import { StagedLandingControl } from './StagedLandingControl';
// Value import via the browser-safe subpath — the core barrel pulls node:path
// (LocalStoragePathBuilder), which Vite externalises and crashes at runtime.
import type { WorktreeContents, WorktreeContentContainer } from '@magic-ingredients/tiny-brain-core/worktree-contents';
import { WorktreeStatusPill } from '@/features/worktrees/components/worktree-status-meta';
import type { WorktreeListStatus } from '@/utils/worktree-list-status';

/** The canonical kind glyph + tone, matching WorktreesInProgressTab. Only the kinds
 *  a branch's WorktreeContents can carry today (PRD, fix) live here — spikes aren't
 *  represented in WorktreeContents yet, so add a `spike` entry (FlaskConical /
 *  text-cyan-500) here when they are, rather than carry dead config now. */
const KIND_META: Record<'prd' | 'fix', { tone: string; Icon: LucideIcon }> = {
  prd: { tone: 'text-primary', Icon: Layers },
  fix: { tone: 'text-blue-500', Icon: Wrench },
};

/**
 * The branch's delivery kind for the type-aware header glyph + tone: any PRD work
 * reads as a plan, else a fix. Falls back to a neutral amber branch glyph when
 * nothing is derivable — e.g. an interactive worktree with no recognised contents.
 */
function kindMeta(contents?: WorktreeContents): { tone: string; Icon: LucideIcon } {
  if (contents?.prds.length) return KIND_META.prd;
  if (contents?.fixes.length) return KIND_META.fix;
  return { tone: 'text-amber-500', Icon: GitBranch };
}

/**
 * The single-fix worktree-merge island (delivery-convergence F6 / delivery-surface
 * task 7; mockup: worktree-runs-fix-unmerged.html). Opens over the repo view from
 * a fix's worktree marker and drives the four delivery actions against the F6 API.
 *
 * Presentational + dumb (the house style): it takes the derived acceptance state
 * and action callbacks; the parent owns data fetching, the POSTs, and the marker
 * wiring. Two rules it enforces locally:
 *   - the land chooser (ff · merge · raise-PR) only exists while there is still
 *     something to land — once `landed`, it is gone;
 *   - teardown is GATED — disabled until `landed` (the F6 lifecycle rule), so the
 *     only on-disk copy of un-landed work can't be destroyed from here.
 *
 * State distinctions it honours (the lattice keeps four `AcceptanceState`s, not
 * two): the land chooser appears ONLY for `pending-acceptance` — `not-ready`
 * (work unfinished) offers nothing to land, and `rejected` is a deliberate
 * dead-end here (a rejected run's worktree is removed via the PRD view's
 * *discard* action, task 8 — distinct from landed teardown). `busy` disables the
 * async-dispatch buttons (land / confirm-reject / teardown); local toggles and
 * the dismissal paths (Esc / backdrop / ✕) stay live — closing the overlay never
 * aborts an in-flight POST.
 */

type LandStrategy = 'ff' | 'merge' | 'pr';

export interface WorktreeMergeContentProps {
  /** Optional close affordance — the header ✕ renders only when provided (the overlay passes it; an inline pane may omit it or use it to deselect). */
  onClose?: () => void;
  /** The island header title — a fix title or a worktree branch (container-agnostic). */
  title: string;
  /** The branch's contents (PRD/feature(s)/fix(es)) — shown in the header so the land confirmation names exactly what will land. */
  contents?: WorktreeContents;
  /** The derived delivery-acceptance state (drives the land/teardown gating). */
  acceptanceState: AcceptanceState;
  /** The shared lifecycle bucket (derived once from status + acceptance) — drives the header status pill so the detail surface reads the same as the sidebar card (task 11). */
  mergeState: WorktreeListStatus;
  /**
   * Whether an actual worker run backs this branch. "Reject run" is a
   * worker-run concept (discard the run's branch), so it — and its reason panel
   * — only render when a run is present. Land / raise-PR stay available for any
   * deliverable worktree, worker or interactive (`tb go`). Required so a dropped
   * thread along the wiring is a compile error, not a silent interactive
   * fallback that strips Reject from a worker run.
   */
  isWorkerRun: boolean;
  /**
   * Branch provenance (ahead/behind vs base, mergeability, on-disk size) behind
   * the vitals header + branch panel (workers / worktree-merge-surface). Absent on
   * surfaces that haven't wired it yet — the vitals row degrades gracefully.
   */
  provenance?: WorktreeProvenance;
  /** The worker run(s) that produced this branch, most-recent first — the Worker run + Environment vitals. */
  runs?: readonly BranchRunProvenance[];
  /** The branch's task completion, for the Tasks vital + the "Tasks delivered" count. */
  tasks?: { done: number; total: number };
  /** The tasks this run delivered, each with its green commit SHA — the "Tasks delivered" list. */
  deliveredTasks?: readonly DeliveredTask[];
  /** Commits on the branch not yet on main — what a teardown would discard; shown in the clean-up panel. */
  unlandedCommits?: readonly { readonly sha: string; readonly subject: string }[];
  /** A delivery action is in flight — disables the action buttons. */
  busy?: boolean;
  /**
   * The git work streamed by the in-flight land, most-recent last — rendered live
   * in the running log once a mode is clicked. The container feeds it from the
   * land-output stream; absent until that stream is wired (the section then just
   * shows a starting state while `busy`).
   */
  landLog?: readonly string[];
  /** The in-flight land failed (the container stayed open to retry) — the running log shows a failed state, not a false success. */
  landError?: boolean;
  /** Why the land failed — the reason + copyable rebase hint — shown so a refused land isn't silent (fix: worktree-ff-land-without-run-record). */
  landFailure?: string;
  /**
   * Teardown-only mode (spike clean-up): there is nothing to land/raise/reject —
   * the only action is tearing down the worktree. Hides the Land section and
   * enables Teardown regardless of landed-ness, with finished-spike copy.
   */
  teardownOnly?: boolean;
  /** The worktree has been torn down — the Clean up section shows a done state and disables its action. */
  cleanedUp?: boolean;
  /** A refused teardown's reason (the git removeError or a gate's reason) — surfaced in the Clean up section so the failure isn't silent. */
  teardownError?: string;
  /**
   * The server-derived staged-landing state (worktree-landing-strip
   * island-landing-states). When present, the Landing strip section renders the
   * staged control (Prepare → verify → Land ff, with secondary unverified
   * merge/PR) instead of the direct ff/merge/PR chooser. Absent ⇒ the legacy
   * chooser (rows that haven't wired the landing state).
   */
  landingState?: LandingState;
  onLand: (method: 'ff-only' | 'merge') => void;
  onRaise: () => void;
  onReject: (reason: string) => void;
  /** "Prepare to land" — start the reconcile ladder (staged control). */
  onPrepare?: () => void;
  /** "Restore pre-rebase" — reset the branch to its backup (staged control). */
  onRestore?: () => void;
  /** Tear down the selected subset of the worktree's reclaimable parts. */
  onTeardown: (selection: TeardownPartSelection) => void;
  /** Tear down with --force — invoked when the selection includes a caveated part (dirty worktree / unmerged branch) whose removal needs force. Posts the same selection with force. */
  onForceTeardown?: (selection: TeardownPartSelection) => void;
  /**
   * Permit discarding this worktree even though it isn't landed (fix task 14): an
   * unmerged NON-spike worktree may be torn down after the discard warning. The
   * parent decides eligibility (kind !== 'spike'); the not-ready scoping is applied
   * here. Spikes stay locked until their outcome is graduated (task 15).
   */
  allowDiscard?: boolean;
}

/** Which reclaimable parts of a landed worktree the user chose to clean up. */
export interface TeardownPartSelection {
  /** Remove the on-disk worktree. */
  worktree: boolean;
  /** Delete the branch ref. */
  branch: boolean;
  /** Delete these run records (by id). */
  runIds: string[];
}

// The landing modes, as the segments of the "Landing strip" chooser. `tab` is the
// terse segment label (also each radio's accessible name); `icon` is the segment
// glyph. The per-segment scenario copy comes from landModeDetail (provenance-aware).
const STRATEGIES: ReadonlyArray<{ value: LandStrategy; tab: string; icon: LucideIcon }> = [
  { value: 'ff', tab: 'Fast-forward', icon: FastForward },
  { value: 'merge', tab: 'Merge commit', icon: GitMerge },
  { value: 'pr', tab: 'Pull request', icon: GitPullRequest },
];

/**
 * A single at-a-glance fact chip in the vitals row (mockup `.vital .seg`). With a
 * `sub`, it stacks into two rows (label/value on top, the sub indented beneath) —
 * used to hang the on-disk size under a local Environment chip.
 */
function Vital({
  icon: Icon,
  label,
  value,
  tone,
  sub,
  faded,
  iconTone,
}: {
  icon: LucideIcon;
  label: string;
  /** Omit for a label-only chip (e.g. a worker-less worktree's faded "Worker"). */
  value?: string;
  tone?: string;
  sub?: string;
  faded?: boolean;
  /** Glyph colour — defaults to muted; the Environment glyph takes the Provenance blue. */
  iconTone?: string;
}) {
  return (
    // The glyph is vertically centred against the (possibly two-line) content via
    // the chip's `align-items: center` — so a local Environment chip's on-disk sub
    // hangs under the value while the icon stays centred beside both lines. The
    // rail's `items-stretch` makes a single-line chip match a two-line sibling.
    <span className={cn('vital seg', faded && 'opacity-50')}>
      <Icon className={cn('h-3.5 w-3.5 shrink-0', iconTone ?? 'text-muted-foreground')} />
      <span className="flex flex-col">
        <span className="inline-flex items-center gap-[0.45rem]">
          <span className="text-xs text-muted-foreground">{label}</span>
          {value && <span className={`mono text-xs font-semibold ${tone ?? 'text-foreground'}`}>{value}</span>}
        </span>
        {sub && <span className="mono text-[11px] text-subtle">{sub}</span>}
      </span>
    </span>
  );
}

/** The environment the latest run executed in — local unless a cloud run produced the branch. */
function environmentOf(runs?: readonly BranchRunProvenance[]): 'local' | 'cloud' {
  return runs?.[0]?.where ?? 'local';
}

/** The base-cap note: whether the base has moved since the branch forked. */
function baseCapNote(provenance: WorktreeProvenance): string {
  if (provenance.behind === 0) return "branched here, hasn't moved since";
  return `${provenance.base} has moved ${provenance.behind} commit${provenance.behind === 1 ? '' : 's'} since`;
}

/** The "N ahead · M behind" branch-position phrase, shown in the vitals, branch panel, and land intro. */
function aheadBehind(provenance: WorktreeProvenance): string {
  return `${provenance.ahead} ahead · ${provenance.behind} behind`;
}

/**
 * Whether a landing mode can run for THIS branch, the one-line copy for its
 * segment, and an optional short caveat chip. When `available` is false the copy
 * is the REASON it's disabled, shown on a clearly-disabled segment. Only a true
 * conflict disables a mode — a branch that's merely behind can still fast-forward
 * after a rebase, so that stays available with a "rebase first" caveat. A PR can
 * always be raised. With no provenance wired we don't gate. The branch position
 * (ahead · behind) lives in Provenance, not here.
 */
function landMode(
  value: LandStrategy,
  provenance?: WorktreeProvenance,
): { available: boolean; detail: string; caveat?: string } {
  if (value === 'pr') return { available: true, detail: 'Push the branch to origin and open a pull request for review.' };
  if (value === 'merge') {
    if (provenance?.mergeability === 'conflict')
      return { available: false, detail: 'Conflicts with main to resolve before a merge commit can land.' };
    return { available: true, detail: 'Add an explicit merge commit joining the branch onto main.' };
  }
  // fast-forward
  if (!provenance) return { available: true, detail: 'Replay the commits straight onto main — linear history, no merge node.' };
  if (provenance.mergeability === 'fast-forward')
    return { available: true, detail: 'A clean fast-forward is available — replay the commits onto main, linear.' };
  if (provenance.mergeability === 'conflict')
    return { available: false, detail: 'Cannot fast-forward cleanly — conflicts with main to resolve first.' };
  if (provenance.mergeability === 'unknown')
    // Mergeability not yet computed — don't claim a rebase is needed; stay neutral.
    return { available: true, detail: 'Replay the commits straight onto main — linear history, no merge node.' };
  // Behind main but cleanly mergeable: a fast-forward is still reachable, but
  // only after rebasing the branch onto main first.
  return { available: true, detail: 'Main has moved on — rebase onto it first, then it fast-forwards cleanly.', caveat: 'rebase first' };
}

/** A small uppercase-mono tone chip, self-contained (the dashboard has no `.pill-*` variants). */
function TonePill({ varName, children }: { varName: string; children: ReactNode }) {
  return (
    <span
      className="mono inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
      style={{ color: `var(${varName})`, background: `color-mix(in oklab, var(${varName}) 16%, transparent)` }}
    >
      {children}
    </span>
  );
}

/** "Jun 22, 11:24" — null when the run hasn't ended (still running) or the date is unparseable. */
function formatFinished(iso?: string): string | null {
  if (!iso) return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}

/** The run-status chip's label + tone var (completed is the common, done-toned case). */
function runStatusChip(status: BranchRunProvenance['status']): { label: string; varName: string } {
  if (status === 'completed') return { label: 'tasks complete', varName: '--color-done' };
  if (status === 'running') return { label: 'running', varName: '--color-blue' };
  if (status === 'failed') return { label: 'failed', varName: '--color-phase-red' };
  return { label: status, varName: '--color-warn' };
}

/** Stable per-work-item key for grouping delivered tasks (distinct from core's
 *  `containerKey` — this one carries the fix/prd slug shape the UI groups on). */
function deliveredContainerKey(c: WorktreeContentContainer): string {
  return c.kind === 'fix' ? `fix:${c.fix}` : `prd:${c.prd}/${c.feature}`;
}

/** A work item's grouped delivered tasks + its identity and n/n count. */
interface WorkItemGroupData {
  key: string;
  kind: WorktreeContentContainer['kind'];
  title: string;
  slug: string;
  done: number;
  total: number;
  tasks: DeliveredTask[];
}

/**
 * Group delivered tasks by their work-item container, in first-appearance order.
 * Identity (title/slug) comes off the container each task carries; the n/n count
 * comes from `contents` (the authoritative per-item totals), falling back to the
 * delivered count when a container isn't represented there.
 */
function groupDeliveredTasks(
  deliveredTasks: readonly DeliveredTask[],
  contents?: WorktreeContents,
): WorkItemGroupData[] {
  const totals = new Map<string, { done: number; total: number }>();
  for (const fix of contents?.fixes ?? []) {
    totals.set(`fix:${fix.fix}`, { done: fix.completedTaskCount, total: fix.totalTaskCount ?? fix.completedTaskCount });
  }
  for (const prd of contents?.prds ?? []) {
    for (const f of prd.features) {
      totals.set(`prd:${prd.prd}/${f.feature}`, { done: f.completedTaskCount, total: f.totalTaskCount ?? f.completedTaskCount });
    }
  }

  // Map iteration preserves insertion order, so grouping into it keeps
  // first-appearance order without a parallel key list.
  const byKey = new Map<string, WorkItemGroupData>();
  for (const task of deliveredTasks) {
    const c = task.container;
    const key = deliveredContainerKey(c);
    const existing = byKey.get(key);
    if (existing) {
      existing.tasks.push(task);
      continue;
    }
    const count = totals.get(key);
    byKey.set(key, {
      key,
      kind: c.kind,
      title: c.kind === 'fix' ? c.fixTitle ?? c.fix : c.featureTitle ?? c.feature,
      slug: c.kind === 'fix' ? `fix · ${c.fix}` : `prd · ${c.prd} / ${c.feature}`,
      done: count?.done ?? 0,
      total: count?.total ?? 0,
      tasks: [task],
    });
  }
  // Fall back to the delivered count when contents didn't carry a total.
  return [...byKey.values()].map((g) => (g.total > 0 ? g : { ...g, done: g.tasks.length, total: g.tasks.length }));
}

/** A "N fixes · M features" summary of the branch's work items, from contents
 *  (the authoritative list) so it shows even before any per-task commit lands. */
function workItemsSummary(contents?: WorktreeContents): string {
  if (!contents) return '';
  const fixes = contents.fixes.length;
  const features = contents.prds.reduce((n, p) => n + p.features.length, 0);
  const parts: string[] = [];
  if (fixes > 0) parts.push(`${fixes} ${fixes === 1 ? 'fix' : 'fixes'}`);
  if (features > 0) parts.push(`${features} ${features === 1 ? 'feature' : 'features'}`);
  return parts.join(' · ');
}

/** One collapsible work-item group: identity header (glyph · title · slug · n/n)
 *  over its own delivered-task rows. Collapsing keeps the identity row so a
 *  many-item branch reads as a compact index. */
function WorkItemGroup({ group, defaultOpen }: { group: WorkItemGroupData; defaultOpen: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  // Match the rail convention: the kind tone (blue fix · violet plan) while in
  // progress, green (done tone) once every task in the item has landed.
  const complete = group.total > 0 && group.done === group.total;
  const { Icon } = KIND_META[group.kind];
  const iconTone = complete ? 'text-done' : KIND_META[group.kind].tone;
  const tileBg = complete ? 'bg-done/15' : group.kind === 'prd' ? 'bg-primary/15' : 'bg-blue-500/15';
  return (
    <div data-testid="work-item-group" className="panel-flat overflow-hidden rounded-xl">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="hoverable flex w-full items-center gap-2.5 p-3 text-left"
      >
        <ChevronDown className={cn('h-4 w-4 shrink-0 text-subtle transition-transform', !open && '-rotate-90')} />
        <span className={cn('flex h-7 w-7 shrink-0 items-center justify-center rounded-lg', tileBg)}>
          <Icon className={cn('h-4 w-4', iconTone)} />
        </span>
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm font-medium">{group.title}</div>
          <div className="mono truncate text-xs text-subtle">{group.slug}</div>
        </div>
        <span
          data-testid="work-item-count"
          className={cn('mono shrink-0 text-xs', complete ? 'text-done' : 'text-subtle')}
        >
          {group.done} / {group.total}
        </span>
      </button>
      {open && (
        <ul className="space-y-1.5 border-t border-border/60 p-3 text-sm">
          {group.tasks.map((t, i) => (
            <li key={t.sha ?? i} className="flex items-start gap-2">
              <CircleCheck className="mt-0.5 h-4 w-4 shrink-0 text-done" />
              <span className="min-w-0 flex-1">{t.description}</span>
              {t.sha && <span className="mono shrink-0 text-xs text-subtle">{t.sha.slice(0, 7)}</span>}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * The branch git-graph: the base cap, a node, the delivered-tasks list, a branch
 * panel, and the unmerged tip while the branch hasn't landed. Sourced from
 * `provenance`; the node shows the worker `run` when one backs the branch, else an
 * interactive-worktree node — so the graph renders for ANY deliverable worktree, not
 * only worker runs.
 */
function RunSection({
  provenance,
  run,
  runEnv,
  landed,
  tasks,
  deliveredTasks,
  contents,
}: {
  provenance: WorktreeProvenance;
  run?: BranchRunProvenance;
  runEnv: RunEnvironment;
  landed: boolean;
  tasks?: { done: number; total: number };
  deliveredTasks?: readonly DeliveredTask[];
  contents?: WorktreeContents;
}) {
  const finished = run ? formatFinished(run.endedAt) : null;
  const status = run ? runStatusChip(run.status) : null;
  const EnvIcon = runEnv === 'cloud' ? Cloud : HardDrive;
  const envLabel = runEnv === 'cloud' ? 'cloud' : 'local worktree';
  const sectionLabel = run ? 'The run' : 'The branch';
  const groups =
    deliveredTasks && deliveredTasks.length > 0 ? groupDeliveredTasks(deliveredTasks, contents) : [];
  // A single work item auto-expands; a multi-item branch collapses every group by
  // default so it reads as a compact index.
  const autoOpenGroups = groups.length === 1;
  const deliveredSummary = [workItemsSummary(contents), tasks ? `${tasks.done} / ${tasks.total} tasks` : '']
    .filter(Boolean)
    .join(' · ');
  return (
    <section aria-label={sectionLabel}>
      <p className="eyebrow mb-3 text-[10px] text-subtle">{sectionLabel}</p>
      <div className="graph">
        <div className="gcap">
          <GitCommitHorizontal className="h-4 w-4 text-blue" />
          <span className="mono text-sm font-medium">{provenance.base}</span>
          {provenance.baseSha && (
            <span className="mono text-[11px] text-subtle">{provenance.baseSha.slice(0, 7)}</span>
          )}
          <span className="text-xs text-muted-foreground">— {baseCapNote(provenance)}</span>
        </div>

        <div className="gnode panel-flat my-3 rounded-2xl p-5">
          {/* Top row: the worktree/run identity (left) and the header-less branch
              box (right), top-aligned on the same row so the tasks below run full
              width. */}
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="flex min-w-0 items-center gap-2.5">
              <span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-blue/15 text-blue">
                <EnvIcon className="h-4 w-4" />
              </span>
              <div className="min-w-0">
                {run ? (
                  <>
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="mono text-sm font-semibold">{run.runId}</span>
                      <TonePill varName="--color-blue">
                        <EnvIcon className="h-3 w-3" />
                        {envLabel}
                      </TonePill>
                      {status && <TonePill varName={status.varName}>{status.label}</TonePill>}
                    </div>
                    <p className="text-xs text-muted-foreground">
                      worker <span className="text-foreground">{run.worker}</span>
                      {finished && <> · finished {finished}</>}
                    </p>
                  </>
                ) : (
                  // Interactive worktree: the env glyph + "Local worktree" says it
                  // all — no redundant title or "worked locally" subtext.
                  <span className="text-sm font-semibold">Local worktree</span>
                )}
              </div>
            </div>

            {/* Branch box — header-less, top-aligned beside the identity. A single
                row: the branch ref (left) and its diff size (right). The raw
                commit count is dropped (it's ~4 commits/task — noise); position
                lives in the accordion header, on-disk size in the Environment
                vitals above. */}
            <div
              data-testid="branch-box"
              className="panel-flat flex w-full shrink-0 items-center justify-between gap-3 rounded-xl p-3.5 text-sm sm:w-auto sm:min-w-[240px]"
            >
              <span className="mono min-w-0 truncate text-xs">{provenance.branch}</span>
              <span className="mono whitespace-nowrap text-xs">
                <span className="t-good">+{provenance.insertions}</span>{' '}
                <span className="t-bad">−{provenance.deletions}</span>
              </span>
            </div>
          </div>

          {/* Work delivered — one collapsible group per work item, so a branch
              carrying several fixes / features reads as a grouped index rather
              than one flat mixed list. Hidden once landed: a merged worktree's
              delivered facts are unreliable (introduced-scoped ⇒ empty, or
              reachability-inherited), so the merged-to-main footer below stands
              in for it (fix ff-merged-worktree-loses-cleanup-row). */}
          {!landed && (
            <div className="mt-4">
              <p className="eyebrow mb-2 text-[10px] text-subtle">
                Work delivered{deliveredSummary ? ` · ${deliveredSummary}` : ''}
              </p>
              {groups.length > 0 ? (
                <div className="space-y-2.5">
                  {groups.map((g) => (
                    <WorkItemGroup key={g.key} group={g} defaultOpen={autoOpenGroups} />
                  ))}
                </div>
              ) : (
                <p className="text-xs text-muted-foreground">No per-task commits recorded for this run.</p>
              )}
            </div>
          )}
        </div>

        {/* The tip cap: a FILLED done node once merged (the branch is integrated),
            else the dashed amber "open" ring of an unmerged tip. */}
        <div className={landed ? 'gcap merged' : 'gcap open'}>
          <span className="mono text-sm font-medium">{provenance.base}</span>
          {landed ? (
            <TonePill varName="--color-done">merged to main</TonePill>
          ) : (
            <TonePill varName="--color-warn">not merged yet</TonePill>
          )}
        </div>
      </div>
    </section>
  );
}

/**
 * Human-readable worktree size, decimal units to match the mockup's "196 MB". Only
 * the two tiers a checkout actually spans — MB (rounded) and, for a large tree, GB
 * (one decimal). Sub-MB worktrees don't occur (node_modules alone dwarfs that), and
 * a zero size is suppressed by the caller, so no smaller tier is carried.
 */
function formatBytes(bytes: number): string {
  if (bytes >= 1e9) return `${(bytes / 1e9).toFixed(1)} GB`;
  return `${Math.round(bytes / 1e6)} MB`;
}

/**
 * One collapsible accordion section in the island body. The header is a button
 * (chevron + icon + title, with an optional trailing summary chip always shown —
 * e.g. the branch position on Provenance); the body renders only when open, so a
 * collapsed section costs no vertical real estate. The section carries an
 * `aria-label` (= title) so it is a
 * queryable region, and the toggle's accessible name is `Toggle <title> section`
 * to stay distinct from any action button inside.
 *
 * `tone="blue"` tints the whole section as the active action right now — the
 * Landing strip before landing, the Teardown after. Only one section is toned at
 * a time, so the blue tracks where the next move is.
 */
function CollapsibleSection({
  title,
  icon: Icon,
  open,
  onToggle,
  summary,
  tone,
  children,
}: {
  title: string;
  icon: LucideIcon;
  open: boolean;
  onToggle: () => void;
  summary?: ReactNode;
  tone?: 'blue';
  children: ReactNode;
}) {
  const blue = tone === 'blue';
  const accent = blue ? 'text-blue-500' : 'text-muted-foreground';
  return (
    <section aria-label={title} className={cn('border-b border-border last:border-0', blue && 'bg-blue-500/[0.06]')}>
      <button
        type="button"
        aria-expanded={open}
        aria-label={`Toggle ${title} section`}
        onClick={onToggle}
        className={cn('flex w-full items-center gap-2.5 px-6 py-4 text-left transition-colors', blue ? 'hover:bg-blue-500/10' : 'hover:bg-foreground/[0.02]')}
      >
        {open ? (
          <ChevronDown className={cn('h-4 w-4 shrink-0', accent)} />
        ) : (
          <ChevronRight className={cn('h-4 w-4 shrink-0', accent)} />
        )}
        <Icon className={cn('h-4 w-4 shrink-0', accent)} />
        <span className="display flex-1 text-base font-bold">{title}</span>
        {summary}
      </button>
      {open && <div className="px-6 pb-6">{children}</div>}
    </section>
  );
}

export function WorktreeMergeContent({
  onClose,
  title,
  contents,
  acceptanceState,
  mergeState,
  isWorkerRun,
  provenance,
  runs,
  tasks,
  deliveredTasks,
  unlandedCommits,
  busy = false,
  landLog,
  landError = false,
  landFailure,
  teardownOnly = false,
  cleanedUp = false,
  teardownError,
  landingState,
  onLand,
  onRaise,
  onReject,
  onPrepare,
  onRestore,
  onForceTeardown,
  onTeardown,
  allowDiscard = false,
}: WorktreeMergeContentProps) {
  const [rejecting, setRejecting] = useState(false);
  const [reason, setReason] = useState('');
  // Which mode a land is in flight for — drives the spinner on that one segment.
  const [landingMode, setLandingMode] = useState<LandStrategy | null>(null);

  const landed = acceptanceState === 'landed';

  // A not-ready worktree splits two ways. A worker run, or genuinely unfinished
  // tracked work (a partial task tally), is "work unfinished" — the
  // incomplete-work warning stands. But an interactive worktree with NO run
  // backing it (the fix's "no run record" case — `tb go` work, or work merged in
  // locally) that is a clean fast-forward with nothing incomplete is "untracked
  // but landable": offer the ff land as a recommended move, no false
  // "incomplete work" warning (fix: worktree-ff-land-without-run-record). Gated on
  // !isWorkerRun (the canonical no-run signal, not inferred from the tally) and
  // KNOWN fast-forwardability, so a worker run or a no-provenance worktree keeps
  // the conservative warning.
  const incompleteWork = !!tasks && tasks.total > 0 && tasks.done < tasks.total;
  const cleanFfUntracked =
    acceptanceState === 'not-ready' &&
    !isWorkerRun &&
    !incompleteWork &&
    provenance?.mergeability === 'fast-forward';

  // The type-aware header glyph + tone, derived from what the branch delivers.
  const { tone: kindTone, Icon: KindIcon } = kindMeta(contents);

  // The three body sections collapse to save the fixed-height panel's real
  // estate. Defaults follow the lifecycle: pre-land we lead with provenance + the
  // landing strip and tuck teardown away; once landed (or in spike teardown-only
  // mode) the landing strip is done, so it collapses and teardown opens.
  // Once landed (or in spike teardown-only), clean-up is the focus, so Provenance
  // defaults collapsed and the checklist leads; pre-land it leads with provenance.
  const [provOpen, setProvOpen] = useState(!landed && !teardownOnly);
  const [landOpen, setLandOpen] = useState(!landed && !teardownOnly);
  const [teardownOpen, setTeardownOpen] = useState(landed || teardownOnly);

  // Transient choices reset naturally: in the overlay the shared Island unmounts
  // this content on close, so a reopen remounts fresh; inline it simply persists.

  // Re-seat the section defaults whenever the panel (re)opens or its lifecycle
  // state flips — a reopen, or a land that moves the branch to `landed`, should
  // land on the right open/closed shape. User toggles in between persist (this
  // only re-runs on these deps, not on every render).
  useEffect(() => {
    setProvOpen(!landed && !teardownOnly);
    setLandOpen(!landed && !teardownOnly);
    setTeardownOpen(landed || teardownOnly);
  }, [landed, teardownOnly]);
  // Teardown is available once work has landed — or always, in teardown-only
  // (spike clean-up) mode, where there is nothing to land first. It is ALSO offered
  // for an unmerged (not-ready) worktree when the parent allows a discard (task 14:
  // non-spike rows); the existing force-discard warning then names what's lost.
  const canTeardown = landed || teardownOnly || (allowDiscard && acceptanceState === 'not-ready');
  // A refused (not cleaned-up) teardown surfaces its reason; the force escape
  // hatch additionally needs the container to have wired the retry. Hoisted so
  // the warning, the description link, and the button stay in lockstep.
  const showTeardownError = !!teardownError && !cleanedUp;
  // The latest run backs the Environment + Worker vitals.
  const runEnv = environmentOf(runs);
  const latestRun = runs?.[0];

  // The per-part clean-up selection defaults to ALL reclaimable parts — the
  // worktree, every run record, and the branch — EXCEPT an unmerged branch. A
  // branch with commits not on main (`ahead > 0`) is left unchecked (and says so)
  // because `git branch -D` would discard them: "unmerged work is never
  // auto-removed". Re-seeded whenever the panel (re)opens, the branch's
  // merged-ness flips, or the run set changes.
  const branchMerged = provenance?.ahead === 0;
  // The on-disk worktree is PRE-SELECTED for removal by default UNLESS the branch
  // is positively ahead of main (`ahead > 0`) — that carries unlanded work, an
  // actively-worked tree, so auto-removing its checkout could pull the ground from
  // under a live session. It stays reclaimable either way; an ahead worktree is
  // just left unchecked so the user opts in deliberately. Absent/zero ahead ⇒
  // pre-selected (the prior default).
  const preselectWorktree = (provenance?.ahead ?? 0) === 0;
  const runIdsKey = (runs ?? []).map((r) => r.runId).join(',');
  const [selWorktree, setSelWorktree] = useState(preselectWorktree);
  const [selBranch, setSelBranch] = useState(branchMerged);
  const [selRuns, setSelRuns] = useState<ReadonlySet<string>>(() => new Set(runs?.map((r) => r.runId) ?? []));
  useEffect(() => {
    setSelWorktree(preselectWorktree);
    setSelBranch(branchMerged);
    setSelRuns(new Set(runs?.map((r) => r.runId) ?? []));
    // runs is intentionally read via runIdsKey (a stable id digest) so the effect
    // re-seeds on a genuine run-set change, not on every new array identity.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [branchMerged, preselectWorktree, runIdsKey]);
  const toggleRun = (runId: string, on: boolean) =>
    setSelRuns((prev) => {
      const next = new Set(prev);
      if (on) next.add(runId);
      else next.delete(runId);
      return next;
    });
  // Guard against a stale run selection: the island never unmounts, so a prop
  // refetch can drop a run the user had checked. Only count/post the run ids still
  // shown, so the POST never carries an id whose checkbox has vanished.
  const visibleRunIds = new Set(runs?.map((r) => r.runId));
  const selectedRunIds = [...selRuns].filter((id) => visibleRunIds.has(id));
  const selectedCount = (selWorktree ? 1 : 0) + (selBranch ? 1 : 0) + selectedRunIds.length;
  const selection: TeardownPartSelection = { worktree: selWorktree, branch: selBranch, runIds: selectedRunIds };
  const branchName = provenance?.branch ?? title;

  // Caveats known upfront from provenance: removing a DIRTY worktree needs --force
  // (`git worktree remove` refuses uncommitted/untracked work), and deleting an
  // UNMERGED branch (`ahead > 0`) discards its off-main commits. When a CHECKED
  // part carries a caveat the single action becomes Force — presented immediately,
  // never as a second button after a predictable refusal.
  const worktreeDirty = provenance?.dirty === true;
  const branchAhead = provenance?.ahead ?? 0;
  const dirtyWorktreeSelected = selWorktree && worktreeDirty;
  // `branchAhead > 0` is the precise unmerged test — and, unlike `!branchMerged`,
  // it is correctly false when provenance is absent (no ahead-count ⇒ no caveat).
  const unmergedBranchSelected = selBranch && branchAhead > 0;
  const forceNeeded = dirtyWorktreeSelected || unmergedBranchSelected;
  // What Force will permanently discard — the red note beside the action.
  const forceDiscards = [
    dirtyWorktreeSelected ? "the worktree's uncommitted changes" : undefined,
    unmergedBranchSelected ? `the branch's ${branchAhead} commit${branchAhead === 1 ? '' : 's'} not on main` : undefined,
  ]
    .filter(Boolean)
    .join(' and ');

  // Clicking a mode segment IS the land — there is no separate confirm button.
  // It dispatches that mode and collapses the other sections down to the runway,
  // so the strip is the sole focus while the merge is in flight.
  const landWith = (value: LandStrategy) => {
    setLandingMode(value);
    setProvOpen(false);
    setTeardownOpen(false);
    setLandOpen(true);
    if (value === 'pr') onRaise();
    else onLand(value === 'merge' ? 'merge' : 'ff-only');
  };

  const confirmReject = () => {
    const trimmed = reason.trim();
    if (trimmed.length === 0) return; // a rejection must carry a reason
    onReject(trimmed);
  };

  return (
    <>
      {/* Header — pinned at the top of the fixed-height panel. The eyebrow and the
          close button share the top row; below them the type-aware kind glyph
          leads the title row, with Environment + Worker on a RHS rail aligned to
          the title (merge state + tasks dropped). */}
      <div data-testid="island-header" className="shrink-0 border-b border-border p-6">
        <div className="flex items-start justify-between gap-4">
          {/* Eyebrow + the shared lifecycle pill, so the detail header reads the
              same merge-state as the sidebar card for this worktree (task 11). */}
          <div className="flex min-w-0 items-center gap-2">
            <p className={cn('eyebrow shrink-0 text-[10px]', kindTone)}>Worktree · Merge</p>
            <WorktreeStatusPill status={mergeState} />
          </div>
          {onClose && (
            <button
              aria-label="Close"
              className="-mt-1 shrink-0 text-muted-foreground hover:text-foreground"
              onClick={onClose}
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>
        <div className="mt-3 flex items-start justify-between gap-4">
          {/* Title block — the kind glyph beside a title + subtitle column, so the
              subtitle aligns under the title (not under the glyph). */}
          <div className="flex min-w-0 gap-4">
            <KindIcon className={cn('mt-1 h-5 w-5 shrink-0', kindTone)} />
            <div className="min-w-0">
              <h2 className="display truncate text-xl font-bold">{title}</h2>
              {/* The old truncated work-items label lived here; the branch's work
                  items are now enumerated by the "Work delivered" groups in the
                  Provenance section, so the header carries just the branch title. */}
            </div>
          </div>

          {/* RHS rail — Environment + Worker, aligned to the title row. `items-stretch`
              makes the Worker chip match the taller (two-line) Environment chip
              exactly. Degrades out when no provenance is wired. */}
          {provenance && (
            <div className="flex shrink-0 flex-wrap items-stretch justify-end gap-2" aria-label="Worktree vitals">
              {/* Environment: for a local worktree the on-disk size hangs below as
                  a second row; a cloud run has no checkout, so single row. */}
              <Vital
                icon={runEnv === 'cloud' ? Cloud : HardDrive}
                iconTone="text-blue"
                label="Environment"
                value={runEnv === 'cloud' ? 'cloud' : 'local worktree'}
                sub={
                  // Only when it rounds to ≥ 1 MB — a sub-MB worktree would read
                  // "0 MB on disk", which is noise, so drop the line entirely.
                  runEnv !== 'cloud' && provenance.sizeBytes !== undefined && provenance.sizeBytes >= 1_000_000
                    ? `${formatBytes(provenance.sizeBytes)} on disk`
                    : undefined
                }
              />
              {/* Worker: the backing run's worker NAME as the value, its MODEL on
                  the second line. An interactive `tb go` worktree (no run) shows
                  just a faded "Worker" label. Stretches to the Environment height.
                  Intentionally keyed off the actual `latestRun`, NOT `isWorkerRun`
                  (which still gates Reject below): the run provenance carries the
                  name/model the flag can't, so an isWorkerRun-without-runs branch
                  correctly falls back to the faded label rather than a bare name. */}
              <Vital
                icon={Bot}
                iconTone="text-done"
                label="Worker"
                value={latestRun?.worker}
                sub={latestRun?.model}
                tone="text-done"
                faded={!latestRun}
              />
            </div>
          )}
        </div>
      </div>

      {/* Collapsible body — Provenance / Landing strip / Teardown. Each section
          costs no vertical real estate when collapsed; the body scrolls within
          the fixed-height panel. Default open/closed follows the lifecycle. */}
      <div className="min-h-0 flex-1 overflow-y-auto">
        {/* Provenance — the branch graph (base → node → unmerged tip), sourced
            from provenance; the node is the worker run, else an interactive node. */}
        {provenance && (
          <CollapsibleSection
            title="Provenance"
            icon={GitBranch}
            open={provOpen}
            onToggle={() => setProvOpen((v) => !v)}
            summary={
              <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                <ArrowUp className="h-3.5 w-3.5" />
                vs main
                <span className="mono">{aheadBehind(provenance)}</span>
              </span>
            }
          >
            <RunSection
              provenance={provenance}
              run={runs?.[0]}
              runEnv={runEnv}
              landed={landed}
              tasks={tasks}
              deliveredTasks={deliveredTasks}
              contents={contents}
            />
          </CollapsibleSection>
        )}

        {/* Landing strip — how the branch lands. The land chooser is offered while
            there is something to land (pending-acceptance) AND for in-progress
            (not-ready) work, which is mechanically mergeable too — there it sits
            behind an incomplete-work warning (can-vs-should, task 9/13). A landed or
            rejected branch shows a one-line status. Hidden in spike teardown-only mode. */}
        {!teardownOnly && (
          // tone (blue) = "recommended next move": only pending-acceptance (complete
          // work) gets it; a not-ready chooser stays untoned on purpose — the
          // incomplete-work warning is the focus, we don't nudge the operator to land
          // unfinished work as the obvious next step (task 13).
          <CollapsibleSection
            title={landed ? 'Landed on main — nothing left to land' : 'Landing strip'}
            icon={GitMerge}
            open={landOpen}
            onToggle={() => setLandOpen((v) => !v)}
            tone={acceptanceState === 'pending-acceptance' || cleanFfUntracked ? 'blue' : undefined}
          >
            {acceptanceState === 'pending-acceptance' || acceptanceState === 'not-ready' ? (
              <section aria-label="Land this work">
                {/* Incomplete-work warning (task 13): an in-progress worktree can be
                    merged, but the operator must see that unfinished work is being
                    left behind. The header eyebrow/pill already reads "in progress";
                    this is the actionable companion in the landing strip. */}
                {acceptanceState === 'not-ready' && !cleanFfUntracked && (
                  <div
                    data-testid="incomplete-work-warning"
                    role="alert"
                    className="mb-3 flex items-start gap-2 rounded-xl border px-3 py-2 text-xs"
                    style={{
                      borderColor: 'color-mix(in oklab, var(--color-warn) 40%, transparent)',
                      background: 'color-mix(in oklab, var(--color-warn) 8%, transparent)',
                    }}
                  >
                    <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" style={{ color: 'var(--color-warn)' }} />
                    <span className="leading-snug text-muted-foreground">
                      You're merging <strong className="text-foreground">incomplete work</strong>
                      {/* Only show the count when it's a meaningful PARTIAL — a 0-of-0
                          or a done===total (the per-task count disagreeing with the
                          not-ready lattice) would contradict "incomplete work". */}
                      {tasks && tasks.total > 0 && tasks.done < tasks.total
                        ? ` — ${tasks.done} of ${tasks.total} tasks done`
                        : ''}
                      . The remaining work won't be included.
                    </span>
                  </div>
                )}
                {/* Staged landing control (island-landing-states): when the row
                    carries a server-derived landingState, the strategy row BECOMES a
                    staged control — Prepare (reconcile + verify) → ready · verified →
                    Land ff, with secondary unverified merge/PR — replacing the direct
                    chooser below. The legacy ff/merge/PR chooser stays as the fallback
                    for rows that haven't wired the landing state. */}
                {landingState && onPrepare ? (
                  <StagedLandingControl
                    landingState={landingState}
                    branch={branchName}
                    busy={busy}
                    onPrepare={onPrepare}
                    onLand={onLand}
                    onRaise={onRaise}
                    {...(onRestore ? { onRestore } : {})}
                    {...(landLog ? { landLog } : {})}
                  />
                ) : (
                  <>
                {/* Mode chooser — three double-height action cards. Each is a glyph,
                    the mode name, and what it will do for THIS branch; CLICKING a
                    card lands via that mode (no separate confirm button). The
                    recommended mode (clean ff) is highlighted; a mode that can't run
                    is clearly disabled with the reason as its copy. */}
                <div role="group" aria-label="How it lands" className="flex flex-col gap-2 sm:flex-row sm:items-stretch">
                  {STRATEGIES.map((s) => {
                    const Icon = s.icon;
                    const mode = landMode(s.value, provenance);
                    const recommended = s.value === 'ff' && provenance?.mergeability === 'fast-forward';
                    const isLanding = busy && landingMode === s.value;
                    return (
                      <button
                        key={s.value}
                        type="button"
                        aria-label={s.value === 'pr' ? 'Raise pull request' : `Land — ${s.tab.toLowerCase()}`}
                        disabled={!mode.available || busy}
                        onClick={() => landWith(s.value)}
                        className={cn(
                          'flex flex-1 basis-0 flex-col gap-1.5 rounded-xl border p-3 text-left transition-colors',
                          !mode.available
                            ? 'cursor-not-allowed border-border bg-transparent opacity-60'
                            : recommended
                              ? 'border-blue-500/50 bg-blue-500/15 hover:bg-blue-500/20'
                              : 'border-border bg-foreground/[0.02] hover:border-blue-500/40 hover:bg-blue-500/[0.06]',
                          busy && mode.available && 'opacity-70',
                        )}
                      >
                        <span className={cn('flex items-center gap-1.5 text-sm font-semibold', mode.available ? 'text-foreground' : 'text-muted-foreground')}>
                          {isLanding ? <Loader2 className="h-4 w-4 shrink-0 animate-spin" /> : <Icon className="h-4 w-4 shrink-0" />}
                          {s.tab}
                          {recommended && (
                            <span
                              className="ml-auto rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
                              style={{ color: 'var(--color-done)', background: 'color-mix(in oklab, var(--color-done) 16%, transparent)' }}
                            >
                              recommended
                            </span>
                          )}
                          {!recommended && mode.available && mode.caveat && (
                            <span
                              className="ml-auto rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
                              style={{ color: 'var(--color-warn)', background: 'color-mix(in oklab, var(--color-warn) 16%, transparent)' }}
                            >
                              {mode.caveat}
                            </span>
                          )}
                          {!mode.available && <Ban className="ml-auto h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
                        </span>
                        <span className="text-xs leading-snug text-muted-foreground">
                          {isLanding ? 'Landing…' : mode.detail}
                        </span>
                      </button>
                    );
                  })}
                </div>

                {/* A refused land (diverged / conflict) is reported with HTTP 200,
                    not a throw — surface its reason + copyable rebase hand-off so a
                    land that merged nothing isn't silent. Shown only when there's no
                    running-log to host it (no mode in flight): once a mode is clicked
                    the reason is folded into the log below, so it never double-surfaces
                    (fix: worktree-ff-land-without-run-record). */}
                {landError && landFailure && !landingMode && (
                  <div
                    data-testid="land-failure"
                    role="alert"
                    className="mt-3 flex items-start gap-2 rounded-xl border border-red-500/40 px-3 py-2 text-xs"
                    style={{ background: 'color-mix(in oklab, var(--color-phase-red) 6%, transparent)' }}
                  >
                    <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0 t-bad" />
                    <span className="mono leading-snug text-muted-foreground whitespace-pre-wrap">{landFailure}</span>
                  </div>
                )}

                {/* Live running log — appears once a mode is clicked, streaming the
                    git work to the UI. Driven by the landLog prop; until the
                    backend stream is wired it shows a starting state while busy. */}
                {landingMode && (
                  <section
                    aria-label="Land progress"
                    className={cn('mt-3 overflow-hidden rounded-xl border', landError && !busy ? 'border-red-500/40' : 'border-blue-500/30')}
                    style={{
                      background: `color-mix(in oklab, var(${landError && !busy ? '--color-phase-red' : '--color-blue'}) 6%, transparent)`,
                    }}
                  >
                    <div className={cn('flex items-center gap-2 border-b px-3 py-2', landError && !busy ? 'border-red-500/30' : 'border-blue-500/20')}>
                      {busy ? (
                        <Loader2 className="h-3.5 w-3.5 shrink-0 animate-spin text-blue-500" />
                      ) : landError ? (
                        <TriangleAlert className="h-3.5 w-3.5 shrink-0 t-bad" />
                      ) : (
                        <CheckCheck className="h-3.5 w-3.5 shrink-0 text-done" />
                      )}
                      <span className={cn('eyebrow text-[10px]', landError && !busy ? 't-bad' : 'text-blue-500')}>
                        {busy ? 'Running' : landError ? 'Failed — retry below' : 'Finished'} ·{' '}
                        {landingMode === 'pr' ? 'raise pull request' : landingMode === 'merge' ? 'merge commit' : 'fast-forward'}
                      </span>
                    </div>
                    <div role="log" aria-live="polite" className="mono max-h-48 overflow-y-auto px-3 py-2 text-xs leading-relaxed text-muted-foreground">
                      {landLog && landLog.length > 0 ? (
                        landLog.map((line, i) => (
                          <div key={i} className="whitespace-pre-wrap">
                            {line}
                          </div>
                        ))
                      ) : busy ? (
                        <div className="text-subtle">Starting…</div>
                      ) : null}
                      {/* The refused-land reason lives here once a mode is in flight —
                          the standalone alert hides while landingMode is set, so the
                          reason shows exactly once. */}
                      {landError && !busy && landFailure && (
                        <div data-testid="land-failure" className="whitespace-pre-wrap t-bad">
                          {landFailure}
                        </div>
                      )}
                      {busy && <div className="text-subtle" aria-hidden="true">▋</div>}
                    </div>
                  </section>
                )}
                  </>
                )}

                {/* Reject run — only for an actual worker run (an interactive
                    worktree has no run to reject; fix
                    merge-island-land-reject-on-non-worker), and only for a
                    completed-but-unaccepted run (pending-acceptance). An in-progress
                    (not-ready) run may still be live — task 13 widened the land
                    chooser to not-ready but deliberately does NOT expose reject
                    there, to avoid writing a terminal reject against a running run.
                    Hidden once a land is under way — the running log is the focus. */}
                {acceptanceState === 'pending-acceptance' && isWorkerRun && !rejecting && !landingMode && (
                  <div className="mt-3 flex justify-end">
                    <button
                      className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm text-muted-foreground hover:text-foreground"
                      onClick={() => setRejecting(true)}
                    >
                      <X className="h-4 w-4" /> Reject run
                    </button>
                  </div>
                )}

                {acceptanceState === 'pending-acceptance' && isWorkerRun && rejecting && (
                  <div className="mt-4 rounded-xl border border-border p-3">
                    <label className="block text-xs font-medium text-muted-foreground" htmlFor="reject-reason">
                      Reason for rejection
                    </label>
                    <textarea
                      id="reject-reason"
                      aria-label="Reason for rejection"
                      className="mt-1.5 w-full rounded-lg border border-border bg-transparent p-2 text-sm"
                      rows={2}
                      value={reason}
                      onChange={(e) => setReason(e.target.value)}
                    />
                    <div className="mt-2 flex justify-end gap-2">
                      <button
                        className="rounded-lg border border-border px-3 py-1.5 text-sm text-muted-foreground"
                        onClick={() => {
                          setRejecting(false);
                          setReason('');
                        }}
                      >
                        Cancel
                      </button>
                      <button
                        className="rounded-lg bg-red-600 px-3 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
                        disabled={busy}
                        onClick={confirmReject}
                      >
                        Confirm reject
                      </button>
                    </div>
                  </div>
                )}
              </section>
            ) : (
              // Only landed or rejected reach here — in-progress (not-ready) now
              // shows the chooser above, behind its incomplete-work warning.
              <p className="text-sm text-muted-foreground">
                {landed
                  ? 'Landed on main — nothing left to land.'
                  : 'This run was rejected and never landed.'}
              </p>
            )}
          </CollapsibleSection>
        )}

        {/* Clean up — gated on landed-ness (or always available in teardown-only).
            Collapsed and quiet until landed; once cleanup is the live post-merge
            action it opens and goes blue, the same accent the landing strip wore. */}
        <CollapsibleSection
          title="Clean up"
          icon={Trash2}
          open={teardownOpen}
          onToggle={() => setTeardownOpen((v) => !v)}
          tone={canTeardown ? 'blue' : undefined}
          summary={!canTeardown ? <Lock className="h-3.5 w-3.5 text-muted-foreground" /> : undefined}
        >
          <div className="rounded-2xl border border-border p-5">
            {cleanedUp ? (
              <p className="flex items-center gap-2 text-sm t-good">
                <CircleCheck className="h-4 w-4 shrink-0" />
                Cleaned up — the selected parts were removed.
              </p>
            ) : !canTeardown ? (
              <p className="flex items-center gap-2 text-sm text-muted-foreground">
                <Lock className="h-4 w-4 shrink-0" />
                {acceptanceState === 'rejected'
                  ? 'This run was rejected, not landed — remove its worktree via discard in the PRD view.'
                  : 'Available once this work is landed — nothing is removed while the branch is unlanded.'}
              </p>
            ) : (
              <>
                <p className="text-sm text-muted-foreground">
                  {teardownOnly
                    ? 'Choose what to reclaim for this finished spike. The spike — and its findings — are kept.'
                    : 'Choose which parts to reclaim. Merged-safe parts are pre-selected; unmerged work is never auto-removed.'}
                </p>
                <ul className="mt-3 space-y-1.5" role="group" aria-label="Reclaimable parts">
                  {/* Worktree — the on-disk scaffolding (with its footprint). */}
                  <li>
                    <label className="flex items-center gap-3 rounded-xl border border-border px-3 py-2 text-sm">
                      <input
                        type="checkbox"
                        className="h-4 w-4 shrink-0"
                        checked={selWorktree}
                        disabled={busy}
                        onChange={(e) => setSelWorktree(e.target.checked)}
                      />
                      <HardDrive className="h-4 w-4 shrink-0 text-muted-foreground" />
                      <span className="font-medium">Worktree</span>
                      {worktreeDirty && (
                        // The caveat, like the branch's: removing it needs --force.
                        <span className="text-xs t-bad">(uncommitted changes)</span>
                      )}
                      {provenance?.sizeBytes !== undefined && provenance.sizeBytes >= 1_000_000 && (
                        <span className="ml-auto mono text-xs text-muted-foreground">{formatBytes(provenance.sizeBytes)}</span>
                      )}
                    </label>
                  </li>
                  {/* Branch — the ref, badged `merged` once it carries nothing off trunk. */}
                  <li>
                    <label className="flex items-center gap-3 rounded-xl border border-border px-3 py-2 text-sm">
                      <input
                        type="checkbox"
                        className="h-4 w-4 shrink-0"
                        checked={selBranch}
                        disabled={busy}
                        onChange={(e) => setSelBranch(e.target.checked)}
                      />
                      <GitBranch className="h-4 w-4 shrink-0 text-muted-foreground" />
                      <span className="font-medium">Branch</span>
                      <span className="mono text-xs text-muted-foreground truncate">{branchName}</span>
                      {branchMerged ? (
                        <span className="ml-auto rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs t-good">merged</span>
                      ) : provenance && provenance.ahead > 0 ? (
                        // Why it is not pre-selected: it carries commits not on main
                        // that `git branch -D` would discard.
                        <span className="ml-auto text-xs text-muted-foreground">
                          {provenance.ahead} commit{provenance.ahead === 1 ? '' : 's'} not landed on main
                        </span>
                      ) : null}
                    </label>
                  </li>
                  {/* Run record(s) — audit data, opt-in. One row per run (id · worker). */}
                  {runs?.map((r) => (
                    <li key={r.runId}>
                      <label className="flex items-center gap-3 rounded-xl border border-border px-3 py-2 text-sm">
                        <input
                          type="checkbox"
                          className="h-4 w-4 shrink-0"
                          checked={selRuns.has(r.runId)}
                          disabled={busy}
                          onChange={(e) => toggleRun(r.runId, e.target.checked)}
                        />
                        <Bot className="h-4 w-4 shrink-0 text-muted-foreground" />
                        <span className="mono text-xs">{r.runId}</span>
                        <span className="text-xs text-muted-foreground">· {r.worker}</span>
                      </label>
                    </li>
                  ))}
                </ul>
                {/* The `ahead` commits, enumerated: `unlandedCommits` and
                    `provenance.ahead` are the SAME `base..branch` set, produced
                    together server-side, so this list and the branch's "N commits
                    not landed" caveat describe one thing. */}
                {unlandedCommits && unlandedCommits.length > 0 && (
                  <div className="mt-4" data-testid="unlanded-commits">
                    <p className="eyebrow mb-2 text-[10px] text-subtle">
                      Not yet on main — discarded if you remove the branch
                    </p>
                    <ul className="space-y-1">
                      {unlandedCommits.map((c) => (
                        <li key={c.sha} className="flex items-baseline gap-2 text-xs">
                          <span className="mono text-[11px] text-muted-foreground">{c.sha.slice(0, 7)}</span>
                          <span className="min-w-0 truncate">{c.subject}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </>
            )}
            {showTeardownError && (
              <p className="mt-2 flex items-center gap-2 text-sm t-bad">
                <TriangleAlert className="h-4 w-4 shrink-0" />
                {teardownError}
              </p>
            )}
            {/* Once cleaned up, the success line stands alone — the discard note and
                the action button are gone (nothing left to act on or warn about). */}
            {!cleanedUp && (
              <>
                {/* The selection includes a part that can only be removed by force —
                    say what that discards, in red, right above the (now Force)
                    action. No doomed plain attempt + second button: correct upfront. */}
                {forceNeeded && (
                  <p id="force-discard-note" className="mt-2 flex items-start gap-2 text-sm t-bad">
                    <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" />
                    <span>Force clean up permanently discards {forceDiscards}. Landed work on main is safe.</span>
                  </p>
                )}
                <div className="mt-3 flex justify-end">
                  <button
                    className={cn(
                      'inline-flex items-center gap-1.5 rounded-xl border px-3 py-2 text-sm disabled:opacity-50',
                      forceNeeded ? 'border-red-500/40 t-bad' : 'border-border',
                    )}
                    disabled={!canTeardown || busy || selectedCount === 0}
                    onClick={() => (forceNeeded ? onForceTeardown?.(selection) : onTeardown(selection))}
                    {...(forceNeeded ? { 'aria-describedby': 'force-discard-note' } : {})}
                  >
                    {/* Always count-bearing; flips to Force when a caveated part is checked. */}
                    {forceNeeded ? 'Force clean up' : 'Clean up'} {canTeardown ? selectedCount : 0} selected
                  </button>
                </div>
              </>
            )}
          </div>
        </CollapsibleSection>
      </div>
    </>
  );
}

export default WorktreeMergeContent;
