import React, { useCallback, useState } from 'react';
import { Copy, Check } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';

interface CopyIdButtonProps {
  /** The id / slug copied to the clipboard. */
  value: string;
  /** The kind shown in the tooltip: "Copy the {kind} ID" (the word "ID" is emphasised). */
  kind: string;
  /** Extra classes for layout (e.g. ml-1). */
  className?: string;
}

/**
 * A copy-to-clipboard affordance for an item's id. Shows just the icon (the id
 * text lives next to the title it sits beside), a check on success, and a
 * tooltip reading "Copy the {kind} ID" with the word "ID" emphasised. Stops
 * click propagation so it is safe to drop inside a clickable row (e.g. the
 * collapsible feature header).
 */
const CopyIdButton: React.FC<CopyIdButtonProps> = ({ value, kind, className = '' }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    if (!value) return;
    await navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }, [value]);

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              void handleCopy();
            }}
            aria-label={`Copy the ${kind} ID`}
            className={`inline-flex items-center hover:text-foreground transition-colors ${className}`}
          >
            {copied ? (
              <Check className="h-4 w-4 text-green-500" />
            ) : (
              <Copy className="h-4 w-4 opacity-50 hover:opacity-100" />
            )}
          </button>
        </TooltipTrigger>
        <TooltipContent>
          Copy the {kind} <span className="font-bold">ID</span>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

export default CopyIdButton;
