import { useState, type ComponentType, type ReactNode } from 'react';
import { CircleX, Plane, PlaneLanding, Trash2 } from 'lucide-react';
import type { WorkRef } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';
import MiniStatusRail from '@/components/MiniStatusRail';
import { SidebarCard } from '@/components/SidebarCard';
import { ResizablePanel, ResizablePanelGroup, ResizableHandle } from '@/components/ui/resizable';
import type { InFlightLanes, InFlightRow } from '@/hooks/useInFlight';

type LaneKey = keyof InFlightLanes;

const TABS: {
  key: LaneKey;
  label: string;
  Icon: ComponentType<{ className?: string }>;
  countClass: string;
}[] = [
  { key: 'inProgress', label: 'In progress', Icon: Plane, countClass: 'bg-blue-500/15 text-blue' },
  { key: 'readyToLand', label: 'Ready to land', Icon: PlaneLanding, countClass: 'bg-amber-500/15 text-warn' },
  // "Failed runs" — a run that crashed and needs a re-run, distinct from a
  // ready-to-land item that failed to merge and needs a rebase.
  { key: 'failed', label: 'Failed runs', Icon: CircleX, countClass: 'bg-red-500/15 text-red-500' },
  { key: 'readyToClean', label: 'Ready to clean', Icon: Trash2, countClass: 'bg-emerald-500/15 text-emerald-500' },
];

export interface InFlightViewProps {
  lanes: InFlightLanes;
  /** The selected row's key ({@link inFlightRowKey}); parent-owned for deep-linking. */
  selectedKey?: string | null;
  onSelect?: (row: InFlightRow) => void;
  /** Render the selected row's detail surface in the main pane. */
  renderDetail?: (row: InFlightRow) => ReactNode;
}

/**
 * The one operations board: a sidebar of the four job-tabbed lanes (rows are a
 * deliverable's type + title + MiniStatusRail glance) beside a main pane showing
 * the selected row's full detail. No inline row actions — the detail owns them.
 */
export function InFlightView({ lanes, selectedKey, onSelect, renderDetail }: InFlightViewProps) {
  const [active, setActive] = useState<LaneKey>('inProgress');
  const rows = lanes[active];

  const selectedRow = selectedKey
    ? [...lanes.inProgress, ...lanes.readyToLand, ...lanes.failed, ...lanes.readyToClean].find(
        (r) => inFlightRowKey(r) === selectedKey,
      )
    : undefined;

  return (
    <div className="flex h-full flex-col gap-3 p-4">
      {/* Full-width job tabs across the top of the board. */}
      <div className="flex gap-1 border-b border-border" role="tablist">
        {TABS.map(({ key, label, Icon, countClass }) => (
          <button
            key={key}
            type="button"
            role="tab"
            aria-selected={active === key}
            data-testid={`in-flight-tab-${key}`}
            onClick={() => setActive(key)}
            className={cn(
              'flex items-center gap-2 px-3 py-2 text-sm font-medium transition-colors',
              active === key ? 'border-b-2 border-primary text-primary' : 'text-muted-foreground hover:text-foreground',
            )}
          >
            <Icon className="h-4 w-4" />
            {label}
            <span
              data-testid={`in-flight-count-${key}`}
              className={cn('rounded-full px-1.5 text-xs tabular-nums', countClass)}
            >
              {lanes[key].length}
            </span>
          </button>
        ))}
      </div>

      <ResizablePanelGroup direction="horizontal" className="min-h-0 flex-1">
        <ResizablePanel defaultSize={32} minSize={22} maxSize={45}>
          <aside className="flex h-full flex-col space-y-1.5 overflow-y-auto pr-2">
            {active === 'inProgress' && (
              <p data-testid="in-flight-workers-only-note" className="px-1 pb-1 text-xs text-muted-foreground">
                Worker runs only — interactive sessions appear in the Fixes and Plans lists.
              </p>
            )}
            {rows.length === 0 ? (
              <p className="px-1 py-8 text-center text-sm text-muted-foreground">Nothing in this lane.</p>
            ) : (
              rows.map((row, i) => (
                <Row
                  key={inFlightRowKey(row) || `${row.mechanism.kind}-${i}`}
                  row={row}
                  selected={selectedKey === inFlightRowKey(row)}
                  onSelect={onSelect}
                />
              ))
            )}
          </aside>
        </ResizablePanel>

        <ResizableHandle withHandle />

        <ResizablePanel defaultSize={68}>
          <section className="h-full min-w-0 overflow-y-auto pl-2">
            {selectedRow && renderDetail ? (
              renderDetail(selectedRow)
            ) : (
              <div
                data-testid="in-flight-empty-detail"
                className="flex h-full items-center justify-center text-sm text-muted-foreground"
              >
                Select a deliverable to see its detail.
              </div>
            )}
          </section>
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  );
}

function Row({ row, selected, onSelect }: { row: InFlightRow; selected: boolean; onSelect?: (row: InFlightRow) => void }) {
  return (
    <SidebarCard
      testId="in-flight-row"
      status={row.lane}
      isSelected={selected}
      emphasized={Boolean(row.live) || selected}
      onClick={onSelect ? () => onSelect(row) : undefined}
      title={rowTitle(row)}
      pills={<KindPill workRef={row.workRef} />}
      rail={<MiniStatusRail {...rowMsr(row)} />}
      progress={null}
    />
  );
}

/**
 * Map a row to the MiniStatusRail glance props. Uses `rail` mode (not `card`)
 * so the runner and env glyphs ALWAYS render — the board's point is showing the
 * mechanism explicitly, whereas card mode hides the user glyph and the local-env
 * glyph, leaving an idle worktree card with an empty rail.
 */
function rowMsr(row: InFlightRow): Parameters<typeof MiniStatusRail>[0] {
  if (row.mechanism.kind === 'worker') {
    return {
      mode: 'rail',
      isWorkerRun: true,
      where: row.mechanism.location,
      workerModel: row.mechanism.model,
      activeRunId: row.live ? row.runId : undefined,
      attentionStatus: row.failureClass ? (row.status === 'stalled' ? 'stalled' : 'failed') : undefined,
    };
  }
  return {
    mode: 'rail',
    worktreeMode: 'compact',
    isWorkerRun: row.mechanism.isWorkerRun,
    where: 'local',
    branches: row.branch ? [{ branch: row.branch, hasWorktree: true }] : [],
  };
}

const KIND_COLOR: Record<string, string> = {
  feature: 'bg-primary/15 text-primary',
  prd: 'bg-primary/15 text-primary',
  fix: 'bg-amber-500/15 text-amber-500',
  spike: 'bg-blue-500/15 text-blue-500',
  task: 'bg-muted text-muted-foreground',
};

function KindPill({ workRef }: { workRef?: WorkRef }) {
  const label = workKindLabel(workRef);
  if (!label) return null;
  return (
    <span className={cn('flex-shrink-0 rounded-md px-1.5 py-0.5 text-[10px] font-medium uppercase', KIND_COLOR[label])}>
      {label}
    </span>
  );
}

function workKindLabel(workRef?: WorkRef): string | null {
  if (!workRef) return null;
  if (workRef.kind === 'prd') return workRef.feature ? 'feature' : 'prd';
  return workRef.kind;
}

function rowTitle(row: InFlightRow): string {
  return row.title ?? row.branch ?? row.workRef?.id ?? 'Untitled';
}

/** A stable identity for a row across renders — for selection + deep-linking. */
export function inFlightRowKey(row: InFlightRow): string {
  if (row.runId) return `run:${row.runId}`;
  if (row.branch) return `branch:${row.branch}`;
  if (row.workRef) {
    const feature = row.workRef.kind === 'prd' && row.workRef.feature ? `/${row.workRef.feature}` : '';
    return `${row.mechanism.kind}:${row.workRef.kind}:${row.workRef.id}${feature}`;
  }
  return row.mechanism.kind;
}
