import React, { useEffect, useState } from 'react';
import { ExternalLink, FileCode2, FileText, Image as ImageIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Island } from './Island';
import {
  assetFileUrl,
  fetchAssets,
  type AssetFile,
  type AssetFileKind,
  type AssetItemKind,
  type AssetListingResult,
} from '../services/api';

export interface AssetsIslandProps {
  repoId: string;
  kind: AssetItemKind;
  slug: string;
  /** Dismiss the view — returns to the fix/PRD detail it was opened from. */
  onClose?: () => void;
}

/** Per-file-kind glyph + tint + rail label, keyed by the resolver's kind. */
const KIND_GLYPH: Record<AssetFileKind, { Icon: typeof FileCode2; tint: string; label: string }> = {
  html: { Icon: FileCode2, tint: 'text-primary bg-primary/10', label: 'html' },
  image: { Icon: ImageIcon, tint: 'text-blue bg-blue/10', label: 'image' },
  other: { Icon: FileText, tint: 'text-subtle bg-foreground/5', label: 'file' },
};

type LoadState =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ok'; listing: AssetListingResult };

function fileCountLabel(n: number): string {
  return `${n} ${n === 1 ? 'file' : 'files'}`;
}

/** Stable legend / present-kind order. */
const KIND_ORDER: AssetFileKind[] = ['html', 'image', 'other'];

/** Drop the trailing extension for display (the full name stays the a11y name). */
function baseName(name: string): string {
  return name.replace(/\.[^./]+$/, '');
}

/**
 * In-place design-assets view (surface-design-assets-in-dashboard F4). Rides the
 * shared {@link Island} overlay shell — so it dismisses on backdrop click and
 * Escape exactly like the other islands — and renders the header (kind eyebrow +
 * "Assets · N files") and a two-pane body: a file rail and the preview pane.
 * Task 1 renders the rail (listing) with honest loading / empty / error states;
 * Task 2 fills the preview pane.
 */
export const AssetsIsland: React.FC<AssetsIslandProps> = ({ repoId, kind, slug, onClose }) => {
  const [state, setState] = useState<LoadState>({ status: 'loading' });
  const [selected, setSelected] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setState({ status: 'loading' });
    fetchAssets(repoId, kind, slug)
      .then((listing) => {
        if (cancelled) return;
        setState({ status: 'ok', listing });
        setSelected(listing.assets[0]?.name ?? null);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setState({ status: 'error', message: err instanceof Error ? err.message : String(err) });
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, kind, slug]);

  const kindLabel = kind === 'prd' ? 'PRD' : 'Fix';
  const selectedFile = state.status === 'ok' ? state.listing.assets.find((f) => f.name === selected) : undefined;
  const selectedUrl = selectedFile ? assetFileUrl(repoId, kind, slug, selectedFile.name) : undefined;
  const presentKinds =
    state.status === 'ok' ? KIND_ORDER.filter((k) => state.listing.assets.some((f) => f.kind === k)) : [];

  return (
    <Island open onClose={onClose ?? (() => {})} ariaLabel="Design assets" size="wide">
      {/* Equal horizontal / vertical padding (p-6); no width cap so the preview
          gets the full island width. Flex column so the preview fills the
          remaining height rather than being capped. */}
      <div className="flex flex-1 min-h-0 flex-col p-6">
        <header className="mb-5 shrink-0">
          {/* Eyebrow row with the open-in-browser affordance RHS (mirrors the
              other islands' DetailHeader), then the title at mt-3.5. */}
          <div className="flex min-h-7 items-center justify-between gap-3">
            <p className="eyebrow text-[10px] text-primary">{kindLabel} · assets</p>
            {selectedFile && selectedUrl && (
              <a
                href={selectedUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1.5 text-xs text-blue transition-colors hover:underline"
              >
                <ExternalLink className="h-3.5 w-3.5" /> open in browser
              </a>
            )}
          </div>
          <div className="mt-3.5 flex items-center justify-between gap-3">
            <div className="flex min-w-0 items-baseline gap-2">
              <h1 className="display whitespace-nowrap text-2xl font-bold leading-tight">
                Assets
                {state.status === 'ok' && (
                  <span className="font-normal text-muted-foreground"> · {fileCountLabel(state.listing.assets.length)}</span>
                )}
              </h1>
              <span className="mono truncate text-sm text-muted-foreground">· {slug}</span>
            </div>
            {presentKinds.length > 0 && <KindLegend kinds={presentKinds} />}
          </div>
        </header>

        {state.status === 'loading' && (
          <p role="status" className="text-sm text-muted-foreground">
            Loading assets…
          </p>
        )}

        {state.status === 'error' && (
          <p role="alert" className="text-sm text-red-400">
            Couldn&rsquo;t load assets — {state.message}
          </p>
        )}

        {state.status === 'ok' &&
          (state.listing.assets.length === 0 ? (
            <div className="grid place-items-center rounded-2xl border border-dashed border-border-strong py-16 text-center">
              <p className="text-sm text-muted-foreground">No design assets for this {kindLabel} yet.</p>
            </div>
          ) : (
            <div className="flex min-h-0 flex-1 flex-col gap-3">
              {/* Files as a horizontal top bar — leaves the full width for the
                  preview. The extension is dropped from each chip (the header
                  legend + glyph colour convey the kind). */}
              <div role="listbox" aria-label="Asset files" className="flex shrink-0 flex-wrap gap-2">
                {state.listing.assets.map((file) => (
                  <FileChip
                    key={file.name}
                    file={file}
                    selected={file.name === selected}
                    onSelect={() => setSelected(file.name)}
                  />
                ))}
              </div>
              <div className="min-h-0 flex-1 overflow-hidden">
                {selectedFile && selectedUrl ? (
                  <Preview file={selectedFile} url={selectedUrl} />
                ) : (
                  <div className="grid h-full place-items-center p-6 text-center">
                    <p className="text-sm text-muted-foreground">Select a file to preview.</p>
                  </div>
                )}
              </div>
            </div>
          ))}
      </div>
    </Island>
  );
};

/** Kind legend above the file bar — maps each glyph colour to its kind. */
const KindLegend: React.FC<{ kinds: AssetFileKind[] }> = ({ kinds }) => (
  <div className="flex shrink-0 flex-wrap items-center gap-3 text-[11px] uppercase tracking-wider text-subtle">
    {kinds.map((k) => {
      const { Icon, tint, label } = KIND_GLYPH[k];
      return (
        <span key={k} className="flex items-center gap-1.5">
          {/* Glyph tile matches the file chips' (h-6/w-6, h-3.5 icon). */}
          <span className={cn('grid h-6 w-6 place-items-center rounded', tint)}>
            <Icon className="h-3.5 w-3.5" />
          </span>
          {label}
        </span>
      );
    })}
  </div>
);

const FileChip: React.FC<{ file: AssetFile; selected: boolean; onSelect: () => void }> = ({
  file,
  selected,
  onSelect,
}) => {
  const { Icon, tint } = KIND_GLYPH[file.kind];
  return (
    <button
      type="button"
      role="option"
      aria-selected={selected}
      // Full name (with extension) as the accessible name; the visible chip
      // drops the extension since the legend + glyph convey the kind.
      aria-label={file.name}
      onClick={onSelect}
      className={cn(
        'flex items-center gap-2 rounded-lg border px-2.5 py-1.5 transition-colors',
        selected
          ? 'border-blue/40 bg-blue/10 text-foreground'
          : 'border-border text-subtle hover:bg-foreground/5 hover:text-foreground',
      )}
    >
      <span className={cn('grid h-6 w-6 flex-none place-items-center rounded', tint)}>
        <Icon className="h-3.5 w-3.5" />
      </span>
      <span className="mono whitespace-nowrap text-[12px]">{baseName(file.name)}</span>
    </button>
  );
};

/**
 * The preview pane for the selected asset. HTML renders in a sandboxed iframe;
 * images render inline; anything else has no inline preview and is opened via
 * the header link.
 *
 * Sandbox: `allow-scripts` lets the mockup's own scripts run (theme toggles,
 * icon rendering) so the preview is faithful — but WITHOUT `allow-same-origin`,
 * so the frame is a unique opaque origin that cannot reach the dashboard's
 * DOM/cookies/storage or navigate the top frame. The server also sends
 * `Content-Security-Policy: sandbox allow-scripts` + nosniff on the same bytes
 * (F1 T3), so the isolation holds on a direct navigation too — defence in depth.
 */
const Preview: React.FC<{ file: AssetFile; url: string }> = ({ file, url }) => {
  if (file.kind === 'html') {
    return (
      <iframe
        title={file.name}
        src={url}
        sandbox="allow-scripts"
        className="block h-full min-h-[460px] w-full rounded-lg border border-border bg-white"
      />
    );
  }
  if (file.kind === 'image') {
    return <ImagePreview url={url} name={file.name} />;
  }
  return (
    <div className="grid h-full min-h-[300px] place-items-center rounded-lg border border-dashed border-border-strong p-6 text-center">
      <div className="flex max-w-sm flex-col items-center gap-3">
        <FileText className="h-7 w-7 text-subtle" />
        <p className="text-sm text-muted-foreground">
          <span className="mono text-foreground">{file.name}</span> has no inline preview — open it in browser.
        </p>
      </div>
    </div>
  );
};

/** Inline image preview with a graceful fallback when the endpoint fails. */
const ImagePreview: React.FC<{ url: string; name: string }> = ({ url, name }) => {
  const [failed, setFailed] = useState(false);
  return (
    <div className="grid h-full min-h-[300px] place-items-center rounded-lg border border-border bg-foreground/[0.04] p-6 text-center">
      {failed ? (
        <div className="flex max-w-sm flex-col items-center gap-3">
          <ImageIcon className="h-7 w-7 text-subtle" />
          <p className="text-sm text-muted-foreground">
            <span className="mono text-foreground">{name}</span> couldn&rsquo;t be loaded.
          </p>
        </div>
      ) : (
        <img
          src={url}
          alt={name}
          onError={() => setFailed(true)}
          className="max-h-[420px] max-w-full rounded-md"
        />
      )}
    </div>
  );
};

export default AssetsIsland;
