import { Check, CheckCheck, Loader2, AlertCircle } from 'lucide-react';
import { extractTests } from '../utils/extract-tests';
import { useCommitDiff } from '../hooks/useCommitDiff';
import DiffFileView from './DiffFileView';
import { PhaseEmptyState } from './PhaseEmptyState';

interface GreenTabProps {
  repoId: string;
  /** The task's GREEN (feat:/fix:) commit SHA — the implementation. */
  commitSha?: string;
  /** The task's RED (test:) commit SHA — the source of the passing-test list. */
  testCommitSha?: string;
  /** Whether the green phase is live (red landed, implementation underway) —
   *  drives the empty state to read "in progress" rather than "not started". */
  inProgress?: boolean;
}

const isTestPath = (p: string) => /\.(test|spec)\./.test(p);
const basename = (p: string) => p.split('/').pop() ?? p;
const shortSha = (sha?: string) =>
  sha && sha !== 'skipped' ? sha.slice(0, 7) : null;

/**
 * The Green tab — the implementation that turned the spec green. The same tests
 * the Red tab listed as failing, now shown passing (derived from the RED
 * commit's test source; per-test runtime output is never recorded, so no
 * timing), beside the GREEN commit's implementation diff. Pairs two commit
 * diffs: the red one for the test list, the green one for the implementation.
 */
export default function GreenTab({ repoId, commitSha, testCommitSha, inProgress }: GreenTabProps) {
  const hasGreen = !!commitSha && commitSha !== 'skipped';
  // No green commit ⇒ the tab is the empty state, so fetch neither diff. The
  // red diff (for the passing-test list) is only meaningful alongside a green.
  const impl = useCommitDiff(repoId, hasGreen ? commitSha : undefined);
  const red = useCommitDiff(repoId, hasGreen ? testCommitSha : undefined);

  if (!hasGreen) {
    return (
      <PhaseEmptyState
        inProgress={!!inProgress}
        message={
          inProgress
            ? 'Implementing — turning the spec green…'
            : 'No green commit yet — no implementation has landed for this task.'
        }
      />
    );
  }

  // Passing tests come from the RED commit's test source.
  const redTestFiles = red.files.filter((f) => isTestPath(f.newPath ?? f.oldPath ?? ''));
  const tests = extractTests(redTestFiles.length > 0 ? redTestFiles : red.files);

  // The implementation diff: prefer non-test files (the test was added in RED);
  // fall back to the whole green diff if it touched only test files.
  const implFiles = impl.files.filter((f) => !isTestPath(f.newPath ?? f.oldPath ?? ''));
  const displayFiles = implFiles.length > 0 ? implFiles : impl.files;

  const redShort = shortSha(testCommitSha);
  const greenShort = shortSha(commitSha);

  return (
    <div className="grid h-full min-h-0 grid-cols-1 lg:grid-cols-[320px_minmax(0,1fr)]">
      {/* Passing-tests rail */}
      <aside className="flex min-h-0 flex-col border-r border-border">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="eyebrow text-[10px]" style={{ color: 'var(--color-phase-green)' }}>
            Tests now passing
          </p>
          <span className="mono text-[11px] text-muted-foreground">{tests.length}</span>
        </div>
        <p data-testid="green-provenance" className="px-4 pt-2 text-[13px] leading-snug text-muted-foreground">
          {redShort ? (
            <>
              Written failing in <span className="mono text-foreground">{redShort}</span>, green since{' '}
              <span className="mono text-foreground">{greenShort}</span>.
            </>
          ) : (
            <>
              Green since <span className="mono text-foreground">{greenShort}</span>.
            </>
          )}
        </p>

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto pb-3">
          {red.loading && (
            <div className="flex items-center gap-2 px-4 py-3 text-[13px] text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading tests…
            </div>
          )}
          {red.error && !red.loading && (
            <div className="flex items-start gap-2 px-4 py-3 text-[13px] text-red-500">
              <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {red.error}
            </div>
          )}
          {!red.loading &&
            !red.error &&
            tests.map((test, i) => (
            <div key={`${test.name}-${i}`} className="flex gap-3 px-4 py-3">
              <span
                className="grid h-5 w-5 flex-none place-items-center rounded-full border"
                style={{
                  color: 'var(--color-phase-green)',
                  background: 'color-mix(in oklab, var(--color-phase-green) 16%, transparent)',
                  borderColor: 'color-mix(in oklab, var(--color-phase-green) 45%, transparent)',
                }}
              >
                <Check className="h-3.5 w-3.5" />
              </span>
              <div className="min-w-0">
                <p className="text-[13px] leading-snug">{test.name}</p>
                <p className="mono mt-1 text-[10px] text-muted-foreground">
                  {basename(test.path)}:{test.line}
                </p>
              </div>
            </div>
          ))}

          {!red.loading && !red.error && tests.length > 0 && (
            <div className="mx-4 mt-4 rounded-xl border border-border bg-muted/30 p-3">
              <p className="eyebrow text-[9px] text-muted-foreground">Suite</p>
              <p
                data-testid="green-suite-summary"
                className="mono mt-1 inline-flex items-center gap-1.5 text-[12px]"
                style={{ color: 'var(--color-phase-green)' }}
              >
                <CheckCheck className="h-3.5 w-3.5" /> {tests.length} passed · 0 failed
              </p>
            </div>
          )}
        </div>
      </aside>

      {/* Green implementation diff */}
      <section className="tb-diff min-h-0 overflow-y-auto">
        {impl.loading && (
          <div className="flex items-center gap-2 p-4 text-sm text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" /> Loading diff…
          </div>
        )}
        {impl.error && (
          <div className="flex items-start gap-2 p-4 text-sm text-red-500">
            <AlertCircle className="mt-0.5 h-4 w-4 flex-none" /> {impl.error}
          </div>
        )}
        {!impl.loading &&
          !impl.error &&
          displayFiles.map((file, fileIndex) => (
            <DiffFileView key={`${file.newPath ?? file.oldPath ?? ''}-${fileIndex}`} file={file} />
          ))}
      </section>
    </div>
  );
}
