interface RepoInfo {
  id: string
  name: string
  path: string
  contextFile?: string
  lastAnalyzed?: string
}

// Settings is an inline view (see below), not a workspace tab — so 'setup' is
// no longer a TabType. A legacy stored 'setup' is coerced to 'plans' at init.
type TabType = 'plans' | 'fixes' | 'spikes' | 'in-flight' | 'quality' | 'agents' | 'skills' | 'plugins' | 'hooks'

const TAB_TYPES: readonly TabType[] = [
  'plans', 'fixes', 'spikes', 'in-flight', 'quality', 'agents', 'skills', 'plugins', 'hooks',
]

// Coerce an untrusted tab value (from the `?view=` URL param or stored
// preference) to a known TabType. A legacy 'setup' maps to 'plans'; anything
// unrecognised returns null so the caller can fall back rather than promoting a
// bogus deep-link value to a TabType that renders a blank workspace.
const coerceTab = (value: string | null | undefined): TabType | null => {
  if (!value) return null
  if (value === 'setup') return 'plans'
  return (TAB_TYPES as readonly string[]).includes(value) ? (value as TabType) : null
}

// The three work areas the stage rail surfaces as sibling tabs.
const WORK_AREAS: readonly WorkArea[] = ['plans', 'fixes', 'spikes']
const asWorkArea = (tab: TabType): WorkArea | null =>
  (WORK_AREAS as readonly string[]).includes(tab) ? (tab as WorkArea) : null

// Helper to get/set localStorage with prefix
const getStorageKey = (repoId: string, key: string) => `tiny-brain:repo:${repoId}:${key}`

const getStoredValue = <T,>(repoId: string, key: string, defaultValue: T): T => {
  try {
    const stored = localStorage.getItem(getStorageKey(repoId, key))
    return stored ? JSON.parse(stored) : defaultValue
  } catch {
    return defaultValue
  }
}

const setStoredValue = <T,>(repoId: string, key: string, value: T): void => {
  try {
    localStorage.setItem(getStorageKey(repoId, key), JSON.stringify(value))
  } catch {
    // Ignore storage errors
  }
}

export default function RepoDetailPage() {
  const { repoId } = useParams<{ repoId: string }>()
  const [searchParams, setSearchParams] = useSearchParams()
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId ?? '')
  const { setRepo: setCurrentRepo } = useCurrentRepo()
  // repoId is always present on the /repos/:repoId route; `?? ''` mirrors the
  // file's existing fallback convention (see usePipelineConfig above).
  const workspacePanels = usePanelSizeMemory(`repo-workspace:${repoId ?? ''}`)

  // A ?section= deep-link (from a repo-card badge) opens the Setup tab at
  // that section, overriding the stored tab preference.
  const deepLinkSection = searchParams.get('section') ?? undefined

  // The full task detail view is an in-place view of this same route — opening
  // a task sets `?task=<id>&tab=<phase>` rather than navigating away, so the
  // workspace stays mounted and its plans/fixes/spikes data stays warm (no
  // refetch on open/close). When `?task` is absent the normal workspace renders.
  const selectedTaskId = searchParams.get('task')
  // The worktree-merge island is a content-replacing view keyed by branch (like
  // ?task=), so its transparent backdrop shows the single app wash.
  const islandBranch = searchParams.get('island')
  // A `prd:<id>` island is the PRD teardown surface (worktree-teardown-surface) —
  // a distinct content-replacing view keyed by PRD id, not a single branch.
  const teardownPrdId = islandBranch?.startsWith('prd:') ? islandBranch.slice('prd:'.length) : null
  // The WorkerRun island (F12) is a content-replacing view keyed by runId, like
  // ?task= / ?island=. Opened from a feature rail's Running pill; round-trips on
  // a bookmark and survives navigation because the island reads the run record.
  const selectedRunId = searchParams.get('run')
  const openRun = (runId: string) =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.set('run', runId)
      return next
    })
  const closeRun = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.delete('run')
      return next
    })
  // The design-assets view (surface-design-assets F4) is a MODE of the open
  // fix/PRD, so `?assets` is a bare marker: the item is already identified by
  // `?view=<area>&item=<slug>`, and the kind is derived from the active area.
  // Both still live in the URL, so the view round-trips on a bookmark.
  const assetsOpen = searchParams.has('assets')
  // The raw `?tab=` value — TaskDetailPage resolves it against the task's pinned
  // gate-set (the gate-set isn't known here).
  const selectedTaskRawTab = searchParams.get('tab')
  const openTaskTab = (tab: TaskTab) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('tab', tab)
        return next
      },
      { replace: true },
    )
  }
  const closeTask = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.delete('task')
      next.delete('tab')
      return next
    })
  }

  // Repo Settings is an inline view that renders in the workspace content area
  // with the stage rail still visible — opened via the top-rail Settings control
  // (RepoViewControls) or a `?section=` badge deep-link, both of which set/imply
  // `?settings`. The rest of the workspace stays mounted; selecting a work area /
  // Quality clears the params and restores it with no refetch.
  const settingsOpen = searchParams.get('settings') !== null || deepLinkSection !== undefined
  const settingsSection = searchParams.get('settings') || deepLinkSection || undefined
  // Selecting a Settings section writes it to `?settings=<id>` so the section is
  // deep-linkable, survives reload, and shows in the breadcrumb. Drop the legacy
  // `?section=` alias so the two can't disagree. Replace — switching sections is
  // not a distinct history entry.
  const setSettingsSection = (id: string) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('settings', id)
        next.delete('section')
        return next
      },
      { replace: true },
    )
  }

  // The active work area / Quality is URL-driven via `?view=<area>` so it is
  // deep-linkable and survives reload. localStorage is only a fallback for the
  // initial area when the URL carries no `?view=` (remembers the last tab across
  // visits). Settings is no longer a workspace tab (it's the inline Settings
  // view, opened via `?settings`), so the workspace defaults to Plans. A legacy
  // stored / linked 'setup' coerces to 'plans'.
  const viewParam = searchParams.get('view')
  const storedTab = repoId ? getStoredValue<string>(repoId, 'activeTab', 'plans') : 'plans'
  // URL wins over the stored preference; an unrecognised value in either falls
  // through to 'plans' so a malformed deep link can never blank the workspace.
  const activeTab: TabType = coerceTab(viewParam) ?? coerceTab(storedTab) ?? 'plans'

  // Normalise a bare workspace URL so the resolved active tab is always present
  // in `?view=`. The breadcrumb lives in the global header and reads the area
  // from the URL alone, so a load with no `?view=` (and no settings/task view)
  // must write the resolved tab back — otherwise the header can't show the
  // area crumb. This intentionally covers every known tab (e.g. a stored
  // `quality` restores `?view=quality`), not just the work areas. Replace, so
  // it adds no history entry.
  useEffect(() => {
    if (selectedTaskId) return
    if (searchParams.get('settings') !== null || searchParams.get('section') !== null) return
    if (searchParams.get('view')) return
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        next.set('view', activeTab)
        return next
      },
      { replace: true },
    )
  }, [selectedTaskId, searchParams, activeTab, setSearchParams])
  // The selected Plan / Fix / Spike is URL-driven via `?item=<slug>` so a
  // specific item is deep-linkable and rendered as a breadcrumb drill-down
  // crumb. One param serves all three work areas because only one area is active
  // at a time; the value is scoped to the active area below. Switching area
  // clears it (see setActiveTab) so a stale slug can't leak across areas.
  const selectedItemId = searchParams.get('item')
  const setSelectedItemId = (id: string | null) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev)
        if (id) next.set('item', id)
        else next.delete('item')
        return next
      },
      { replace: true },
    )
  }
  const selectedPlanId = activeTab === 'plans' ? selectedItemId : null
  const selectedFixId = activeTab === 'fixes' ? selectedItemId : null
  const setSelectedPlanId = setSelectedItemId
  const setSelectedFixId = setSelectedItemId
  const [selectedAgentId, setSelectedAgentIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedAgentId', null) : null
  )
  const [selectedSkillId, setSelectedSkillIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedSkillId', null) : null
  )
  const [selectedPluginId, setSelectedPluginIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedPluginId', null) : null
  )
  const [selectedQualityRunId, setSelectedQualityRunIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedQualityRunId', null) : null
  )

  // Wrapped setters that persist to localStorage
  // Selecting a work area / Quality writes `?view=<area>` (and closes any open
  // Settings view) in a single URL update, so the area round-trips through the
  // URL. The stored value keeps the "remember my last tab" behaviour for the
  // next visit that arrives without a `?view=`.
  const setActiveTab = (tab: TabType) => {
    if (repoId) setStoredValue(repoId, 'activeTab', tab)
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev)
      next.set('view', tab)
      next.delete('settings')
      next.delete('section')
      // Drop the previous area's drill-downs so a stale item/analyser can't leak
      // into the newly selected area.
      next.delete('item')
      next.delete('analyser')
      return next
    })
  }
  const setSelectedAgentId = (id: string | null) => {
    setSelectedAgentIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedAgentId', id)
  }
  const setSelectedSkillId = (id: string | null) => {
    setSelectedSkillIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedSkillId', id)
  }
  const setSelectedPluginId = (id: string | null) => {
    setSelectedPluginIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedPluginId', id)
  }
  const setSelectedQualityRunId = (id: string | null) => {
    setSelectedQualityRunIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedQualityRunId', id)
  }
  const [viewMode] = useState<'summary' | 'details' | 'json'>('details')
  const [repoPlans, setRepoPlans] = useState<Plan[]>([])
  const [repoFixes, setRepoFixes] = useState<Fix[]>([])
  const [repoSpikes, setRepoSpikes] = useState<SpikeSummary[]>([])
  // Spikes share the same URL-driven selection as plans/fixes (scoped to the
  // spikes area). Unlike plans/fixes there is no auto-select, so it stays unset
  // until the user picks a spike.
  const selectedSpikeId = activeTab === 'spikes' ? selectedItemId : null
  const setSelectedSpikeId = setSelectedItemId
  const [selectedSpike, setSelectedSpike] = useState<SpikeProgress | null>(null)
  const [repoWorktrees, setRepoWorktrees] = useState<Worktree[]>([])
  const [deliveryWorktrees, setDeliveryWorktrees] = useState<DeliveryWorktreeRow[]>([])
  // Whether the delivery queue has resolved at least once — distinguishes "still
  // loading" (a ?island= deep-link/reload before the fetch lands) from "no such
  // branch", so the island view shows the right state instead of silently
  // falling through to the workspace.
  const [deliveryLoaded, setDeliveryLoaded] = useState(false)
  // The PRD teardown model for the active ?island=prd:<id> view — fetched on
  // demand, keyed by the target PRD id (worktree-teardown-surface task 8).
  const [prdTeardown, setPrdTeardown] = useState<PrdTeardownModel | null>(null)
  const [prdTeardownLoaded, setPrdTeardownLoaded] = useState(false)
  // Default true because the page fetches spikes immediately on mount (see the
  // repoId-keyed effect below); the spikes list shows a spinner until then.
  const [spikesLoading, setSpikesLoading] = useState(true)
  const [spikeDetailLoading, setSpikeDetailLoading] = useState(false)
  const [repoAgents, setRepoAgents] = useState<Agent[]>([])
  const [repoSkills, setRepoSkills] = useState<Skill[]>([])
  const [repoPlugins, setRepoPlugins] = useState<RepoPlugin[]>([])
  const [repoHooks, setRepoHooks] = useState<AllHooks>({ pluginHooks: [], repoHooks: [], gitHooks: [] })
  const [repoQualityRuns, setRepoQualityRuns] = useState<QualityRunSummary[]>([])
  const [, setLatestQualityGrade] = useState<string | null>(null)
  const [, setLatestQualityScore] = useState<number | null>(null)
  const [, setQualityCriteria] = useState<{ passing: number; total: number } | null>(null)
  const [selectedQualityRun, setSelectedQualityRun] = useState<QualityRunDetail | null>(null)
  const [repoInfo, setRepoInfo] = useState<RepoInfo | null>(null)
  const [loading, setLoading] = useState(true)
  const [fixesLoading, setFixesLoading] = useState(false)
  const [agentsLoading, setAgentsLoading] = useState(false)

  // Per-area list filters: multi-select status pills, defaulting to active
  // work (Not started + In progress); completed and archived are opt-in.
  const [planFilter, setPlanFilter] = useState<Set<ListStatus>>(() => new Set(DEFAULT_LIST_STATUSES))
  const [fixFilter, setFixFilter] = useState<Set<ListStatus>>(() => new Set(DEFAULT_LIST_STATUSES))
  const [spikeFilter, setSpikeFilter] = useState<Set<ListStatus>>(() => new Set(SPIKE_DEFAULT_LIST_STATUSES))
  // Shared list search query (over the sidebar), reset when the tab changes.
  const [listSearch, setListSearch] = useState('')
  // Whether the status-filter pills are revealed (toggled by the filter button).
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [skillsLoading, setSkillsLoading] = useState(false)
  const [pluginsLoading, setPluginsLoading] = useState(false)
  const [hooksLoading, setHooksLoading] = useState(false)
  const [, setQualityLoading] = useState(false)
  const [selectedHook, setSelectedHook] = useState<Hook | null>(null)
  const [, setSetupComplete] = useState(false)

  // The full item sets (the list filter, below, decides per-row visibility;
  // selection lookups and effects index off the full set).
  // One repo-wide live telemetry feed (initial fetch + telemetryChange SSE),
  // still consumed by the spike detail surface.
  const { events: telemetry } = useRepoTelemetry(repoId ?? null)
  // Every run across all states — the Runs lens (activeTab === 'runs') and its
  // two-part rail count. Failed runs surface as a flash on the rail Runs control
  // + inline Resume on the lens rows (which retired the push attention banner);
  // `refresh` is re-run after a resume/cancel so the list reflects the change.
  const repoRuns = useRepoRuns(repoId ?? null)
  // The one operations board (in-flight-ops F16): live worker runs + delivery
  // worktrees, folded into four lanes server-side. Feeds both the rail's
  // three-part count and the In-flight view (activeTab === 'in-flight').
  const inFlight = useInFlight(repoId ?? null)
  const inFlightRailCount = {
    running: inFlight.lanes.inProgress.length,
    toLand: inFlight.lanes.readyToLand.length,
    failed: inFlight.lanes.failed.length,
  }
  // Render the selected in-flight row's detail in the board's main pane: a
  // worker/failed run opens the WorkerRun island; a delivery worktree opens the
  // Land-this-work detail (land or cleanup by its own state).
  const renderInFlightDetail = (row: InFlightRow) => {
    if (!repoId) return null
    if (row.mechanism.kind === 'worker' && row.runId) {
      return (
        <WorkerRunIsland
          repoId={repoId}
          runId={row.runId}
          onClose={() => { setSelectedItemId(null); inFlight.refresh() }}
        />
      )
    }
    if (row.mechanism.kind === 'worktree' && row.branch) {
      const worktree = deliveryWorktrees.find((w) => w.branch === row.branch)
      return worktree ? (
        <WorktreeMergeDetail
          repoId={repoId}
          worktree={worktree}
          onActionComplete={() => { fetchRepoDeliveryQueue(); inFlight.refresh() }}
        />
      ) : (
        <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
          Worktree detail unavailable.
        </div>
      )
    }
    // A run-less worker or branch-less worktree can't route to a detail surface.
    return (
      <div className="flex h-full items-center justify-center px-6 text-center text-sm text-muted-foreground">
        No detail available for this deliverable yet.
      </div>
    )
  }
  // Render the server projection directly (live-frontier-projection F4-T1). The
  // composer already merged git + the event overlay (redStartedAt / greenStartedAt
  // / reviews) into each task's flat fields, and a pre-commit phase pulse rides the
  // per-entity `status-change` SSE that patches the affected fix/plan by id (F3-T1)
  // — so the client no longer re-folds the telemetry feed into a parallel
  // `derivedState`. `toEffectiveTask` reads the server-projected fields directly.
  const fixes = repoFixes
  const plans = repoPlans

  // Map each item onto a single ListStatus pill category (shared helpers in
  // list-category): archived wins; the fix category sources from the
  // worktree-effective rollup; and a done-but-unlanded fix/PRD stays in active
  // work (in_progress) so it doesn't vanish from the default view before it
  // lands (worktree-surface-consistency-pass task 4).
  const spikeCategory = (spike: SpikeSummary): ListStatus => {
    const s = spike.status as string
    if (s === 'validated' || s === 'invalidated' || s === 'abandoned') return 'completed'
    if (s === 'in_progress') return 'in_progress'
    return 'not_started'
  }

  // Per-status counts for the list filter pills (drives the pill numbers).
  const countByStatus = <T,>(items: readonly T[], category: (item: T) => ListStatus) =>
    items.reduce<Partial<Record<ListStatus, number>>>((acc, item) => {
      const key = category(item)
      acc[key] = (acc[key] ?? 0) + 1
      return acc
    }, {})

  // Aggregate work-area counts for the stage rail (total = ACTIVE work only:
  // not_started + in_progress; completed/superseded and archived are excluded,
  // so the total reads the same across plans, fixes and spikes).
  const workAreaCounts = {
    plans: workAreaCount(plans, planCategory),
    fixes: workAreaCount(fixes, fixCategory),
    spikes: workAreaCount(repoSpikes, spikeCategory),
  }


  const filteredPlans = plans
    .filter(plan => planFilter.has(planCategory(plan)))
    .filter(plan => matchesSearch(listSearch, plan.title, plan.name, plan.prdId))
  const filteredFixes = fixes
    .filter(fix => fixFilter.has(fixCategory(fix)))
    .filter(fix => matchesSearch(listSearch, fix.title, fix.id))
  const filteredSpikes = repoSpikes
    .filter(spike => spikeFilter.has(spikeCategory(spike)))
    .filter(spike => matchesSearch(listSearch, spike.title, spike.id))

  // Toggle a status pill in one of the per-area filters.
  const makeStatusToggle = (
    setter: (updater: (prev: Set<ListStatus>) => Set<ListStatus>) => void,
  ) => (status: ListStatus) =>
    setter(prev => {
      const next = new Set(prev)
      if (next.has(status)) next.delete(status)
      else next.add(status)
      return next
    })

  // The status filter for the active work area (null on non-list views). Each
  // branch pairs items with their own category fn so the counts stay typed, and
  // its pill set: plans/fixes get the full ALL_LIST_STATUSES (stated explicitly
  // for symmetry with spikes, though it is the component default); spikes drop
  // ready_to_land since they have no landed concept.
  const activeListFilter =
    activeTab === 'plans'
      ? { active: planFilter, onToggle: makeStatusToggle(setPlanFilter), counts: countByStatus(plans, planCategory), statuses: ALL_LIST_STATUSES }
      : activeTab === 'fixes'
        ? { active: fixFilter, onToggle: makeStatusToggle(setFixFilter), counts: countByStatus(fixes, fixCategory), statuses: ALL_LIST_STATUSES }
        : activeTab === 'spikes'
          ? { active: spikeFilter, onToggle: makeStatusToggle(setSpikeFilter), counts: countByStatus(repoSpikes, spikeCategory), statuses: SPIKE_LIST_STATUSES }
          : null

  // `plans` is the server projection (F4-T1); the selected plan is that entity
  // directly — live status changes arrive as a per-entity `status-change` patch.
  const selectedPlan = (selectedPlanId ? plans.find((p: Plan) => p.id === selectedPlanId) : null) ?? null

  // Fetch repo info
  const fetchRepoInfo = async () => {
    try {
      console.log('[RepoDetailPage] Fetching repo info for:', repoId);
      const response = await fetch(`/api/repos/${repoId}`)
      console.log('[RepoDetailPage] Repo info response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received repo info:', data);
        setRepoInfo(data.repo || null)
        setCurrentRepo(data.repo || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo info:', error)
    }
  }


  // Fetch plans for this repo
  const fetchRepoPlans = async () => {
    try {
      console.log('[RepoDetailPage] Fetching plans for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/plans`)
      console.log('[RepoDetailPage] Response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received data:', data);
        console.log('[RepoDetailPage] Plans count:', data.plans?.length);
        setRepoPlans(data.plans || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plans:', error)
    } finally {
      setLoading(false)
    }
  }

  // Fetch fixes for this repo
  const fetchRepoFixes = async () => {
    try {
      setFixesLoading(true)
      console.log('[RepoDetailPage] Fetching fixes for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/fixes`)
      console.log('[RepoDetailPage] Fixes response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received fixes:', data);
        console.log('[RepoDetailPage] Fixes count:', data.fixes?.length);
        setRepoFixes(data.fixes || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo fixes:', error)
    } finally {
      setFixesLoading(false)
    }
  }

  // Fetch spikes for this repo
  const fetchRepoSpikes = async () => {
    if (!repoId) return
    try {
      setSpikesLoading(true)
      const response = await fetch(`/api/repos/${repoId}/spikes`)
      if (!response.ok) {
        // Distinguish a real failure from "no spikes yet" — both
        // resolve to an empty list in the UI, but a server-side 500
        // is something we want surfaced in the console for triage.
        console.error(
          '[RepoDetailPage] Spikes fetch failed:',
          response.status,
          await response.text().catch(() => '(no body)'),
        )
        return
      }
      const data = await response.json()
      setRepoSpikes(data.spikes ?? [])
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo spikes:', error)
    } finally {
      setSpikesLoading(false)
    }
  }

  // Fetch worktrees so SpikeDetail can derive present/orphaned status
  // for its launch snippet / orphan banner. Bounded by repo size, cheap.
  const fetchRepoWorktrees = async () => {
    if (!repoId) return
    try {
      const response = await fetch(`/api/repos/${repoId}/worktrees`)
      if (response.ok) {
        const data = await response.json()
        setRepoWorktrees(data.worktrees ?? [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo worktrees:', error)
    }
  }

  // The cross-kind Done queue — fixes + PRDs needing a git move. Feeds both the
  // rail's `to merge` count and the Worktrees Done tab. Assembled server-side;
  // the page just holds + forwards it (the dumb-UI rule).
  const fetchRepoDeliveryQueue = async () => {
    if (!repoId) return
    try {
      setDeliveryWorktrees(await fetchDeliveryWorktrees(repoId))
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching delivery queue:', error)
    } finally {
      setDeliveryLoaded(true)
    }
  }

  // One fetch-and-set for the teardown model, shared by the initial-load effect
  // and the post-action refresh. `isStale` lets the effect drop a result that a
  // fast prd/repo switch has superseded, so a stale fetch never lands.
  const loadTeardownModel = async (isStale: () => boolean = () => false): Promise<void> => {
    if (!teardownPrdId || !repoId) return
    try {
      const model = await fetchPrdTeardown(repoId, teardownPrdId)
      if (!isStale()) setPrdTeardown(model)
    } catch (error) {
      if (!isStale()) console.error('[RepoDetailPage] Error loading PRD teardown:', error)
    }
  }

  // Re-fetch after a remediation action changes a branch's state (a reconcile can
  // flip conflict → ready → merged), so the island reflects the new posture
  // without a manual reload.
  const refreshTeardown = () => loadTeardownModel()

  // Load the teardown model when the ?island=prd:<id> view is active. Cancels a
  // stale fetch on prd/repo change so a fast switch never lands the wrong model.
  useEffect(() => {
    if (!teardownPrdId || !repoId) {
      setPrdTeardown(null)
      setPrdTeardownLoaded(false)
      return
    }
    let cancelled = false
    setPrdTeardown(null)
    setPrdTeardownLoaded(false)
    void loadTeardownModel(() => cancelled).finally(() => {
      if (!cancelled) setPrdTeardownLoaded(true)
    })
    return () => {
      cancelled = true
    }
    // loadTeardownModel closes over the same (teardownPrdId, repoId) deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [teardownPrdId, repoId])

  // Fetch full spike detail when the user selects a row. List endpoint
  // only carries summaries (cheap to refresh); detail carries tasks +
  // outcome body which only matter once the user is looking at one
  // spike.
  //
  // AbortController guards against the stale-response race: if the
  // user clicks spike A then B and A's response lands last, the
  // controller from A's call is aborted by B's, so the outdated
  // payload never reaches setSelectedSpike.
  const fetchSpikeDetail = async (
    spikeId: string,
    signal: AbortSignal,
  ): Promise<void> => {
    if (!repoId) return
    try {
      setSpikeDetailLoading(true)
      const response = await fetch(
        `/api/repos/${repoId}/spikes/${encodeURIComponent(spikeId)}`,
        { signal },
      )
      if (signal.aborted) return
      if (!response.ok) {
        console.error(
          '[RepoDetailPage] Spike detail fetch failed:',
          response.status,
          await response.text().catch(() => '(no body)'),
        )
        setSelectedSpike(null)
        return
      }
      const data = await response.json()
      if (!signal.aborted) setSelectedSpike(data.spike ?? null)
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') return
      console.error('[RepoDetailPage] Error fetching spike detail:', error)
      setSelectedSpike(null)
    } finally {
      if (!signal.aborted) setSpikeDetailLoading(false)
    }
  }

  // Fetch agents for this repo
  const fetchRepoAgents = async () => {
    try {
      setAgentsLoading(true)
      console.log('[RepoDetailPage] Fetching agents for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/agents`)
      console.log('[RepoDetailPage] Agents response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received agents:', data);
        console.log('[RepoDetailPage] Agents count:', data.agents?.length);
        setRepoAgents(data.agents || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo agents:', error)
    } finally {
      setAgentsLoading(false)
    }
  }

  // Fetch skills for this repo
  const fetchRepoSkills = async () => {
    try {
      setSkillsLoading(true)
      console.log('[RepoDetailPage] Fetching skills for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/skills`)
      console.log('[RepoDetailPage] Skills response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received skills:', data);
        console.log('[RepoDetailPage] Skills count:', data.skills?.length);
        setRepoSkills(data.skills || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo skills:', error)
    } finally {
      setSkillsLoading(false)
    }
  }

  // Fetch plugins for this repo
  const fetchRepoPlugins = async () => {
    try {
      setPluginsLoading(true)
      console.log('[RepoDetailPage] Fetching plugins for repo:', repoId);
      // Use the repo path from repoInfo, or decode the repoId
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/plugins/repo/${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Plugins response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received plugins:', data);
        console.log('[RepoDetailPage] Plugins count:', data.plugins?.length);
        setRepoPlugins(data.plugins || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plugins:', error)
    } finally {
      setPluginsLoading(false)
    }
  }

  // Fetch hooks for this repo
  const fetchRepoHooks = async () => {
    try {
      setHooksLoading(true)
      console.log('[RepoDetailPage] Fetching hooks for repo:', repoId);
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/hooks?repoPath=${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Hooks response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received hooks:', data);
        setRepoHooks(data)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo hooks:', error)
    } finally {
      setHooksLoading(false)
    }
  }

  // Eagerly fetch quality criteria for tab badge
  const fetchQualityCriteria = async () => {
    try {
      const response = await fetch(`/api/repos/${repoId}/quality-scores`)
      if (response.ok) {
        const data = await response.json()
        if (data.readiness) {
          setQualityCriteria(data.readiness)
        }
      }
    } catch {
      // Ignore — criteria will be set when QualityTab renders
    }
  }

  // Fetch quality runs for this repo
  const fetchRepoQualityRuns = async () => {
    try {
      setQualityLoading(true)
      console.log('[RepoDetailPage] Fetching quality runs for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/quality`)
      console.log('[RepoDetailPage] Quality response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality runs:', data);
        console.log('[RepoDetailPage] Quality runs count:', data.runs?.length);
        setRepoQualityRuns(data.runs || [])
        setLatestQualityGrade(data.latestGrade || null)
        setLatestQualityScore(data.latestScore ?? null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo quality runs:', error)
    } finally {
      setQualityLoading(false)
    }
  }

  // Fetch quality run details
  const fetchQualityRunDetail = async (runId: string) => {
    try {
      console.log('[RepoDetailPage] Fetching quality run detail:', runId);
      const response = await fetch(`/api/repos/${repoId}/quality/${runId}`)
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality run detail:', data);
        setSelectedQualityRun(data.run || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching quality run detail:', error)
    }
  }

  // Check setup status (lightweight: 3 small fetches)
  const checkSetupStatus = async () => {
    try {
      const [healthRes, analysisRes, recsRes] = await Promise.all([
        fetch(`/api/repos/${repoId}/config-health`),
        fetch(`/api/repos/${repoId}/analysis`),
        fetch(`/api/repos/${repoId}/recommendations`),
      ])
      const isHealthy = healthRes.ok && (await healthRes.json()).health?.status === 'healthy'
      const analysisExists = analysisRes.ok && (await analysisRes.json()).exists
      const noRecs = recsRes.ok && ((await recsRes.json()).recommendations ?? []).length === 0
      setSetupComplete(isHealthy && analysisExists && noRecs)
    } catch {
      // Silently handle — setupComplete stays false
    }
  }

  useEffect(() => {
    if (repoId) {
      // Clear only the fetched spike-detail object so a stale spike from a
      // previous repo doesn't flash before the refetch. The selected spike id
      // now lives in the URL (`?item=`), so it must NOT be wiped here — doing so
      // would strip a deep link (`?view=spikes&item=...`) on mount. Navigating
      // between repos already lands on a fresh URL with no `?item=`.
      setSelectedSpike(null)
      fetchRepoInfo()
      fetchRepoPlans()
      fetchRepoFixes()
      fetchRepoSpikes()
      fetchRepoWorktrees()
      fetchRepoDeliveryQueue()
      fetchRepoAgents()
      fetchRepoSkills()
      fetchRepoQualityRuns()
      fetchQualityCriteria()
      checkSetupStatus()
    }
  }, [repoId])

  // Clear current-repo context when leaving the page so the header reverts
  useEffect(() => {
    return () => setCurrentRepo(null)
  }, [setCurrentRepo])

  // Refetch spike detail when the user picks a different row. The
  // effect's cleanup aborts the in-flight request — rapid A→B clicks
  // can't leave A's data showing under B's selection.
  useEffect(() => {
    if (!selectedSpikeId) {
      setSelectedSpike(null)
      setSpikeDetailLoading(false)
      return
    }
    const controller = new AbortController()
    fetchSpikeDetail(selectedSpikeId, controller.signal)
    return () => controller.abort()
    // fetchSpikeDetail closes over repoId, which is captured by the
    // outer effect's deps; safe to omit from this effect's deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedSpikeId])

  // Live overlay (PRD progress-json-as-event-projection F4/T5): a
  // server-side `spike-doc-change` event for the currently-selected
  // spike refetches the projection. The hook no-ops when nothing is
  // selected — no SSE bookkeeping in the idle case.
  useSpikeDocLive(
    repoId ?? null,
    selectedSpikeId,
    () => {
      // Fresh AbortController per refetch — the previous controller
      // belongs to the original selection effect and is torn down
      // there.
      fetchSpikeDetail(selectedSpikeId!, new AbortController().signal)
    },
  )

  // Live overlay (Fix: dashboard-drops-filewatcher-sse-events): a
  // markdown edit to a PRD/feature or fix doc emits prd-doc-change /
  // fix-doc-change (not the git-ref `invalidate` this view otherwise
  // relies on). Bridge those into a repo-scoped refetch so the per-repo
  // plans/fixes update live on edit, mirroring the spike doc overlay.
  usePrdDocLive(repoId ?? null, () => fetchRepoPlans())
  useFixDocLive(repoId ?? null, () => fetchRepoFixes())

  // Fetch plugins and hooks after repoInfo is loaded (they need the repo path)
  useEffect(() => {
    if (repoInfo?.path) {
      fetchRepoPlugins()
      fetchRepoHooks()
    }
  }, [repoInfo?.path])

  // Auto-select first plan or validate the URL selection. Gated on the active
  // area so it only drives `?item=` while Plans is showing — otherwise it would
  // fire for the (null) plan selection while another area is active.
  useEffect(() => {
    if (activeTab !== 'plans') return
    if (plans.length > 0) {
      if (!selectedPlanId || !plans.find(p => p.id === selectedPlanId)) {
        setSelectedPlanId(plans[0].id)
      }
    }
  }, [activeTab, plans, selectedPlanId])

  // Auto-select first fix or validate the URL selection (gated on the Fixes area).
  useEffect(() => {
    if (activeTab !== 'fixes') return
    if (fixes.length > 0) {
      if (!selectedFixId || !fixes.find(f => f.id === selectedFixId)) {
        setSelectedFixId(fixes[0].id)
      }
    }
  }, [activeTab, fixes, selectedFixId])

  // Auto-select first agent or validate persisted selection
  useEffect(() => {
    if (repoAgents.length > 0) {
      if (!selectedAgentId || !repoAgents.find(a => a.id === selectedAgentId)) {
        setSelectedAgentId(repoAgents[0].id)
      }
    }
  }, [repoAgents, selectedAgentId])

  // Auto-select first skill or validate persisted selection
  useEffect(() => {
    if (repoSkills.length > 0) {
      if (!selectedSkillId || !repoSkills.find(s => s.id === selectedSkillId)) {
        setSelectedSkillId(repoSkills[0].id)
      }
    }
  }, [repoSkills, selectedSkillId])

  // Auto-select first plugin or validate persisted selection
  useEffect(() => {
    if (repoPlugins.length > 0) {
      if (!selectedPluginId || !repoPlugins.find(p => p.path === selectedPluginId)) {
        setSelectedPluginId(repoPlugins[0].path)
      }
    }
  }, [repoPlugins, selectedPluginId])

  // Auto-select first quality run or validate persisted selection
  useEffect(() => {
    if (repoQualityRuns.length > 0) {
      if (!selectedQualityRunId || !repoQualityRuns.find(r => r.runId === selectedQualityRunId)) {
        setSelectedQualityRunId(repoQualityRuns[0].runId)
      }
    }
  }, [repoQualityRuns, selectedQualityRunId])

  // Auto-select first hook when hooks load
  useEffect(() => {
    const allHooks = [...repoHooks.pluginHooks, ...(repoHooks.repoHooks ?? []), ...repoHooks.gitHooks]
    if (allHooks.length > 0 && !selectedHook) {
      setSelectedHook(allHooks[0])
    }
  }, [repoHooks, selectedHook])

  // Fetch quality run details when selection changes
  useEffect(() => {
    if (selectedQualityRunId) {
      fetchQualityRunDetail(selectedQualityRunId)
    } else {
      setSelectedQualityRun(null)
    }
  }, [selectedQualityRunId, repoId])

  // Patch the single affected fix/plan on a granular status push
  // (live-frontier-projection F3-T1). The event carries only the changed
  // entities (adds + modifications); merge them by id rather than refetching.
  useSSEEvent<StatusChangeEvent>('statusChange', (event) => {
    // Only process events for this repo
    if (event.repoId && event.repoId !== repoId) {
      return;
    }

    // Entities are Plan[] when resource is 'plan', Fix[] when 'fix'.
    // TypeScript can't narrow the union from the resource discriminant, so we cast.
    if (event.resource === 'plan') {
      setRepoPlans(prevPlans => {
        const updatedPlans = [...prevPlans];
        for (const entity of event.entities as Plan[]) {
          const idx = updatedPlans.findIndex(p => p.id === entity.id);
          if (idx !== -1) {
            updatedPlans[idx] = entity;
          } else {
            updatedPlans.push(entity);
          }
        }
        return updatedPlans;
      });
    } else if (event.resource === 'fix') {
      setRepoFixes(prevFixes => {
        const updatedFixes = [...prevFixes];
        for (const entity of event.entities as Fix[]) {
          const idx = updatedFixes.findIndex(f => f.id === entity.id);
          if (idx !== -1) {
            updatedFixes[idx] = entity;
          } else {
            updatedFixes.push(entity);
          }
        }
        return updatedFixes;
      });
    }
  });

  // Listen to SSE quality-change events and refetch quality data
  useSSEEvent('qualityChange', (event: any) => {
    console.log('[RepoDetailPage] Received quality-change event:', event.eventType, event);

    // Only process events for this repo
    if (event.repoId && event.repoId !== repoId) {
      console.log('[RepoDetailPage] Ignoring quality event for different repo:', event.repoId);
      return;
    }

    // Refetch quality runs to get the latest data
    console.log('[RepoDetailPage] Refetching quality runs after SSE event');
    fetchRepoQualityRuns();
  });

  const handlePlanSelect = (planId: string) => {
    setSelectedPlanId(planId)
  }

  const handleFixSelect = (fixId: string) => {
    setSelectedFixId(fixId)
  }

  const handleAgentSelect = (agentId: string) => {
    setSelectedAgentId(agentId)
  }

  const handleSkillSelect = (skillId: string) => {
    setSelectedSkillId(skillId)
  }

  const handlePluginSelect = (pluginId: string) => {
    setSelectedPluginId(pluginId)
  }

  const handleHookSelect = (hook: Hook) => {
    setSelectedHook(hook)
  }

  const handleArchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'archived' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving plan:', error)
    }
  }

  const handleUnarchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'active' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving plan:', error)
    }
  }

  const handleArchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: true } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving fix:', error)
    }
  }

  const handleUnarchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: false } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving fix:', error)
    }
  }

  // The selected fix is the server-projected entity directly — `fixes` is already
  // the merged projection (F4-T1), and a live status change arrives as a per-entity
  // `status-change` patch rather than a client-side telemetry re-derivation.
  const selectedFix = selectedFixId ? fixes.find((f: Fix) => f.id === selectedFixId) ?? null : null
  const selectedAgent = selectedAgentId ? repoAgents.find((a: Agent) => a.id === selectedAgentId) : null
  const selectedSkill = selectedSkillId ? repoSkills.find((s: Skill) => s.id === selectedSkillId) : null
  const selectedPlugin = selectedPluginId ? repoPlugins.find((p: RepoPlugin) => p.path === selectedPluginId) : null

  // In-place task detail view — replaces the stage rail + workspace body while
  // keeping RepoDetailPage (and its warm data) mounted. The task is resolved
  // from the already-loaded, server-projected plan/fix so its phase commit
  // SHAs (e.g. the RED commit) are available to the tab content without a
  // refetch.
  if (selectedTaskId && repoId) {
    // Resolve the task plus, for the header meta line, its 1-based ordinal and
    // container id (feature id for a plan task, fix id for a fix task).
    const location = resolveTaskLocation(selectedPlan, selectedFix, selectedTaskId)
    // Lift the launch-ref pinned pipeline plan onto the task so the detail's
    // tab bar surfaces every pinned gate (task-pipeline-shows-pinned-gates),
    // matching the per-task strip.
    const detailTask = location?.task ? applyWorktreePhaseShas(location.task) : undefined
    return (
      <DetailsPopoverProvider>
        <div className="flex flex-col h-full overflow-hidden">
          <TaskDetailPage
            repoId={repoId}
            taskId={selectedTaskId}
            task={detailTask}
            taskNumber={location?.taskNumber}
            container={location?.container}
            tab={selectedTaskRawTab}
            onTabChange={openTaskTab}
            onBack={closeTask}
            reviewPipeline={reviewPipeline}
          />
        </div>
      </DetailsPopoverProvider>
    )
  }

  // In-place WorkerRun island (F12) — the run drill-down opened from a feature
  // rail's Running pill. A content-replacing view keyed by runId, like the task
  // / worktree-merge islands; the island reads the run record + tails its SSE.
  if (selectedRunId && repoId) {
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <WorkerRunIsland
          repoId={repoId}
          runId={selectedRunId}
          onClose={() => { closeRun(); repoRuns.refresh(); }}
        />
      </div>
    )
  }

  // In-place PRD teardown island — the ?island=prd:<id> content-replacing view.
  // Keyed by PRD id (not a branch), hydrated from the fetched teardown model,
  // reusing the shared Island shell. Checked before the branch island so a
  // `prd:` id never falls through to the branch match.
  if (teardownPrdId && repoId) {
    const closeIsland = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('island')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        {prdTeardown ? (
          <PrdTeardownIsland
            open
            model={prdTeardown}
            onClose={closeIsland}
            // Re-check a conflicted branch = reconcile it, then refresh the model.
            // A failed reconcile is logged, never an unhandled rejection.
            onRecheck={(branch) => {
              void postDeliveryAction(repoId, 'reconcile', { branch })
                .then(refreshTeardown)
                .catch((error) => console.error('[RepoDetailPage] Re-check reconcile failed:', error))
            }}
          />
        ) : (
          <div className="grid h-full place-items-center px-6 pb-6 pt-[8vh] text-center">
            {!prdTeardownLoaded ? (
              <p className="text-sm text-muted-foreground" role="status">Loading teardown…</p>
            ) : (
              <div className="panel max-w-md rounded-2xl p-6">
                <p className="display text-lg font-bold">No teardown for this PRD</p>
                <p className="mono mt-1 truncate text-xs text-muted-foreground">{teardownPrdId}</p>
                <button
                  type="button"
                  onClick={closeIsland}
                  className="btn-primary mt-4 inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-semibold"
                >
                  Back to workspace
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  // In-place worktree-merge island — replaces the stage rail + body like the task
  // view, so only the top rail shows and the single app wash shows through the
  // island's transparent backdrop (nothing opaque behind to bleed).
  if (islandBranch && repoId) {
    const row = deliveryWorktrees.find((w) => w.branch === islandBranch)
    const closeIsland = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('island')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        {row ? (
          <WorktreeDeliveryIsland
            repoId={repoId}
            worktree={row}
            open
            onClose={closeIsland}
            onActionComplete={fetchRepoDeliveryQueue}
          />
        ) : (
          // No matching row. While the delivery queue is still resolving (a
          // ?island= deep-link or reload lands here first), show a loading state;
          // once it's loaded the branch genuinely isn't deliverable — say so with
          // a way back, rather than silently dropping to the workspace.
          <div className="grid h-full place-items-center px-6 pb-6 pt-[8vh] text-center">
            {!deliveryLoaded ? (
              <p className="text-sm text-muted-foreground" role="status">Loading worktree…</p>
            ) : (
              <div className="panel max-w-md rounded-2xl p-6">
                <p className="display text-lg font-bold">No deliverable worktree here</p>
                <p className="mono mt-1 truncate text-xs text-muted-foreground">{islandBranch}</p>
                <p className="mt-2 text-sm text-muted-foreground">
                  It may have already landed or been torn down.
                </p>
                <button
                  type="button"
                  onClick={closeIsland}
                  className="btn-primary mt-4 inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-semibold"
                >
                  Back to workspace
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  // In-place design-assets view (surface-design-assets F4) — a content-replacing
  // island like ?island / ?task: the shared Island shell shows the single app
  // wash through its transparent backdrop and dismisses on backdrop-click /
  // Escape, returning to the detail it was opened from. Kind from the active
  // area, slug from the selected item; either missing → fall through.
  const assetsKind = assetsOpen ? deriveAssetsKind(activeTab) : null
  if (assetsOpen && assetsKind && selectedItemId && repoId) {
    const closeAssets = () =>
      setSearchParams((prev) => {
        const next = new URLSearchParams(prev)
        next.delete('assets')
        return next
      })
    return (
      <div className="flex flex-col h-full overflow-hidden">
        <AssetsIsland repoId={repoId} kind={assetsKind} slug={selectedItemId} onClose={closeAssets} />
      </div>
    )
  }

  return (
    <DetailsPopoverProvider>
    <div className="flex flex-col h-full overflow-hidden">
      {/* Stage rail: Plans/Fixes/Spikes work areas + the Worktrees delivery lens.
          Quality and Settings live in the top breadcrumb rail (RepoViewControls).
          Transparent (no surface/border) so the ambient background shows through.
          Sits directly under the repo header — no extra top gap. */}
      <div className="flex-shrink-0">
        <StageRail
          activeTab={settingsOpen ? null : asWorkArea(activeTab)}
          counts={workAreaCounts}
          inFlightCount={inFlightRailCount}
          onInFlightSelect={() => { setActiveTab('in-flight'); setListSearch(''); }}
          inFlightActive={activeTab === 'in-flight'}
          onTabSelect={(area) => { setActiveTab(area); setListSearch(''); }}
        />
      </div>

      {/* Content. Settings renders inline in place of the workspace body. */}
      <div className="flex-1 overflow-hidden">
        {settingsOpen && repoId ? (
          <SetupTab
            repoId={repoId}
            repoPath={repoInfo?.path}
            initialSection={settingsSection}
            onSectionChange={setSettingsSection}
            onNavigateToPlans={() => { setActiveTab('plans'); }}
            onSetupComplete={setSetupComplete}
          />
        ) : activeTab === 'quality' ? (
          repoId ? (
            <QualityTab
              repoId={repoId}
              runs={repoQualityRuns}
              selectedRun={selectedQualityRun}
              selectedRunId={selectedQualityRunId}
              onCriteriaChange={setQualityCriteria}
              onRunDeleted={() => {
                setSelectedQualityRunId(null)
                setSelectedQualityRun(null)
                fetchRepoQualityRuns()
              }}
            />
          ) : null
        ) : activeTab === 'in-flight' ? (
          // The one operations board. Selecting a row (?item=) renders its
          // detail in the main pane: a worker/failed run -> the WorkerRun
          // island, a delivery worktree -> the Land-this-work detail (land or
          // cleanup).
          <InFlightView
            lanes={inFlight.lanes}
            selectedKey={selectedItemId}
            onSelect={(row) => setSelectedItemId(inFlightRowKey(row))}
            renderDetail={renderInFlightDetail}
          />
        ) : (
        <ResizablePanelGroup direction="horizontal" onLayout={workspacePanels.onLayout}>
          {/* Sidebar */}
          <ResizablePanel defaultSize={workspacePanels.defaultSize(0, 30)} minSize={20} maxSize={40}>
            <div className="h-full flex flex-col">
              {/* List search + status filter. Transparent and borderless so it
                  flows out of the stage rail rather than reading as a separate
                  bordered bar. The filter button reveals the status pills. */}
              {(activeTab === 'plans' || activeTab === 'fixes' || activeTab === 'spikes') && (
                <div className="flex-shrink-0 space-y-2 px-3 pb-2">
                  <div className="flex items-stretch gap-2">
                    <ListSearchBox
                      value={listSearch}
                      onChange={setListSearch}
                      placeholder={`Search ${activeTab}…`}
                    />
                    <button
                      type="button"
                      aria-label={`Filter ${activeTab}`}
                      aria-pressed={filtersOpen}
                      onClick={() => setFiltersOpen((open) => !open)}
                      className={cn(
                        'grid shrink-0 place-items-center rounded-md border border-border px-3 transition-colors',
                        filtersOpen ? 'text-foreground' : 'text-muted-foreground hover:text-foreground',
                      )}
                    >
                      <ListFilter className="h-4 w-4" />
                    </button>
                  </div>
                  {filtersOpen && activeListFilter && (
                    <ListStatusFilter
                      active={activeListFilter.active}
                      onToggle={activeListFilter.onToggle}
                      counts={activeListFilter.counts}
                      statuses={activeListFilter.statuses}
                    />
                  )}
                </div>
              )}
              <div className="flex-1 overflow-auto">
                {activeTab === 'plans' && (
                  loading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <PlanList
                      plans={filteredPlans}
                      selectedPlanId={selectedPlanId}
                      onSelectPlan={handlePlanSelect}
                    />
                  )
                )}
                {activeTab === 'fixes' && (
                  fixesLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <FixList
                      fixes={filteredFixes}
                      selectedFixId={selectedFixId}
                      onSelectFix={handleFixSelect}
                      reviewPipeline={reviewPipeline}
                      repoId={repoId}
                      onOpenRun={openRun}
                    />
                  )
                )}
                {activeTab === 'spikes' && (
                  spikesLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <SpikesList
                      spikes={filteredSpikes}
                      selectedSpikeId={selectedSpikeId}
                      onSelectSpike={setSelectedSpikeId}
                    />
                  )
                )}
                {activeTab === 'agents' && (
                  agentsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <AgentList
                      agents={repoAgents}
                      selectedAgentId={selectedAgentId}
                      onSelectAgent={handleAgentSelect}
                    />
                  )
                )}
                {activeTab === 'skills' && (
                  skillsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <SkillList
                      skills={repoSkills}
                      selectedSkillId={selectedSkillId}
                      onSelectSkill={handleSkillSelect}
                      repoId={repoId || ''}
                    />
                  )
                )}
                {activeTab === 'plugins' && (
                  pluginsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <RepoPluginList
                      plugins={repoPlugins}
                      selectedPluginId={selectedPluginId}
                      onSelectPlugin={handlePluginSelect}
                    />
                  )
                )}
                {activeTab === 'hooks' && (
                  hooksLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <HooksList
                      hooks={repoHooks}
                      selectedHook={selectedHook}
                      onSelectHook={handleHookSelect}
                    />
                  )
                )}
              </div>
            </div>
          </ResizablePanel>

          {/* The divider line is transparent for the top 60px (behind the
              header bar) and the real border colour below, so the splitter
              starts beneath the header — the header reads as one continuous
              strip while the list/detail divider stays visible and draggable. */}
          <ResizableHandle
            withHandle
            className="!bg-transparent bg-[linear-gradient(to_bottom,transparent_60px,#e5e7eb_60px)] dark:bg-[linear-gradient(to_bottom,transparent_60px,#252d3a_60px)]"
          />

          {/* Details */}
          <ResizablePanel defaultSize={workspacePanels.defaultSize(1, 70)}>
            <div className="h-full flex flex-col">
              {activeTab === 'plans' && (
                selectedPlan ? (
                  // The whole plan detail sits in one raised panel (mockup
                  // <main class="panel rounded-2xl">), floated by the margin —
                  // consistent with the fixes and spikes details. PlanDetails
                  // owns the header + scroll, so the whole section scrolls.
                  <div className="panel mx-3 mb-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">
                    <PlanDetails
                      plan={selectedPlan}
                      viewMode={viewMode}
                      repoId={repoId}
                      onArchive={() => handleArchivePlan(selectedPlan.id)}
                      onUnarchive={() => handleUnarchivePlan(selectedPlan.id)}
                      onOpenRun={openRun}
                    />
                  </div>
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {loading ? 'Loading plans...' : 'No plans found for this repository'}
                  </div>
                )
              )}
              {activeTab === 'fixes' && (
                selectedFix ? (
                  // The whole fix detail sits in one raised panel (mockup
                  // <main class="panel rounded-2xl">), floated by the margin —
                  // consistent with the plans and spikes details.
                  <div className="panel mx-3 mb-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">
                  <FixDetail
                    fix={selectedFix}
                    repoId={repoId!}
                    onArchive={() => handleArchiveFix(selectedFix.id)}
                    onUnarchive={() => handleUnarchiveFix(selectedFix.id)}
                    onOpenRun={openRun}
                  />
                  </div>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-muted-foreground gap-2">
                    <Bolt className="h-10 w-10" aria-hidden="true" />
                    <span>{fixesLoading ? 'Loading fixes...' : 'No fixes found for this repository'}</span>
                  </div>
                )
              )}
              {activeTab === 'spikes' && (
                selectedSpike ? (
                  // The whole spike detail sits in one raised panel (mockup
                  // <main class="panel rounded-2xl">), floated by the margin —
                  // consistent with the plans detail.
                  <div className="panel mx-3 mb-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">
                  <SpikeDetail
                    spike={selectedSpike}
                    worktreeStatus={getSpikeWorktreeStatus(selectedSpike.worktree, repoWorktrees)}
                    repoId={repoId ?? ''}
                    telemetry={telemetry}
                    onWorktreeCleared={() => {
                      // The fire-and-forget refetch can't be cancelled
                      // from a callback — the AbortController earlier
                      // here was decorative. The existing
                      // selectedSpikeId effect's cleanup is the real
                      // serialisation point against rapid switches.
                      if (selectedSpikeId) {
                        fetchSpikeDetail(selectedSpikeId, new AbortController().signal)
                      }
                      fetchRepoWorktrees()
                    }}
                    onWorktreeProvisioned={() => {
                      // Launch just created the worktree — refetch the detail
                      // (worktreeStatus flips unconfigured → present) and the
                      // worktree list (the new spike/<id> worktree appears).
                      if (selectedSpikeId) {
                        fetchSpikeDetail(selectedSpikeId, new AbortController().signal)
                      }
                      fetchRepoWorktrees()
                    }}
                    onOutcomeRecorded={() => {
                      // Refetch both the detail (status flipped to
                      // terminal, outcome banner appears) and the
                      // sidebar (the spike's status badge updates).
                      if (selectedSpikeId) {
                        fetchSpikeDetail(selectedSpikeId, new AbortController().signal)
                      }
                      fetchRepoSpikes()
                    }}
                  />
                  </div>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-muted-foreground gap-2">
                    <Zap className="h-10 w-10" aria-hidden="true" />
                    <span>
                      {spikeDetailLoading
                        ? 'Loading spike…'
                        : selectedSpikeId
                          ? 'Spike not found'
                          : 'Pick a spike to see its detail'}
                    </span>
                  </div>
                )
              )}
              {activeTab === 'agents' && (
                selectedAgent ? (
                  <AgentDetail agent={selectedAgent} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {agentsLoading ? 'Loading agents...' : 'No agents installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'skills' && (
                selectedSkill ? (
                  <SkillDetail skill={selectedSkill} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {skillsLoading ? 'Loading skills...' : 'No skills installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'plugins' && (
                selectedPlugin ? (
                  <RepoPluginDetail plugin={selectedPlugin} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {pluginsLoading ? 'Loading plugins...' : 'No plugins available for this repository'}
                  </div>
                )
              )}
              {activeTab === 'hooks' && (
                <HookDetail
                  hook={selectedHook}
                  repoPath={repoInfo?.path || decodeURIComponent(repoId || '')}
                />
              )}
            </div>
          </ResizablePanel>
        </ResizablePanelGroup>
        )}
      </div>

    </div>
    </DetailsPopoverProvider>
  )
}
