import type { RunEvent } from '@magic-ingredients/tiny-brain-core';

/** A tool invocation folded from a `tool_use` and its later `tool_result`. The
 *  spine's `tool_result` carries only `success`, so a resolved call's `result`
 *  is `{ success }` — mirrors `useSkillInvocation`'s `ToolCall`. */
export interface RunToolCall {
  tool: string;
  input: unknown;
  id?: string;
  result?: { success: boolean };
}

/** A TDD pipeline phase the worker entered (`red`/`green`/a review step). */
export interface RunPhase {
  phase: string;
  taskId: string;
}

/** A commit the worker landed, with its conventional-commit prefix. */
export interface RunCommit {
  sha: string;
  prefix: string;
}

/** The renderable view of a run's activity, folded from its `RunEvent` stream. */
export interface RunActivity {
  /** Concatenated assistant text, in arrival order. */
  output: string;
  /** Tool invocations, each back-filled with its result once it lands. */
  toolCalls: RunToolCall[];
  /** Pipeline phases entered, in order. */
  phases: RunPhase[];
  /** Commits landed, in order. */
  commits: RunCommit[];
  /**
   * Whether an `exit` event has arrived. Activity-only liveness signal
   * (ADR-0017): the exit is a fetch trigger, NOT a status — callers use this to
   * stop the live marker, never to settle the run's outcome (status comes from
   * the git-fetch projection).
   */
  exited: boolean;
}

/**
 * Fold a run's `RunEvent`s into the {@link RunActivity} the dashboard renders.
 * Pure and order-preserving. The `tool_result` back-fill walks to the most
 * recent result-less call (mirroring `useSkillInvocation.deriveToolCalls`), so
 * out-of-the-spine ordering still attaches each result to its call.
 */
export function deriveRunActivity(events: RunEvent[]): RunActivity {
  let output = '';
  const toolCalls: RunToolCall[] = [];
  const phases: RunPhase[] = [];
  const commits: RunCommit[] = [];
  let exited = false;

  for (const event of events) {
    switch (event.type) {
      case 'text':
        output += event.text;
        break;
      case 'tool_use':
        toolCalls.push({ tool: event.tool, input: event.input });
        break;
      case 'tool_result':
        for (let i = toolCalls.length - 1; i >= 0; i--) {
          if (!toolCalls[i].result) {
            toolCalls[i] = { ...toolCalls[i], id: event.toolId, result: { success: event.success } };
            break;
          }
        }
        break;
      case 'pipeline':
        phases.push({ phase: event.phase, taskId: event.taskId });
        break;
      case 'commit':
        commits.push({ sha: event.sha, prefix: event.prefix });
        break;
      case 'exit':
        exited = true;
        break;
      // spawn / usage / auto-commit / contract carry no rendered activity here.
    }
  }

  return { output, toolCalls, phases, commits, exited };
}
