import { metricTrend, semanticsFor, type MetricTrend } from './instrument-trend';
import { riskStateForStep, type VitalState } from './quality-posture';
import type { QualityScoresResponse, StepScoreResponse, MetricFacts, SeverityBuckets } from '../types';

/**
 * A Measured instrument — a single static-analyser fact rendered as a quantity
 * to keep low (never a grade). `series` and `deltaLabel` are optional because
 * quality runs do not yet persist per-analyser history; until that lands the
 * builder emits a current value with a flat/neutral trend, and the richer trend
 * data slots straight in when it arrives. `placeholder` marks a slot the run
 * cannot back yet — rendered as a neutral em-dash rather than a fabricated
 * number, so the Measured grid always shows the full instrument set.
 */
export interface Instrument {
  readonly key: string;
  readonly label: string;
  readonly value: string;
  readonly sublabel?: string;
  readonly series?: ReadonlyArray<number>;
  /** Run date (`YYYY-MM-DD`) for each plotted point, aligned index-for-index to
   *  `series`. Present only when the run history carries runIds that align to
   *  the full series; the detail view labels its axis from these and shows no
   *  axis without them (never an invented date). */
  readonly seriesDates?: ReadonlyArray<string>;
  readonly deltaLabel?: string;
  readonly trend: MetricTrend;
  /** Risk state for the dot. Omitted for placeholders — they have no run data
   *  and so no risk direction; the card renders a neutral dot instead. */
  readonly dotState?: VitalState;
  readonly placeholder?: boolean;
  /** Latest run's severity breakdown for an issue-backed metric, threaded from
   *  the run history (`history.bucketed`). Absent for a metric the run does not
   *  bucket (e.g. coverage), so the detail trend narrates a mix only when real. */
  readonly severity?: SeverityBuckets;
}

interface MetricSlot {
  readonly key: string;
  readonly label: string;
  /** Pipeline step type that backs this slot when present in the scores. */
  readonly stepType: string;
  /** The numeric quantity-to-keep-low used for the value, trend, and delta. */
  readonly current: (step: StepScoreResponse) => number;
  /** Unit suffix appended to the value and delta (e.g. '%'); '' for counts. */
  readonly unit?: string;
  readonly sublabel?: (step: StepScoreResponse) => string | undefined;
  /** Headline value from richer per-metric facts, when the run carries them.
   *  Returns undefined when a required fact is missing so the caller falls back
   *  (MetricFacts is an open Record, so keys aren't guaranteed at the type). */
  readonly factsValue?: (facts: MetricFacts) => string | undefined;
  /** Sublabel from richer per-metric facts; undefined when a fact is missing. */
  readonly factsSublabel?: (facts: MetricFacts) => string | undefined;
}

/** The date portion (`YYYY-MM-DD`) of a runId. Nested runIds are
 *  `YYYY-MM-DDThh-mm`; a legacy flat id with no 'T' is returned as-is. */
const runDatePart = (runId: string): string => {
  const t = runId.indexOf('T');
  return t === -1 ? runId : runId.slice(0, t);
};

/**
 * Run dates for the plotted points, aligned to the non-null series in lockstep.
 * Returns undefined unless `runIds` aligns index-for-index to the full
 * (null-inclusive) series — a length mismatch can't be aligned honestly, so the
 * dates are dropped rather than guessed.
 */
function alignedRunDates(
  rawSeries: ReadonlyArray<number | null> | undefined,
  runIds: ReadonlyArray<string> | undefined,
): string[] | undefined {
  if (!rawSeries || !runIds || runIds.length !== rawSeries.length) return undefined;
  const dates: string[] = [];
  rawSeries.forEach((value, i) => {
    if (value !== null) dates.push(runDatePart(runIds[i]));
  });
  return dates;
}

/** True when every named fact is a real number (guards the open MetricFacts Record). */
const hasFacts = (facts: MetricFacts, ...keys: string[]): boolean =>
  keys.every((k) => Number.isFinite(facts[k]));

const pluralAdvisories = (n: number): string => (n === 1 ? '1 advisory' : `${n} advisories`);
const findings = (step: StepScoreResponse): number => step.findingsCount;

/** Render a metric's numeric value with its unit — the single place the unit
 *  is applied, shared by the headline value and the delta label. */
const formatValue = (slot: MetricSlot, n: number): string => `${n}${slot.unit ?? ''}`;

/**
 * The six Measured instrument slots, in mockup order. Each names the pipeline
 * step type that backs it. Coverage, the dependency audit, eslint (Lint) and
 * typescript (Type errors) are emitted by the default pipeline, so those four
 * carry real values. Survived mutants (`mutation`) and the test suite (`test`)
 * have no pipeline step yet, so they render as placeholders until those steps
 * start landing in a run — at which point they light up with no change here.
 */
const SLOTS: ReadonlyArray<MetricSlot> = [
  {
    key: 'uncovered',
    label: 'Uncovered',
    stepType: 'coverage',
    current: (s) => Math.max(0, Math.round(100 - s.score)),
    unit: '%',
    sublabel: () => 'of lines',
    factsSublabel: (f) =>
      hasFacts(f, 'branchesUncoveredPct') ? `of lines · ${f.branchesUncoveredPct}% of branches untested` : undefined,
  },
  { key: 'lint', label: 'Lint', stepType: 'eslint', current: findings },
  {
    key: 'survived-mutants',
    label: 'Survived mutants',
    stepType: 'mutation',
    current: findings,
    factsValue: (f) => (hasFacts(f, 'survived') ? `${f.survived}` : undefined),
    factsSublabel: (f) => (hasFacts(f, 'total', 'killRate') ? `of ${f.total} · ${f.killRate}% killed` : undefined),
  },
  {
    key: 'dependency-vulns',
    label: 'Dependency vulns',
    stepType: 'dependency-audit',
    current: findings,
    sublabel: (s) => pluralAdvisories(s.findingsCount),
  },
  { key: 'type-errors', label: 'Type errors', stepType: 'typescript', current: findings },
  {
    key: 'test-suite',
    label: 'Test suite',
    stepType: 'test',
    current: findings,
    factsValue: (f) => (hasFacts(f, 'total') ? `${f.total}` : undefined),
    factsSublabel: (f) =>
      hasFacts(f, 'skipped', 'durationMs')
        ? `${f.skipped} skipped · ${Number.isFinite(f.flaky) ? f.flaky : 0} flaky · ${(f.durationMs / 1000).toFixed(1)}s`
        : undefined,
  },
];

/** The metric keys this builder produces (used to guard the SLOT ↔
 * trend-semantics tables against drift). */
export const measuredMetricKeys = (): string[] => SLOTS.map((s) => s.key);

/** The display label for an instrument key (e.g. 'dependency-vulns' →
 * 'Dependency vulns'), or undefined for an unknown key. SLOTS is the single
 * source so the breadcrumb crumb and the Measured grid can never disagree. */
export const instrumentLabelForKey = (key: string): string | undefined =>
  SLOTS.find((s) => s.key === key)?.label;

/**
 * Format a run-over-run change as a delta label (`▼ 3`, `▲ 60`, `▼ 2%`).
 * Returns undefined for an unchanged metric so the card shows no delta. The
 * arrow follows the raw direction (down/up); the trend colour (good/bad/neutral)
 * is carried separately on `trend.colour`. The unit comes from the slot, the
 * same source as the headline value, so the two never drift.
 */
function formatDelta(slot: MetricSlot, trend: MetricTrend): string | undefined {
  if (trend.direction === 'flat' || trend.delta === 0) return undefined;
  const arrow = trend.direction === 'down' ? '▼' : '▲';
  return `${arrow} ${formatValue(slot, Math.abs(trend.delta))}`;
}

export function buildInstruments(data: QualityScoresResponse | null): Instrument[] {
  if (!data) return [];

  const stepByType = new Map(data.steps.map((s) => [s.type, s]));
  const history = data.history;

  // Always emit the full six-slot instrument set so the Measured grid matches
  // the mockup. A slot whose backing analyser step is absent from the run is an
  // honest placeholder (em-dash value, neutral dot, no sparkline/delta) rather
  // than a fabricated zero. A backed slot lights up its sparkline + delta the
  // moment its metric has >=2 runs of history; with fewer points it shows a
  // flat/neutral trend and no series. Agent-lens steps (security, performance,
  // …) have no slot and belong to Observed, not Measured.
  return SLOTS.map((slot) => {
    const step = stepByType.get(slot.stepType);
    if (!step) {
      return {
        key: slot.key,
        label: slot.label,
        value: '—',
        sublabel: 'not measured yet',
        trend: metricTrend(0, undefined, semanticsFor(slot.key)),
        placeholder: true,
      };
    }

    const semantics = semanticsFor(slot.key);
    // Richer per-metric facts (e.g. mutation kill-rate) override the headline
    // value + sublabel; history (below) still drives the series/delta.
    const facts = data.metricFacts?.[slot.key];
    const factsValue = facts && slot.factsValue ? slot.factsValue(facts) : undefined;
    const factsSublabel = facts && slot.factsSublabel ? slot.factsSublabel(facts) : undefined;

    // History is aligned to runs with `null` gaps for runs missing the metric;
    // drop those so the sparkline plots only real measurements. The run dates
    // are filtered in the same lockstep so they stay aligned to the points.
    const rawSeries = history?.series[slot.key];
    const points = rawSeries?.filter((v: number | null): v is number => v !== null);

    if (points && points.length >= 2) {
      const current = points[points.length - 1];
      const previous = points[points.length - 2];
      const trend = metricTrend(current, previous, semantics);
      // Latest run's severity bucket for an issue-backed metric (counts never
      // gap, so the last bucket aligns to the headline value). Absent metrics
      // (e.g. coverage) carry no bucket series.
      const bucketSeries = history?.bucketed?.[slot.key];
      const severity =
        bucketSeries && bucketSeries.length > 0 ? bucketSeries[bucketSeries.length - 1] : undefined;
      return {
        key: slot.key,
        label: slot.label,
        // Headline value comes from the same last series point as the sparkline,
        // so the number and the line it sits beside can never disagree (unless
        // richer facts give a more precise figure).
        value: factsValue ?? formatValue(slot, current),
        sublabel: factsSublabel ?? slot.sublabel?.(step),
        series: points,
        seriesDates: alignedRunDates(rawSeries, history?.runIds),
        deltaLabel: formatDelta(slot, trend),
        trend,
        dotState: riskStateForStep(step),
        ...(severity ? { severity } : {}),
      };
    }

    return {
      key: slot.key,
      label: slot.label,
      value: factsValue ?? formatValue(slot, slot.current(step)),
      sublabel: factsSublabel ?? slot.sublabel?.(step),
      trend: metricTrend(slot.current(step), undefined, semantics),
      dotState: riskStateForStep(step),
    };
  });
}
