import React from 'react';
import { LucideIcon, ArrowLeft, Settings } from 'lucide-react';
import { useCurrentRepo } from '../../contexts/CurrentRepoContext';
import { useLocation, useNavigate } from 'react-router-dom';
import { RepoHeader } from './RepoHeader';
import { RepoViewControls } from './RepoViewControls';
import { cn } from '@/lib/utils';

interface HeaderProps {
  currentItem?: {
    title: string;
    icon: LucideIcon;
  };
}

export const Header: React.FC<HeaderProps> = ({
  currentItem
}) => {
  const { repo: currentRepo } = useCurrentRepo();
  const location = useLocation();
  const navigate = useNavigate();

  // Check if we're on a detail page
  const isPersonaDetailPage = location.pathname.match(/^\/personas\/[^/]+$/);
  const isRepoDetailPage = location.pathname.match(/^\/repos\/[^/]+$/);
  const isSettingsPage = location.pathname === '/settings';
  const repoIdFromPath = isRepoDetailPage ? decodeURIComponent(location.pathname.split('/')[2] ?? '') : null;

  // Repo workspace: a dedicated header (breadcrumb + plan badge). The
  // tiny-brain logo lives in the sidebar now, so this header carries no logo.
  // The breadcrumb reads the repo-internal nav (Quality / Settings / drill-down)
  // straight from the URL.
  if (isRepoDetailPage) {
    return (
      <header className="flex h-16 items-center justify-between gap-4 px-3">
        <RepoHeader
          className="min-w-0 flex-1"
          repoName={currentRepo?.name ?? repoIdFromPath ?? ''}
          onBack={() => navigate('/repos')}
        />
        {/* Repo view-switches (Quality / Settings) live in this top rail now,
            right-aligned beside the breadcrumb. */}
        <RepoViewControls />
      </header>
    );
  }

  return (
    <header
      className={cn(
        'flex h-16 items-center justify-between gap-4 px-3',
        // The settings pane has its own tab-bar underline directly below, so the
        // header's own bottom border would double up right above the tabs.
        !isSettingsPage && 'border-b border-border',
      )}
    >
      <div className="flex min-w-0 items-center">
        {isPersonaDetailPage ? (
          <button
            onClick={() => navigate('/personas')}
            className="-mx-2 flex items-center gap-2 rounded-lg px-2 py-1 text-muted-foreground transition-colors hover:text-foreground"
          >
            <ArrowLeft className="h-4 w-4" />
            <span className="font-medium">Back to Personas</span>
          </button>
        ) : isSettingsPage ? (
          <div className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            <span className="font-medium">Settings</span>
          </div>
        ) : (
          currentItem && (
            <div className="flex items-center gap-2">
              <currentItem.icon className="h-5 w-5" />
              <span className="font-medium">{currentItem.title}</span>
            </div>
          )
        )}
      </div>
    </header>
  );
};