import React, { useMemo } from 'react';
import { SidebarCard } from './SidebarCard';
import { cardTitleMarkers } from './CardTitleMarkers';
import MiniStatusRail from './MiniStatusRail';
import { StatusPill, type StatusVariant } from './StatusPill';
import { deriveEffectiveStatus, deriveWorktreeBranches, rollUpEffectiveStatuses } from '../utils/effective-task-status';
import { toEffectiveTask } from '../utils/effective-task';
import type { Plan } from '../types';

/** Day-granular relative label shared by the date-only and full-ISO paths.
 *  `diffDays <= 0` is today (the ISO path never reaches here below 24h, so this
 *  branch is exercised only by date-only values). */
function relativeFromDays(diffDays: number): string {
  if (diffDays <= 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) {
    const weeks = Math.floor(diffDays / 7);
    return `${weeks} ${weeks === 1 ? 'week' : 'weeks'} ago`;
  }
  if (diffDays < 365) {
    const months = Math.floor(diffDays / 30);
    if (months === 1 && diffDays > 30) {
      return 'over a month ago';
    }
    return `${months} ${months === 1 ? 'month' : 'months'} ago`;
  }
  const years = Math.floor(diffDays / 365);
  return `${years} ${years === 1 ? 'year' : 'years'} ago`;
}

// Format date to relative time. Exported for unit coverage of the date-only path.
export function formatRelativeTime(dateStr: string | undefined): string {
  if (!dateStr) return 'Never';

  // A bare `YYYY-MM-DD` carries no time: `new Date('2026-06-22')` parses to
  // midnight UTC, so the sub-day branches below would fabricate "Nh ago" for an
  // item created earlier today (`tb work add prd`/`add feature` stamp date-only
  // `created`/`updated`). Read it as a LOCAL calendar day and compare whole days
  // — skipping the minute/hour granularity that has no basis without a time.
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
    const [y, m, d] = dateStr.split('-').map(Number);
    const then = new Date(y, m - 1, d);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const diffDays = Math.round((today.getTime() - then.getTime()) / (1000 * 60 * 60 * 24));
    return relativeFromDays(diffDays);
  }

  const date = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffMinutes = Math.floor(diffMs / (1000 * 60));

  if (diffMinutes < 1) return 'Just now';
  if (diffMinutes < 60) return `${diffMinutes}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  return relativeFromDays(diffDays);
}

interface PlanCardProps {
  plan: Plan;
  isSelected: boolean;
  onClick: () => void;
}

const PlanCard: React.FC<PlanCardProps> = ({ plan, isSelected, onClick }) => {
  const planName = plan.title || plan.name || 'Unnamed Plan';
  const updatedDate = formatRelativeTime(plan.updatedAt || plan.lastUpdated);

  // Branches this PRD's work lives on, each flagged with whether a live worktree
  // exists for it. Keyed on the BRANCH (the stable identity) so the same
  // physical worktree — which surfaces both as a task/source worktree dir-name
  // and as a lattice branch ref — collapses to one entry instead of being
  // double-counted under two different name namespaces.
  //
  // Sources:
  //  - `plan.sourceWorktree` / `task.worktree`: worktrees explicitly tied to this
  //    PRD's work (assignment events) — relevant regardless of ahead-status, so a
  //    fresh/undiverged worktree still surfaces.
  //  - per-ref lattice (`statusByRef`, ADR-0007): pure git, reflecting commits on
  //    a worktree branch. Two filters, both learned the hard way: require
  //    `isWorktree` (a stale non-worktree branch like `backup/pre-rebase-*` is
  //    also ahead of main) AND strictly-ahead-of-launch (every worktree descends
  //    from main, so a task done on the launch ref reads "completed" on every
  //    worktree column too).
  const worktreeBranches = useMemo(
    () => deriveWorktreeBranches((plan.features ?? []).flatMap((f) => f.tasks ?? []), plan.sourceWorktree),
    [plan.sourceWorktree, plan.features],
  );

  // Calculate progress from tasks (same logic as PlanDetailsPRD)
  // This ensures sidebar and detailed view are always in sync
  const progress = useMemo(() => {
    const features = plan.features || [];
    const totalTasks = features.reduce((acc, feature) => acc + (feature.tasks?.length || 0), 0);
    // Count by WORKTREE-AWARE effective status so work completed on a worktree
    // counts toward progress (not just commits landed on the launch ref).
    const allTasks = features.flatMap((feature) => feature.tasks ?? []);
    const doneTasks = allTasks
      .map((task) => deriveEffectiveStatus(task).status)
      .filter((s) => s === 'completed' || s === 'superseded').length;

    return totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  }, [plan.features]);

  // Calculate feature count from features array or metadata
  const featureCount = plan.features?.length ?? plan.metadata?.totalFeatures ?? plan.featureCount ?? 0;

  // Roll the card status up from WORKTREE-EFFECTIVE task statuses, reusing
  // FixCard's toEffectiveTask: it promotes a started-but-uncommitted task
  // (derivedState.redStartedAt, no commit) from not_started → in_progress, so a
  // pre-commit red start on the live telemetry feed reads as in-progress here —
  // not just once a commit lands. progress (completed-only) can't see a started
  // task, so without this the card lags the already-live fix sidebar.
  const effectiveStatus = useMemo(() => {
    const allTasks = (plan.features ?? []).flatMap((f) => f.tasks ?? []);
    return allTasks.length > 0 ? rollUpEffectiveStatuses(allTasks.map((t) => toEffectiveTask(t).status)) : plan.status;
  }, [plan.features, plan.status]);

  const isComplete = progress === 100;
  // In progress when any task is effectively started (incl. pre-commit red) or
  // when the launch-ref plan.status says so. (A `progress > 0` clause would be
  // redundant: progress is task-derived, so any completed task already makes
  // effectiveStatus in_progress — or, if every task is terminal, isComplete.)
  const isInProgress = !isComplete && (effectiveStatus === 'in_progress' || plan.status === 'in_progress');
  const isArchived = plan.type === 'archived';

  const variant: StatusVariant = isComplete ? 'done' : isInProgress ? 'in-progress' : 'not-started';
  // The pink→blue progress bar appears whenever there's progress to show — i.e.
  // for active and completed work. A not-started plan shows just its pill.
  const showProgress = isComplete || isInProgress;
  // The blue left accent marks the current SELECTION (not in-progress status);
  // the `.plan-card-surface` hover rules also light it (and the border) on hover.

  return (
    <SidebarCard
      testId={isArchived ? 'archived-card' : 'plan-card'}
      status={variant}
      isSelected={isSelected}
      isArchived={isArchived}
      emphasized={isInProgress || isSelected}
      onClick={onClick}
      title={planName}
      titleAside={cardTitleMarkers({ hasAssets: plan.hasAssets, assetCount: plan.assetCount, isArchived })}
      pills={<StatusPill variant={variant} label={isComplete ? 'Completed' : undefined} />}
      // Glance-only on the card — acting on the worktree is the detail header.
      // A PRD aggregates many tasks, so it reads as interactive/local work here.
      rail={<MiniStatusRail mode="card" branches={worktreeBranches} isWorkerRun={false} where="local" />}
      progress={showProgress ? progress : null}
      metaLeft={
        <>
          {featureCount} <span className="font-sans">{featureCount === 1 ? 'feature' : 'features'}</span>
          {showProgress && (
            <>
              {' · '}
              <span className="mono">{progress}%</span> <span className="font-sans">complete</span>
            </>
          )}
        </>
      }
      metaRight={updatedDate}
    />
  );
};

export default PlanCard;