import type { ListStatus } from '@/components/ListStatusFilter';
import type { Fix, Plan } from '../types';
import { deriveFixEffectiveStatus, derivePlanEffectiveStatus } from './effective-task';
import { deriveEffectiveStatus } from './effective-task-status';

/**
 * Sidebar list-filter categorisation (worktree-surface-consistency-pass task 4).
 *
 * Done-but-unlanded work would otherwise collapse to `completed` and vanish from
 * the default "active work" filter the moment its last task finished — even
 * though it still needs an action (landing on main). To keep such items both
 * visible AND filterable, `fixCategory` and `planCategory` map them to their own
 * `ready_to_land` category (a default-on pill); once landed they read `completed`
 * and drop out (opt-in to see).
 */

/** A resolved fix whose work hasn't reached main — a task explicitly not landed.
 *  The same signal FixCard's "not landed" pill uses, so the sidebar agrees with
 *  the card. */
export function isFixDoneButUnlanded(fix: Fix): boolean {
  const status = deriveFixEffectiveStatus(fix);
  const resolved = status === 'completed' || status === 'superseded';
  return resolved && fix.tasks.length > 0 && fix.tasks.some((t) => t.landed === false);
}

/** A completed PRD with work still terminal on a worktree ref strictly ahead of
 *  the launch ref — done on its worktree, not yet merged to main. Reads the
 *  per-ref lattice (via `deriveEffectiveStatus`'s `worktreeRef`), so a PRD whose
 *  work already mirrors main — or whose assigned worktree merely lingers — is
 *  NOT flagged. */
export function isPlanDoneButUnlanded(plan: Plan): boolean {
  if (derivePlanEffectiveStatus(plan) !== 'completed') return false;
  const tasks = (plan.features ?? []).flatMap((f) => f.tasks ?? []);
  return tasks.some((t) => {
    const { status, worktreeRef } = deriveEffectiveStatus(t);
    return worktreeRef !== undefined && (status === 'completed' || status === 'superseded');
  });
}

/** The sidebar list-filter category for a fix. Archived wins; a done-but-unlanded
 *  fix reads as its own `ready_to_land` category (still active work, but split
 *  out of in_progress) rather than dropping to completed. */
export function fixCategory(fix: Fix): ListStatus {
  if (fix.archived) return 'archived';
  const status = deriveFixEffectiveStatus(fix);
  if (status === 'completed' || status === 'superseded') {
    return isFixDoneButUnlanded(fix) ? 'ready_to_land' : 'completed';
  }
  return status === 'in_progress' ? 'in_progress' : 'not_started';
}

/** The sidebar list-filter category for a PRD; same archived-wins rule and
 *  `ready_to_land` carve-out for done-but-unlanded work as {@link fixCategory}. */
export function planCategory(plan: Plan): ListStatus {
  if (plan.type === 'archived') return 'archived';
  const status = derivePlanEffectiveStatus(plan);
  if (status === 'completed') {
    return isPlanDoneButUnlanded(plan) ? 'ready_to_land' : 'completed';
  }
  return status === 'in_progress' ? 'in_progress' : 'not_started';
}

/**
 * Default sidebar ordering rank: in-progress work first (0), then completed work
 * that's done-but-not-merged (1), then everything else (2). Callers break ties
 * within a rank by severity (fixes) or their own secondary key. Done-but-unlanded
 * is a SEPARATE band from in-progress here (unlike the filter category, which
 * merges them) so "ready to merge" reads as its own group at the top.
 */
export function fixSortRank(fix: Fix): number {
  if (deriveFixEffectiveStatus(fix) === 'in_progress') return 0;
  if (isFixDoneButUnlanded(fix)) return 1;
  return 2;
}

/** {@link fixSortRank} for PRDs. */
export function planSortRank(plan: Plan): number {
  if (derivePlanEffectiveStatus(plan) === 'in_progress') return 0;
  if (isPlanDoneButUnlanded(plan)) return 1;
  return 2;
}
