import type { Feature } from '../types';
import { StatReadout } from './ui';
import { derivePlanStats, featuresBuiltReadout, tasksResolvedReadout } from '../utils/plan-stats';

/**
 * The plan-detail stat readouts (plans-console): two recessed StatReadout cards
 * — "Features built" and "Tasks resolved" — each with a gradient progress bar,
 * percentage, and a done · skipped · left breakdown. Sits between the plan
 * header and the features list.
 */
export function PlanDetailStats({ features }: { features: readonly Feature[] }) {
  const counts = derivePlanStats(features);
  const built = featuresBuiltReadout(counts);
  const resolved = tasksResolvedReadout(counts);

  return (
    <div className="grid gap-3 sm:grid-cols-2">
      <StatReadout label="Features built" value={built.value} detail={built.detail} />
      <StatReadout label="Tasks resolved" value={resolved.value} detail={resolved.detail} />
    </div>
  );
}

export default PlanDetailStats;
