/**
 * Branch → contents derivation (delivery-convergence F10 /
 * worktree-keyed-merge-surface task 1). The PURE reducer behind the
 * worktree-keyed merge surface: given a branch and the tasks that carry a
 * per-ref status lattice, it answers "what is *completed on this branch*?" — the
 * PRD/feature(s)/fix(es) whose tasks read `completed` for this ref, grouped by
 * container.
 *
 * The merge unit is the BRANCH, never a feature (F10's reframe): interleaved
 * work on a shared branch lands together, so the row must show exactly what is
 * inside it. This derivation produces that label. It is lattice-sourced and
 * run-agnostic — the same basis the fix path uses — so interactive `tb go` work
 * (no `RunRecord`) is described just as readily as a worker run.
 *
 * No IO — the reader resolves each task's lattice + container identity from
 * git/markdown; this is the fixture-testable derivation the Done tab consumes.
 */
/**
 * Does the task count toward `branch`'s contents — completed on that ref's cell
 * AND not yet landed on the default branch? A landed task is reachable from a
 * fresh worktree (so its cell reads `completed`) but reads as inherited base
 * work, not what the branch still has to land, so it never contributes.
 */
function completedOnBranch(task, branch) {
    if (task.landed)
        return false;
    return task.statusByRef?.find((cell) => cell.ref === branch)?.status === 'completed';
}
/**
 * A one-line human label for a branch's contents (F10 task 4) — what the Done
 * row and the merge-island header show so you see exactly what will land, e.g.
 * `PRD delivery-convergence · features A, B · fix Y`. Each PRD contributes its id
 * (or title) plus a `feature`/`features` segment; each fix contributes a `fix`
 * segment. Empty contents yield `''` (the caller renders a fallback).
 */
export function worktreeContentsLabel(contents) {
    const parts = [];
    for (const prd of contents.prds) {
        parts.push(`PRD ${prd.title ?? prd.prd}`);
        const names = prd.features.map((f) => f.title ?? f.feature);
        if (names.length > 0)
            parts.push(`${names.length === 1 ? 'feature' : 'features'} ${names.join(', ')}`);
    }
    for (const fix of contents.fixes) {
        parts.push(`fix ${fix.title ?? fix.fix}`);
    }
    return parts.join(' · ');
}
/** Stable key for a task's container, used to total tasks across the input. */
function containerKey(container) {
    return container.kind === 'prd' ? `prd ${container.prd} ${container.feature}` : `fix ${container.fix}`;
}
export function deriveWorktreeContents(input) {
    const prds = new Map();
    const fixes = new Map();
    // Total tasks per container (every task, regardless of branch completion) — the
    // progress denominator. Read only for containers that surface (≥1 completed on
    // the branch); others are never emitted.
    const totals = new Map();
    for (const task of input.tasks) {
        totals.set(containerKey(task.container), (totals.get(containerKey(task.container)) ?? 0) + 1);
    }
    for (const task of input.tasks) {
        if (!completedOnBranch(task, input.branch))
            continue;
        const { container } = task;
        if (container.kind === 'prd') {
            const prd = prds.get(container.prd) ?? { title: container.prdTitle, features: new Map() };
            if (prd.title === undefined && container.prdTitle !== undefined)
                prd.title = container.prdTitle;
            const feature = prd.features.get(container.feature) ?? { title: container.featureTitle, completedTaskCount: 0 };
            if (feature.title === undefined && container.featureTitle !== undefined)
                feature.title = container.featureTitle;
            feature.completedTaskCount += 1;
            prd.features.set(container.feature, feature);
            prds.set(container.prd, prd);
        }
        else {
            const fix = fixes.get(container.fix) ?? { title: container.fixTitle, completedTaskCount: 0 };
            if (fix.title === undefined && container.fixTitle !== undefined)
                fix.title = container.fixTitle;
            fix.completedTaskCount += 1;
            fixes.set(container.fix, fix);
        }
    }
    return {
        prds: [...prds.entries()]
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([prd, acc]) => ({
            prd,
            ...(acc.title !== undefined ? { title: acc.title } : {}),
            features: [...acc.features.entries()]
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([feature, f]) => ({
                feature,
                ...(f.title !== undefined ? { title: f.title } : {}),
                completedTaskCount: f.completedTaskCount,
                // Every emitted container has ≥1 counted task, so the lookup is always
                // present; reuse containerKey so the write/read key format can't drift.
                totalTaskCount: totals.get(containerKey({ kind: 'prd', prd, feature })),
            })),
        })),
        fixes: [...fixes.entries()]
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([fix, acc]) => ({
            fix,
            ...(acc.title !== undefined ? { title: acc.title } : {}),
            completedTaskCount: acc.completedTaskCount,
            totalTaskCount: totals.get(containerKey({ kind: 'fix', fix })),
        })),
    };
}
