import { worktreeContentsLabel } from '@magic-ingredients/tiny-brain-core/worktree-contents';
import type { DeliveryWorktreeRow } from '@/services/api';
import { WorktreeMergeContent } from '@/components/WorktreeMergeContent';
import { useDeliveryActions } from '@/hooks/useDeliveryActions';
import { deliveryWorktreeStatus } from '@/utils/worktree-list-status';

export interface WorktreeMergeDetailProps {
  /** The repo the worktree belongs to (delivery actions post under it). */
  repoId: string;
  /** The selected worktree — its branch keys the delivery actions; its fields drive the surface. */
  worktree: DeliveryWorktreeRow;
  /** Called after a successful delivery action so the parent can refresh / re-derive the row. */
  onActionComplete?: () => void;
  /** Optional close affordance — the overlay passes it (header ✕); the inline detail pane omits it. */
  onClose?: () => void;
}

/** Human labels for the run's pipeline phases, streamed live into the running log. */
const PHASE_LABELS: Record<string, string> = {
  'render-worktree': 'Rendering delivery worktree…',
  'completion-gate': 'Replaying commits…',
  'land-to-main': 'Landing to main…',
  'worktree-remove': 'Removing worktree…',
  'branch-delete': 'Deleting branch…',
  'record-delete': 'Deleting run record…',
  // Reconcile ("Prepare to land") run phases — streamed into the staged control's log.
  reconcile: 'Reconciling onto main…',
  agent: 'Resolving residual conflicts…',
  verify: 'Verifying build + tests…',
};

/** Completed / total task counts summed across the worktree's contents — the Tasks vital + delivered count. */
function deriveTasks(contents: DeliveryWorktreeRow['contents']): { done: number; total: number } {
  let done = 0;
  let total = 0;
  for (const prd of contents.prds) {
    for (const feature of prd.features) {
      done += feature.completedTaskCount;
      total += feature.totalTaskCount ?? feature.completedTaskCount;
    }
  }
  for (const fix of contents.fixes) {
    done += fix.completedTaskCount;
    total += fix.totalTaskCount ?? fix.completedTaskCount;
  }
  return { done, total };
}

/**
 * The worktree merge surface as a worktree-in component: given a repo + a
 * {@link DeliveryWorktreeRow}, it derives the header/provenance/landing-strip/
 * clean-up sections ({@link WorktreeMergeContent}) and owns the delivery action
 * wiring ({@link useDeliveryActions}, keyed by branch). Container-agnostic — the
 * overlay mounts it inside `Island`, the two-pane Worktrees view mounts it
 * directly in the detail pane.
 */
export function WorktreeMergeDetail({ repoId, worktree, onActionComplete, onClose }: WorktreeMergeDetailProps) {
  const label = worktreeContentsLabel(worktree.contents);
  // An unmerged worktree may be DISCARDED — but NOT a spike, whose outcome lives
  // only on its branch until graduated (task 14 excludes spikes; task 15 owns
  // preservation). The content uses this to relax the clean-up gate; the hook uses
  // it to send the discard opt-in on the force path for the unmerged case.
  const nonSpike = worktree.kind !== 'spike';
  const actions = useDeliveryActions(repoId, worktree.branch, {
    onSuccess: onActionComplete,
    raiseTitle: `Deliver ${worktree.branch}`,
    raiseBody: label || `Deliver ${worktree.branch}`,
    discardable: nonSpike && worktree.acceptanceState === 'not-ready',
  });
  // The server-derived landingState only refetches on the reconcile's terminal
  // exit, so while a Prepare-to-land run is streaming we synthesize the `preparing`
  // phase from the in-flight runId (over the server base). This makes the strip show
  // live feedback mid-run; on exit `reconcileRunId` clears and the exit-refetch
  // brings the real terminal state (fix: landing-strip-no-live-feedback-during-reconcile).
  // Gated on the server base being present — it always is when a reconcile is in
  // flight (Prepare is only reachable from the staged control, which itself only
  // renders with a landingState), so a missing base degrades to the pass-through.
  const landingState =
    actions.reconcileRunId && worktree.landingState
      ? { ...worktree.landingState, phase: 'preparing' as const, reconcileRunId: actions.reconcileRunId }
      : worktree.landingState;
  return (
    <WorktreeMergeContent
      title={worktree.branch}
      contents={worktree.contents}
      acceptanceState={worktree.acceptanceState}
      mergeState={deliveryWorktreeStatus(worktree.status, worktree.acceptanceState)}
      isWorkerRun={worktree.isWorkerRun}
      provenance={worktree.provenance}
      runs={worktree.runs}
      tasks={deriveTasks(worktree.contents)}
      deliveredTasks={worktree.tasksDelivered}
      {...(worktree.unlandedCommits ? { unlandedCommits: worktree.unlandedCommits } : {})}
      {...(onClose ? { onClose } : {})}
      busy={actions.busy}
      landLog={actions.phases.map((p) => PHASE_LABELS[p.phase] ?? p.phase)}
      landError={actions.landError}
      {...(actions.landFailure ? { landFailure: actions.landFailure } : {})}
      cleanedUp={actions.cleanedUp}
      teardownError={actions.teardownError}
      {...(landingState ? { landingState } : {})}
      onLand={actions.onLand}
      onRaise={actions.onRaise}
      onReject={actions.onReject}
      onPrepare={actions.onPrepare}
      onRestore={actions.onRestore}
      onTeardown={actions.onTeardown}
      onForceTeardown={actions.onForceTeardown}
      allowDiscard={nonSpike}
    />
  );
}

export default WorktreeMergeDetail;
