import React from 'react';
import { BarChart3, Loader2, RefreshCw, Trash2 } from 'lucide-react';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { buildPostureSummary, type Vital } from '../utils/quality-posture';
import type { QualityScoresResponse, QualityRunSummary } from '../types';

interface QualityPostureHeaderProps {
  data: QualityScoresResponse | null;
  analysedAt?: string;
  selectedRun?: QualityRunSummary | null;
  onRunQuality?: () => void;
  onDeleteRun?: () => void;
  isRunning?: boolean;
  hasClaudeCli?: boolean;
  isApiKeyLoading?: boolean;
}

function VitalChip({ vital }: { vital: Vital }) {
  return (
    <span
      data-testid={`vital-${vital.key}`}
      data-state={vital.state}
      className="vital seg"
    >
      <span className={`dot d-${vital.state}`} aria-hidden />
      <span className="text-xs text-muted-foreground">{vital.label}</span>
      <span className="mono text-xs font-semibold text-foreground">{vital.value}</span>
    </span>
  );
}

function RunButton({
  onRunQuality,
  isRunning,
  hasClaudeCli,
  label,
  icon,
}: {
  onRunQuality: () => void;
  isRunning: boolean;
  hasClaudeCli: boolean;
  label: string;
  icon: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span>
          {/* Filled, raised treatment matching the repo Settings control — a
              `bg-background` surface (dark in dark mode) with border + shadow, so
              the button reads as a control against the elevated posture panel. */}
          <button
            type="button"
            onClick={onRunQuality}
            disabled={!hasClaudeCli || isRunning}
            data-testid="run-quality-button"
            className="flex items-center gap-2 rounded-lg border border-border bg-background px-3 py-2 text-sm font-medium text-foreground shadow-sm transition-colors hover:bg-foreground/[0.04] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {isRunning ? <Loader2 className="h-4 w-4 animate-spin" /> : icon}
            {isRunning ? 'Running...' : label}
          </button>
        </span>
      </TooltipTrigger>
      {!hasClaudeCli && (
        <TooltipContent>
          Claude CLI required - use the /quality skill in Claude Code instead
        </TooltipContent>
      )}
    </Tooltip>
  );
}

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

/**
 * The Quality "signals" posture header — a plain-language sentence naming what
 * is solid and the sharpest open risk, plus a vitals strip, on the reimagined
 * elevated `panel` surface. Replaces the old `N/total criteria passing` verdict,
 * grade pill and fill-to-100 readiness bar: there is no single score here.
 */
export const QualityPostureHeader: React.FC<QualityPostureHeaderProps> = ({
  data,
  analysedAt,
  selectedRun,
  onRunQuality,
  onDeleteRun,
  isRunning = false,
  hasClaudeCli = false,
  isApiKeyLoading = false,
}) => {
  if (!data) {
    return (
      <div data-testid="quality-posture-header" className="panel rounded-2xl p-6">
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">Not assessed</div>
          {!isApiKeyLoading && onRunQuality && (
            <RunButton
              onRunQuality={onRunQuality}
              isRunning={isRunning}
              hasClaudeCli={hasClaudeCli}
              label="Run Quality Analysis"
              icon={<BarChart3 className="h-4 w-4" />}
            />
          )}
        </div>
      </div>
    );
  }

  const summary = buildPostureSummary(data, { analysedAt });

  return (
    <div data-testid="quality-posture-header" className="panel rounded-2xl p-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="eyebrow text-[10px] text-subtle">
            <span className="text-blue">QUALITY</span>
            {analysedAt ? ` · analysed ${analysedAt}` : ''}
          </p>
          <h1
            data-testid="quality-posture-headline"
            className="display mt-2 max-w-3xl text-2xl font-bold leading-snug"
          >
            {summary.headline}
          </h1>
          <p data-testid="quality-posture-detail" className="mt-1.5 max-w-3xl text-sm text-muted-foreground">
            {summary.detail}
          </p>
        </div>
        {!isApiKeyLoading && onRunQuality && (
          <div className="shrink-0">
            <RunButton
              onRunQuality={onRunQuality}
              isRunning={isRunning}
              hasClaudeCli={hasClaudeCli}
              label="Re-run analysis"
              icon={<RefreshCw className="h-4 w-4" />}
            />
          </div>
        )}
      </div>

      <div data-testid="quality-vitals-strip" className="mt-5 flex flex-wrap gap-2">
        {summary.vitals.map((vital) => (
          <VitalChip key={vital.key} vital={vital} />
        ))}
      </div>

      {selectedRun && (
        <div className="mt-4 flex items-center justify-between" data-testid="selected-run-info">
          <span className="text-sm font-medium text-foreground">{formatDate(selectedRun.date)}</span>
          {onDeleteRun && (
            <button
              onClick={onDeleteRun}
              className="text-subtle transition-colors hover:text-red-500 dark:hover:text-red-400"
              title="Delete this quality run"
              data-testid="delete-run-button"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          )}
        </div>
      )}
    </div>
  );
};
