import type { HTMLAttributes } from 'react';
import { cn } from '@/lib/utils';
import { PanelFlat } from './Panel';
import { GradientProgress } from './GradientProgress';

export interface StatReadoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Eyebrow label, e.g. "Features built". */
  label: string;
  /** Optional right-aligned breakdown, e.g. "3 done · 17 skipped · 8 left". */
  detail?: string;
  /** Completion percentage (0–100); drives the bar and the readout. */
  value: number;
}

/**
 * The stat-readout card from the UI Refresh design system: a recessed panel-flat
 * surface with an eyebrow label + optional detail, a pink→blue gradient bar, and
 * a mono percentage. Composes the Panel and GradientProgress primitives.
 */
export function StatReadout({ label, detail, value, className, ...rest }: StatReadoutProps) {
  const pct = Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 0;
  return (
    <PanelFlat className={cn('rounded-2xl p-5', className)} {...rest}>
      <div className="flex items-center justify-between">
        <p className="eyebrow text-[10px] text-subtle">{label}</p>
        {detail ? (
          <span data-testid="stat-readout-detail" className="mono text-xs text-muted-foreground">
            {detail}
          </span>
        ) : null}
      </div>
      <div className="mt-3 flex items-center gap-3">
        {/* Feed the already-clamped value so the bar and the label can't diverge. */}
        <GradientProgress value={pct} className="flex-1" />
        <span className="mono text-sm font-semibold text-blue">{Math.round(pct)}%</span>
      </div>
    </PanelFlat>
  );
}

export default StatReadout;
