import React from 'react';
import { Loader2, AlertCircle, CheckCircle, Wrench } from 'lucide-react';
import { PanelFlat } from './ui/Panel';
import { useRunStream } from '../hooks/useRunStream';
import { deriveRunActivity } from '../utils/run-activity';

interface WorkerRunActivityProps {
  repoId: string;
  runId: string;
}

/**
 * Inline live activity for a worker run (ADR-0017, stream-worker-runs Task 2).
 * Subscribes to the per-run SSE bridge through {@link useRunStream}, folds the
 * `RunEvent`s with {@link deriveRunActivity}, and renders assistant text, tool
 * calls, pipeline phases and commits as they arrive.
 *
 * Liveness ONLY: the live marker follows the stream (connected and not yet
 * exited); the run's *status* is deliberately never rendered here. The `exit`
 * event is a fetch trigger, not a completion — status settles via the
 * git-fetch projection (the fix's own status), so this view can never
 * contradict it. Marker animates, fetch confirms.
 */
const WorkerRunActivity: React.FC<WorkerRunActivityProps> = ({ repoId, runId }) => {
  const { events, connected, error } = useRunStream(repoId, runId);
  const activity = deriveRunActivity(events);
  const live = connected && !activity.exited;

  return (
    <PanelFlat data-testid="worker-run-activity" className="rounded-2xl p-5 space-y-4">
      <div className="flex items-center justify-between">
        <p className="eyebrow text-[10px] text-subtle">Live activity</p>
        {live && (
          <span
            data-testid="worker-run-live"
            className="inline-flex items-center gap-1.5 text-[11px] font-medium text-blue"
          >
            <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden="true" />
            Running
          </span>
        )}
      </div>

      {error && (
        <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-900/20">
          <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0 text-red-500" aria-hidden="true" />
          <div className="text-sm text-red-700 dark:text-red-300">{error}</div>
        </div>
      )}

      {activity.phases.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {activity.phases.map((p, i) => (
            <span
              key={i}
              title={`task ${p.taskId}`}
              className="mono inline-flex items-center rounded-md border border-border-strong px-2 py-0.5 text-[11px] text-muted-foreground"
            >
              {p.phase}
            </span>
          ))}
        </div>
      )}

      <div className="max-h-[360px] overflow-y-auto rounded-lg bg-muted/40 p-4">
        {activity.output ? (
          <pre className="mono whitespace-pre-wrap text-sm text-foreground">{activity.output}</pre>
        ) : (
          <p className="text-sm italic text-muted-foreground">
            {live ? 'Waiting for activity…' : 'No activity yet'}
          </p>
        )}
      </div>

      {activity.toolCalls.length > 0 && (
        <div className="overflow-hidden rounded-lg border border-border">
          <div className="flex items-center gap-2 border-b border-border bg-muted/40 px-3 py-2">
            <Wrench className="h-3.5 w-3.5 text-subtle" aria-hidden="true" />
            <span className="text-xs font-medium text-foreground">Tool calls</span>
            <span className="text-xs text-subtle">({activity.toolCalls.length})</span>
          </div>
          <div className="divide-y divide-border">
            {activity.toolCalls.map((call, i) => {
              // input is `unknown`; JSON.stringify(undefined) is `undefined`, so
              // coalesce before slicing or the row crashes the whole view.
              const inputPreview = JSON.stringify(call.input) ?? '';
              return (
                // Index key (not call.id): the list is append-only and order-
                // stable, and id is absent until the result lands — keying on it
                // would remount the row on resolution.
                <div key={i} className="flex items-start gap-2 px-3 py-2">
                  <span className="mt-0.5 flex-shrink-0">
                    {call.result ? (
                      call.result.success ? (
                        <CheckCircle className="h-3.5 w-3.5 text-green-500" aria-hidden="true" />
                      ) : (
                        <AlertCircle className="h-3.5 w-3.5 text-red-500" aria-hidden="true" />
                      )
                    ) : (
                      <Loader2 className="h-3.5 w-3.5 animate-spin text-blue" aria-hidden="true" />
                    )}
                  </span>
                  <div className="min-w-0 flex-1">
                    <span className="mono text-sm text-foreground">{call.tool}</span>
                    <div className="mono mt-0.5 truncate text-xs text-subtle">
                      {inputPreview.slice(0, 100)}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {activity.commits.length > 0 && (
        <ul className="mono space-y-0.5 text-xs text-muted-foreground">
          {activity.commits.map((c, i) => (
            <li key={c.sha || i}>
              <span className="text-subtle">{c.prefix}</span> {c.sha.slice(0, 9)}
            </li>
          ))}
        </ul>
      )}
    </PanelFlat>
  );
};

export default WorkerRunActivity;
