import type { SpikeWorktreeStatus, Worktree } from '@magic-ingredients/tiny-brain-core';

/**
 * Browser-safe mirror of
 * `packages/tiny-brain-core/src/services/worktree/spike-worktree-status.ts`.
 *
 * Lives here because core's main entry transitively pulls in
 * `child_process` / `fs` / `path` through `worktree-list.ts`, and Vite
 * refuses to bundle those for the browser. The pure logic is short
 * enough that duplicating it is cheaper than carving out a separate
 * browser-safe subpath export — but the duplication MUST be matched by
 * a contract test (see __tests__/spike-worktree-status.test.ts) so a
 * future change to either side fails loudly.
 */

const BRANCH_PREFIX = 'refs/heads/';

function normaliseBranch(branch: string): string {
  const trimmed = branch.trim();
  return trimmed.startsWith(BRANCH_PREFIX) ? trimmed.slice(BRANCH_PREFIX.length) : trimmed;
}

export function getSpikeWorktreeStatus(
  spikeWorktree: { name: string; branch: string } | undefined,
  allWorktrees: readonly Worktree[],
): SpikeWorktreeStatus {
  if (!spikeWorktree) return { kind: 'unconfigured' };
  const branch = normaliseBranch(spikeWorktree.branch);
  if (branch.length === 0) return { kind: 'orphaned', branch };
  const match = allWorktrees.find((w) => w.branch === branch);
  return match
    ? { kind: 'present', branch, path: match.path }
    : { kind: 'orphaned', branch };
}
