/**
 * Case-insensitive substring search across an item's searchable fields. An
 * empty / whitespace query matches everything (the search is "off"); otherwise
 * the item matches when ANY provided field contains the query. Undefined fields
 * are skipped. Used to filter the PRD/Fix/Spike lists by the shared search box.
 */
export function matchesSearch(query: string, ...fields: Array<string | undefined>): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return fields.some((field) => (field ?? '').toLowerCase().includes(q));
}
