import React from 'react';
import { Images } from 'lucide-react';

/**
 * Glance-only marker that a work item (PRD / fix) carries committed design
 * assets (surface-design-assets-in-dashboard F2). Sits in the sidebar card's
 * title-aside slot beside the archive marker. Non-interactive — opening the
 * assets view is the detail header's Assets link (F3); here it is pure signal.
 *
 * `role="img"` so the aria-label is reliably announced (a bare lucide <svg> is
 * not); the label carries the asset count when known.
 */
export const AssetsIndicator: React.FC<{ count?: number }> = ({ count }) => (
  <Images
    role="img"
    data-testid="assets-indicator"
    aria-label={count ? `${count} design asset${count === 1 ? '' : 's'}` : 'Has design assets'}
    className="h-3.5 w-3.5 text-muted-foreground"
  />
);
