import { useCallback, useEffect, useState } from 'react';
import type { AcceptanceState, WorkRef } from '@magic-ingredients/tiny-brain-core';

/**
 * The in-flight wire contract, mirroring the server's `InFlightRow` / lanes in
 * `server/routes/in-flight.projection.ts`. Deliberately re-declared client-side
 * (like `RunListRow` in {@link useRepoRuns}): the client tsconfig excludes
 * `server/`, so the two are kept in sync by hand rather than imported across the
 * build boundary. Shared leaf types (`WorkRef`, `AcceptanceState`) come from the
 * core package both sides depend on, so those cannot drift.
 */
export type InFlightLane = 'in-progress' | 'ready-to-land' | 'failed' | 'ready-to-clean';

/** How a deliverable is being delivered — the mechanism badge (mirrors the server contract). */
export type InFlightMechanism =
  | { kind: 'worker'; location: 'local' | 'remote'; model: string }
  | { kind: 'worktree'; isWorkerRun: boolean };

/** One deliverable in flight, as the in-flight route returns it. */
export interface InFlightRow {
  lane: InFlightLane;
  workRef?: WorkRef;
  title?: string;
  mechanism: InFlightMechanism;
  status: string;
  branch?: string;
  runId?: string;
  live?: boolean;
  resumable?: boolean;
  failureClass?: 'transient' | 'permanent';
  exitReason?: string;
  acceptanceState?: AcceptanceState;
}

export interface InFlightLanes {
  inProgress: InFlightRow[];
  readyToLand: InFlightRow[];
  failed: InFlightRow[];
  readyToClean: InFlightRow[];
}

export interface UseInFlightResult {
  lanes: InFlightLanes;
  loading: boolean;
  error: string | null;
  refresh: () => void;
}

const EMPTY: InFlightLanes = { inProgress: [], readyToLand: [], failed: [], readyToClean: [] };

/**
 * Load the repo's in-flight board — the four job lanes from
 * `GET /api/repos/:repoId/in-flight`. Mirrors {@link useRepoRuns}: a direct
 * fetch with an `isActive` cancel guard so a resolve after unmount never sets
 * state. Read-only — the board's actions live in the surfaces a row opens.
 */
export function useInFlight(repoId: string | null): UseInFlightResult {
  const [lanes, setLanes] = useState<InFlightLanes>(EMPTY);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(
    async (isActive: () => boolean = () => true) => {
      if (!repoId) {
        if (isActive()) {
          setLanes(EMPTY);
          setError(null);
          setLoading(false);
        }
        return;
      }
      try {
        const res = await fetch(`/api/repos/${encodeURIComponent(repoId)}/in-flight`);
        if (!res.ok) {
          if (isActive()) {
            setError(`Failed to load in-flight board (HTTP ${res.status})`);
            setLanes(EMPTY);
          }
          return;
        }
        const data = (await res.json()) as Partial<InFlightLanes>;
        if (isActive()) {
          setLanes({
            inProgress: data.inProgress ?? [],
            readyToLand: data.readyToLand ?? [],
            failed: data.failed ?? [],
            readyToClean: data.readyToClean ?? [],
          });
          setError(null);
        }
      } catch (err) {
        if (isActive()) {
          setError(err instanceof Error ? err.message : 'Failed to load in-flight board');
          setLanes(EMPTY);
        }
      } finally {
        if (isActive()) setLoading(false);
      }
    },
    [repoId],
  );

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void load(() => !cancelled);
    return () => {
      cancelled = true;
    };
  }, [load]);

  const refresh = useCallback(() => {
    void load();
  }, [load]);

  return { lanes, loading, error, refresh };
}
