import React, { createContext, useContext, useState, useCallback } from 'react';

export interface CurrentRepoInfo {
  id: string;
  name: string;
  path: string;
  contextFile?: string;
  lastAnalyzed?: string;
}

interface CurrentRepoContextValue {
  repo: CurrentRepoInfo | null;
  setRepo: (repo: CurrentRepoInfo | null) => void;
}

const CurrentRepoContext = createContext<CurrentRepoContextValue>({
  repo: null,
  setRepo: () => {},
});

export const useCurrentRepo = (): CurrentRepoContextValue => useContext(CurrentRepoContext);

export const CurrentRepoProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [repo, setRepoState] = useState<CurrentRepoInfo | null>(null);
  const setRepo = useCallback((next: CurrentRepoInfo | null) => setRepoState(next), []);
  return (
    <CurrentRepoContext.Provider value={{ repo, setRepo }}>
      {children}
    </CurrentRepoContext.Provider>
  );
};
