import React, { useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import type { Plan } from '@/types';
import { ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';
import PlanDetailHeader, { planHeaderPropsFromPlan } from '@/components/PlanDetailHeader';
import { PlanDetailStats } from '@/components/PlanDetailStats';
import { PlanFeatureRow } from '@/components/PlanFeatureRow';
import { PipelineLegend } from '@/components/PipelineLegend';
import { usePipelineConfig } from '@/hooks/usePipelineConfig';
import { deriveFeatureEffectiveStatus } from '@/utils/effective-task-status';
import { deriveTasksEffectiveStatus, derivePlanEffectiveStatus } from '@/utils/effective-task';

interface PlanDetailsPRDProps {
  plan: Plan;
  repoId?: string;
  /** Archive/unarchive the plan — wired to the header action. */
  onArchive?: () => void;
  onUnarchive?: () => void;
  /** Open the WorkerRun island for a feature's live run (rail pill click). */
  onOpenRun?: (runId: string) => void;
}

// Per-plan storage for the feature accordion's open set. Feature open/closed is
// view-local layout — it lives in localStorage keyed by prdId, never the URL, so
// each PRD remembers its own open features across reloads.
const featuresStorageKey = (prdId: string | undefined): string | null =>
  prdId ? `tiny-brain:plan:${prdId}:expandedFeatures` : null;

const readExpandedFeatures = (prdId: string | undefined): Set<number> | null => {
  const key = featuresStorageKey(prdId);
  if (!key) return null;
  try {
    const raw = window.localStorage.getItem(key);
    if (raw === null) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? new Set(parsed.filter((n): n is number => typeof n === 'number'))
      : null;
  } catch {
    return null;
  }
};

const PlanDetailsPRD: React.FC<PlanDetailsPRDProps> = ({ plan, repoId, onArchive, onUnarchive, onOpenRun }) => {
  const [expandedFeatures, setExpandedFeatures] = useState<Set<number>>(
    () => readExpandedFeatures(plan.prdId) ?? new Set(),
  );
  const [supersededExpanded, setSupersededExpanded] = useState(false);
  const [, setSearchParams] = useSearchParams();

  // Open the design-assets view (surface-design-assets F3) as a mode of THIS
  // PRD — the PRD is already the selected item, so `?assets` is a bare marker;
  // the F4 view reads kind + slug from the active area + selected item. The
  // header shows the Assets action only when the PRD actually has assets.
  const openAssets = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('assets', '');
      return next;
    });
  };

  const persistExpanded = (next: Set<number>) => {
    const key = featuresStorageKey(plan.prdId);
    if (!key) return;
    try {
      window.localStorage.setItem(key, JSON.stringify([...next]));
    } catch {
      // Storage unavailable (private mode / quota) — open state just won't persist.
    }
  };

  const toggleFeature = (featureNumber: number) => {
    // Derive the next set from the current render's value (this is a user event
    // handler, so it's up to date) and keep the state updater pure — persistence
    // is a side effect that belongs outside it.
    const next = new Set(expandedFeatures);
    if (next.has(featureNumber)) {
      next.delete(featureNumber);
    } else {
      next.add(featureNumber);
    }
    setExpandedFeatures(next);
    persistExpanded(next);
  };

  // Extract features from plan
  const features = useMemo(() => plan.features || [], [plan.features]);

  // Superseded features are retired work — they belong in a collapsed section
  // below the active accordion, not interleaved with live features. "Superseded"
  // is the worktree-aware effective status (all tasks superseded), matching the
  // stat-readout rollup.
  const { activeFeatures, supersededFeatures } = useMemo(() => {
    const activeFeatures: typeof features = [];
    const supersededFeatures: typeof features = [];
    for (const feature of features) {
      // The launch-ref-only helper is correct HERE: the started-phase promotion
      // only ever turns not_started → in_progress, never affects a `superseded`
      // rollup, so it agrees with the pulse-aware deriveTasksEffectiveStatus for
      // this terminal check (which the auto-expand below does need).
      const bucket =
        deriveFeatureEffectiveStatus(feature.tasks ?? []) === 'superseded'
          ? supersededFeatures
          : activeFeatures;
      bucket.push(feature);
    }
    return { activeFeatures, supersededFeatures };
  }, [features]);

  // The active (in-progress) feature, derived once — it's both the auto-expand
  // target and the scroll target on load. Read the same worktree-aware effective
  // status the partition uses (not raw feature.status), and only look among
  // active features so a superseded feature is never chosen.
  const activeFeature = useMemo(
    () =>
      activeFeatures.find((f) => deriveTasksEffectiveStatus(f.tasks ?? []) === 'in_progress') ??
      null,
    [activeFeatures],
  );

  // Load the open set for this plan: a stored (user-chosen) set wins; otherwise
  // fall back to auto-expanding the active feature. Keyed on prdId so switching
  // plans re-syncs to the right stored set.
  React.useEffect(() => {
    const stored = readExpandedFeatures(plan.prdId);
    if (stored !== null) {
      setExpandedFeatures(stored);
      return;
    }
    setExpandedFeatures(activeFeature ? new Set([activeFeature.number]) : new Set());
  }, [plan.prdId, activeFeature]);

  // Scroll the active feature into view on load. Its expanded body holds the
  // current task, so `block: 'start'` lands the eye on the live work (not just
  // the row's edge) when resuming a deep route.
  const scrollTargetRef = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (activeFeature) {
      // Optional-chain the method too: jsdom (and SSR) have no scrollIntoView.
      scrollTargetRef.current?.scrollIntoView?.({ block: 'start', behavior: 'smooth' });
    }
  }, [activeFeature, plan.prdId]);

  // The configured review pipeline drives the Features-heading legend (and the
  // per-task chips inside FeatureDetail) — not a hardcoded Adversarial/Mutation
  // list.
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId || '');

  return (
    <div className="h-full flex flex-col">
      {/* The whole main section scrolls as one (consistent with FixDetail and
          SpikeDetail) — no fixed KPI rail, no collapse-on-scroll header. */}
      <div
        data-testid="plan-detail-scroll"
        className="flex-1 overflow-y-auto px-7 py-6 space-y-4"
      >
        {/* Plan detail header (UI Refresh): status eyebrow, title + copy-id, and
            the features/updated line carrying Archive. Lives inside the scroll
            region so the whole section scrolls as one (matching FixDetail). */}
        <PlanDetailHeader
          {...planHeaderPropsFromPlan(plan)}
          status={derivePlanEffectiveStatus(plan)}
          repoId={repoId}
          onArchive={onArchive}
          onUnarchive={onUnarchive}
          onOpenAssets={openAssets}
        />

        {/* Plan detail stat readouts (plans-console task 3): Features built /
            Tasks resolved, each with a gradient bar and done · skipped · left
            breakdown. */}
        <PlanDetailStats features={features} />

        {/* Features accordion (plans-console task 4). Each row is a
            PlanFeatureRow on the new design system; the per-task rows and their
            commit-pipeline timelines render in the expanded body. */}
        <div className="space-y-3">
          <div className="mt-8 flex flex-wrap items-center justify-between gap-2">
            <h3 className="display text-base font-semibold">Features</h3>
            <PipelineLegend pipeline={reviewPipeline} />
          </div>
          {activeFeatures.map((feature) => (
            // Transparent wrapper so the active row carries a scroll-target ref
            // without touching PlanFeatureRow's own styling.
            <div
              key={feature.id}
              ref={feature.number === activeFeature?.number ? scrollTargetRef : undefined}
            >
              <PlanFeatureRow
                feature={feature}
                repoId={repoId || ''}
                prdId={plan.prdId}
                expanded={expandedFeatures.has(feature.number)}
                onToggle={() => toggleFeature(feature.number)}
                onOpenRun={onOpenRun}
              />
            </div>
          ))}
        </div>

        {/* Superseded features (plans-console task 5) — retired work, collapsed
            by default so it doesn't compete with the live accordion. */}
        {supersededFeatures.length > 0 && (
          <div className="space-y-3">
            <button
              type="button"
              data-testid="superseded-features-toggle"
              onClick={() => setSupersededExpanded((v) => !v)}
              aria-expanded={supersededExpanded}
              className="flex w-full items-center gap-1.5 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
            >
              <ChevronRight
                className={cn('h-4 w-4 transition-transform', supersededExpanded && 'rotate-90')}
                aria-hidden="true"
              />
              Superseded features ({supersededFeatures.length})
            </button>
            {supersededExpanded && (
              <div className="space-y-3 opacity-70">
                {supersededFeatures.map((feature) => (
                  <PlanFeatureRow
                    key={feature.id}
                    feature={feature}
                    repoId={repoId || ''}
                    prdId={plan.prdId}
                    expanded={expandedFeatures.has(feature.number)}
                    onToggle={() => toggleFeature(feature.number)}
                  />
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default PlanDetailsPRD;
