import { useState, useEffect } from 'react';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { isPipelineStep, ADVERSARIAL_STEP } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';

const DEFAULT_PIPELINE: PipelineStep[] = [ADVERSARIAL_STEP];

interface PipelineConfig {
  pipeline: PipelineStep[];
}

export function usePipelineConfig(repoId: string): PipelineConfig {
  const [pipeline, setPipeline] = useState<PipelineStep[]>(DEFAULT_PIPELINE);

  useEffect(() => {
    // Fetch pipeline config — API returns PipelineStep[] objects
    fetch(`/api/repos/${repoId}/pipeline`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (data?.pipeline && Array.isArray(data.pipeline)) {
          const validated = data.pipeline.filter(isPipelineStep);
          setPipeline(validated);
        }
      })
      .catch(() => {});
  }, [repoId]);

  return { pipeline };
}
