import { WorktreeMergeIsland } from './WorktreeMergeIsland';

export interface SpikeCleanupIslandProps {
  /** The spike's title — shown in the island header. */
  spikeTitle: string;
  /** The spike worktree's branch — the teardown target (used once the backend
   *  action is wired; the spike doc itself is kept). */
  branch: string;
  open: boolean;
  onClose: () => void;
}

/**
 * The spike clean-up surface (worktree-surface-consistency-pass): the shared
 * worktree-merge island in TEARDOWN-ONLY mode. A finished spike has nothing to
 * land/raise/reject — the only action is tearing down its worktree, while the
 * spike doc and its findings are kept.
 *
 * NOTE: the teardown ACTION is not yet implemented. Spike teardown is not just
 * deleting a worktree — the spike record is preserved (so its findings stay
 * readable) and only the worktree/branch is removed. Until that backend exists,
 * the button is present but the action is a no-op that simply closes.
 */
export function SpikeCleanupIsland({ spikeTitle, branch, open, onClose }: SpikeCleanupIslandProps) {
  return (
    <WorktreeMergeIsland
      open={open}
      onClose={onClose}
      title={spikeTitle}
      acceptanceState="not-ready"
      // A spike reaching this island is finished — the only action is teardown —
      // so the header reads ready-to-clean (non-pulsing), not a live "in progress".
      mergeState="ready-to-clean"
      isWorkerRun={false}
      teardownOnly
      onLand={() => {}}
      onRaise={() => {}}
      onReject={() => {}}
      onTeardown={() => {
        // TODO(spike-teardown): wire the real action — delete the worktree at
        // `branch` while KEEPING the spike doc. Stubbed for now.
        void branch;
        onClose();
      }}
    />
  );
}

export default SpikeCleanupIsland;
