import type { GroupedPersonasData, LibraryPersona, CheckResult, Notification } from '../types';

const API_BASE = '/api';

/** Read-only system-health snapshot returned by `GET /api/system/doctor`. */
export interface SystemDoctorResult {
  checks: CheckResult[];
}

export async function getSystemDoctor(): Promise<SystemDoctorResult> {
  const response = await fetch(`${API_BASE}/system/doctor`);
  if (!response.ok) {
    const detail = (await response.json().catch(() => null)) as { error?: unknown } | null;
    const reason =
      detail && typeof detail.error === 'string' ? detail.error : `HTTP ${response.status}`;
    throw new Error(reason);
  }
  return response.json();
}

/** Read-only notifications snapshot returned by `GET /api/system/notifications`. */
export interface SystemNotificationsResult {
  notifications: Notification[];
}

export async function getSystemNotifications(): Promise<SystemNotificationsResult> {
  const response = await fetch(`${API_BASE}/system/notifications`);
  if (!response.ok) {
    const detail = (await response.json().catch(() => null)) as { error?: unknown } | null;
    const reason =
      detail && typeof detail.error === 'string' ? detail.error : `HTTP ${response.status}`;
    throw new Error(reason);
  }
  return response.json();
}

