// Design-asset APIs (surface-design-assets-in-dashboard F4).
export type AssetItemKind = 'prd' | 'fix';
export type AssetFileKind = 'html' | 'image' | 'other';

export interface AssetFile {
  name: string;
  size: number;
  kind: AssetFileKind;
}

export interface AssetListingResult {
  assets: AssetFile[];
}

/** List an item's design assets via `GET /api/repos/:repoId/assets/:kind/:slug`. */
export async function fetchAssets(
  repoId: string,
  kind: AssetItemKind,
  slug: string,
): Promise<AssetListingResult> {
  const response = await fetch(`${API_BASE}/repos/${repoId}/assets/${kind}/${encodeURIComponent(slug)}`);
  if (!response.ok) {
    const detail = (await response.json().catch(() => null)) as { error?: unknown } | null;
    const reason = detail && typeof detail.error === 'string' ? detail.error : `HTTP ${response.status}`;
    throw new Error(reason);
  }
  return response.json();
}

/**
 * URL of a single asset file's bytes (`GET .../assets/:kind/:slug/file/:name`).
 * The server serves it CSP-sandboxed + nosniff, so it is safe to load into a
 * sandboxed iframe (HTML) or an <img> (images), and to open in a new tab.
 */
export function assetFileUrl(repoId: string, kind: AssetItemKind, slug: string, name: string): string {
  return `${API_BASE}/repos/${repoId}/assets/${kind}/${encodeURIComponent(slug)}/file/${encodeURIComponent(name)}`;
}

