import { useEffect, useState } from 'react';
import type { RunRecord } from '@magic-ingredients/tiny-brain-core';

/**
 * Client view of a single run's detail, as `GET /api/repos/:repoId/runs/:runId`
 * returns it (the T1 run-detail contract): the record itself, its derived
 * on-disk worktree path (`null` for a non-worktree branch), and the
 * parent/retry chain walked from `parentRunId` (immediate parent first).
 */
export interface RunDetailView {
  record: RunRecord;
  worktreePath: string | null;
  history: RunRecord[];
}

export interface UseRunDetailResult {
  detail: RunDetailView | null;
  loading: boolean;
  error: string | null;
}

/**
 * Fetch a run's vitals for the WorkerRun island. A one-shot read on mount /
 * when the run changes — the *live* activity comes from `useRunStream`, so
 * this never polls; it supplies the settled vitals (worker, model, target,
 * workRef, worktree) that survive navigation because they're read from the
 * run record, not the ephemeral dispatch.
 */
export function useRunDetail(repoId: string, runId: string): UseRunDetailResult {
  const [detail, setDetail] = useState<RunDetailView | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const res = await fetch(
          `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}`,
        );
        if (!res.ok) {
          if (!cancelled) {
            setError(`Failed to load run (HTTP ${res.status})`);
            setDetail(null);
          }
          return;
        }
        const data = (await res.json()) as RunDetailView;
        if (!cancelled) {
          setDetail(data);
          setError(null);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load run');
          setDetail(null);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [repoId, runId]);

  return { detail, loading, error };
}
