import { useState, useEffect } from 'react';
import { useLocation, useNavigate, Navigate } from 'react-router-dom';
import { Layout } from './components/layout/Layout';
import {
  buildSidebarSections,
  selectedViewForPath,
  defaultViewPath,
  personaCountFromResponse,
  navPathForItem,
} from './components/layout/sidebarSections';
import { AppRoutes } from './AppRoutes';
import { StarredReposSection } from './components/layout/StarredReposSection';
import { usePersona } from './hooks/usePersona';
import { useSSE } from './hooks/useSSE';
import { useRouteMemory } from './hooks/useRouteMemory';

function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const { currentPersona, updatePersona } = usePersona();
  const sseState = useSSE();

  // Mirror the route to localStorage and resume it on a bare-root landing.
  useRouteMemory();
  
  // Derive selectedView from current route. A repo detail page
  // (/repos/<id>) does NOT highlight the parent "Repos" sidebar
  // item — the starred-repo sub-item under Repos owns the selection
  // visual instead. Plain /repos still highlights the parent.
  const getSelectedView = () => selectedViewForPath(location.pathname);
  
  const [selectedView, setSelectedView] = useState<string | null>(getSelectedView());
  
  // Update selectedView when route changes
  useEffect(() => {
    setSelectedView(getSelectedView());
  }, [location.pathname]);

  // Update persona when SSE reports a change
  useEffect(() => {
    if (sseState.personaId && sseState.personaId !== currentPersona) {
      console.log('[SSE] Persona changed to:', sseState.personaId);
      updatePersona(sseState.personaId);
    }
  }, [sseState.personaId, currentPersona, updatePersona]);

  // Persona count drives whether the Personas nav item is worth showing — with
  // just the default `developer` persona there's nothing to switch to. undefined
  // while loading (the item stays until we know, to avoid a flicker).
  const [personaCount, setPersonaCount] = useState<number | undefined>(undefined);
  useEffect(() => {
    let cancelled = false;
    fetch('/api/personas')
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (!cancelled) setPersonaCount(personaCountFromResponse(data));
      })
      .catch(() => {
        // On a failed fetch, resolve to a concrete count so the root/catch-all
        // redirect lands on the always-present Repos rather than a blank pane.
        if (!cancelled) setPersonaCount(0);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Define sidebar sections with items (see components/layout/sidebarSections).
  const sidebarSections = buildSidebarSections({ personaCount });

  const handleItemSelect = (itemId: string) => {
    setSelectedView(itemId);
    const path = navPathForItem(itemId);
    if (path) navigate(path);
  };

  // The bare-root and catch-all redirects wait for the persona count so they land
  // on Repos (not the now-hidden Personas) when there's a single persona; null
  // renders nothing until known.
  const landing = personaCount === undefined ? null : <Navigate to={defaultViewPath(personaCount)} replace />;

  return (
    <Layout
      sidebarSections={sidebarSections}
      selectedItemId={selectedView}
      onItemSelect={handleItemSelect}
      renderAfterSidebarItem={(itemId) => itemId === 'repos' ? <StarredReposSection /> : null}
      onSettingsSelect={() => handleItemSelect('settings')}
      isSettingsSelected={selectedView === 'settings'}
      activeSectionItemId={location.pathname.startsWith('/repos/') ? 'repos' : null}
    >
      <AppRoutes landing={landing} />
    </Layout>
  );
}

export default App;